COLLDATA("asabahur","ur",[[907,"§۹۰۷ ۔ ثابت بن مسعود\nآخری قسم میں ان کا تذکرہ آئے گا۔"],[908,"§۹۰۸ ۔ ثابت بن نعمان بن امیہ\nبقول بعض یہ ابو حبہ بدری کا نام ہے۔"],[909,"§۹۰۹ ۔ ثابت بن نعمان(1)\nبن امیہ بن امری القیس بن ثعلبہ بن عمرو بن عوف بن مالک بن اوس، ابو حبہ کنیت تھی۔ بقول ابن البرقی اور ابن یونس فتح مصر میں شریک تھے۔ یہ وہ بدری نہیں ہیں وہ کلثمہ بن ثعلبہ بن عمرو بن عوف کے بیٹے ہیں جس پر علماء کا اتفاق ہے۔ ابن مندہ کو وہم ہوا انہوں نے دونوں کو ایک بنا دیا۔ ادھر ابن اسحاق نے ابو الصباح ثابت بن نعمان کو شہدائے اُحد میں ذکر کیا اور بعینہ یہ نسب وہاں بیان کیا ہے، اس لحاظ سے ان کے والد ان کے بعد کافی عرصہ زندہ رہے۔","",{"fn":"(1) اسد الغابۃ (۵۷۵) تجرید (۶۵/۱)"}],[910,"§۹۱۰ ۔ ثابت بن نعمان(1)\nبن حارث بن زراح بن ظفر انصاری ظفری، ابن شاہین نے سابقہ سند کے ذریعہ ان کا ذکر کیا ہے۔ بقول قداح، احد اور بعد کے غزوات میں شرکت کی۔ البتہ عدوی نے یہ اضافہ نقل کیا ہے کہ جسر ابی عبیدہ کے روز شہید ہوئے۔ ابو موسیٰ نے ان کا استدراک کیا ہے۔(2)","",{"fn":"(1) اسد الغابۃ (۵۷۶) الاستيعاب (۲۶۸)\n(2) السیرۃ النبویۃ (۹۶/۳)"}],[911,"§۹۱۱ ۔ ثابت بن نعمان(1)\nبن زید بن عامر بن سواد بن ظفر بن ظفری انصاری ظفری۔ ان کا بھی ابن شاہین(2) نے تذکرہ کیا ہے۔ ابو موسیٰ نے کہا: میرے خیال میں یہ پہلے والے نہیں۔ جبکہ ابن الاثیر(3) نے اس کا ردّ کیا ہے۔ اسی طرح ابو عمر نے ان دونوں میں فرق کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۵۷۷) الاستيعاب (۲۵۶)\n(2) السیرۃ النبویۃ (۹۶/۳)\n(3) اسد الغابۃ (۲۶۷/۱)"}],[912,"§۹۱۲ ۔ ثابت بن ہزال(1)\nبن عمرو بن عمر بن قربوس بن لوذان بن سالم بن عوف انصاری۔ موسیٰ بن عقبہ ان کا شرکائے بدر اور شہدائے یمامہ(2) میں تذکرہ کیا ہے اور ابن عبد البر(3) نے ذکر کیا کہ وہ بنی عمرو بن عوف کے فرد ہیں۔","",{"fn":"(1) اسد الغابۃ (۵۷۸) الاستيعاب (۲۴۶) تجرید (۶۵/۱)\n(2) المعجم الکبیر (۱۳۵۹/۲) معرفۃ الصحابۃ (۲۳۵/۳) اسد الغابۃ (۲۶۸/۱)\n(3) الاستيعاب (۲۷۴/۱)"}],[913,"§۹۱۳ ۔ ثابت بن ودیعہ(1)\nابن یزید میں تذکرہ آئے گا۔","",{"fn":"(1) اسد الغابۃ (۵۸۰) الاستيعاب (۲۶۳) تجرید (۶۵/۱)"}],[914,"§۹۱۴ ۔ ثابت بن ودیعہ بن خذام\nبنی امیہ بن زید بن مالک کے فرد ہیں ابن سعد نے ان کا تذکرہ کیا ہے کہ ان کے والد منافق تھے اور ان میں اور ثابت بن یزید میں فرق کیا ہے۔ ابن ودیعہ(1) سے مشہور ہیں۔ ابن الاثیر(2) نے اس کا رد کیا ہے۔ میرے سامنے جو بات ظاہر ہوئی وہ یہ ہے کہ دونوں جدا جدا شخصیتیں ہیں، کیونکہ دونوں کا نسب مختلف ہے۔ اور بظاہر بھی ودیعہ ان کے والد نہیں رہے وہ جن کا تذکرہ آئے گا تو اُن کی والدہ کا نام ودیعہ ہے۔","",{"fn":"(1) جامع المسانید (۴۲۲/۲)\n(2) اسد الغابۃ (۲۶۸/۱)"}],[915,"§۹۱۵ ۔ ثابت بن وقش(1)\nبن زغبہ بن زعوراء بن عبد الاشہل انصاری اشہلی۔ مغازی میں ابن اسحاق نے ذکر کیا کہ عاصم بن عمر نے مجھے بحوالہ محمود بن لبید بتایا کہ جب رسول اللہ صلی اللہ علیہ وسلم اُحد کی جانب نکلے تو ثابت بن وقش اور حسل بن جابر جو حذیفہ بن یمان رضی اللہ عنہ کے والد ہیں ٹیلوں پر عورتوں اور بچوں کے ساتھ دکھائی دیئے دونوں ضعف و پیری میں تھے۔ ایک دوسرے سے کہنے لگے: ہم آج کل میں کھوپڑیاں بن جائیں گے۔ تمہارا ناس! ہمیں کس چیز کا انتظار ہے؟ پھر وہ دونوں مسلمانوں سے آ ملے تا کہ شہادت حاصل کریں۔ جب وہ دونوں لوگوں میں شامل ہوئے تو مشرکین نے ثابت بن وقش کو شہید کر دیا۔ اور مسلمانوں کی تلواریں حذیفہ کے والد کی جانب مڑ چکی تھیں۔ حذیفہ بولے: میرے والد، میرے والد ہیں۔ اتنے میں وہ شہید ہو گئے۔ وہ انہیں پہچانتے نہ تھے۔ سیدنا حذیفہ نے فرمایا: اللہ تمہاری مغفرت فرمائے اور اپنے والد کی دیت(2) مسلمانوں پر صدقہ کر دی۔ حذیفہ کے والد کا قصہ صحیح میں سیدہ عائشہ رضی اللہ عنہا کی حدیث سے ثابت ہے لیکن اس میں \"ثابت\" کا ذکر نہیں۔","",{"fn":"(1) اسد الغابۃ (۵۸۱) الاستيعاب (۲۵۸)\n(2) اسد الغابۃ (۲۶۹/۱) معرفۃ الصحابۃ (۲۲۴/۲)"}],[916,"§۹۱۶ ۔ ثابت بن یزید(1)\nبن ودیعہ، انہیں ابن یزید بن عمرو بن قیس بن جزی بن عدی بن مالک بن سالم بھی کہا جاتا ہے۔ وہ حنبلی بن عوف بن عمرو بن الجموح انصاری ہیں۔ کنیت ابو سعد تھی۔ ترمذی نے ذکر کیا کہ ودیعہ ان کی والدہ ہے جس سے وہ مشہور ہیں۔ جس کا روایات میں تذکرہ آتا ہے۔ ابوداؤد وغیرہ نے ضب(2) (گوہ) کے متعلق ان کی ایک حدیث نقل کی ہے۔ اکثر کے ہاں وہ ثابت بن ودیعہ سے مروی ہے اور ورقاء کی روایت میں بحوالہ حصین، زید بن وہب سے وہ ثابت بن یزید انصاری سے، جس سے معلوم ہوا وہ وہی ہیں۔ بقول ابن ابی حاتم:(3) ثابت بن یزید صحابی ہیں۔ جن سے عامر بن سعد روایت کرتے ہیں، وہ یہی ہیں۔","",{"fn":"(1) اسد الغابۃ (۵۸۲) الاستيعاب (۲۶۳) تجرید (۶۵/۱)\n(2) ابوداؤد کتاب الاطعمۃ باب فی اکل الضب (۳۷۹۵) نسائی کتاب الصید باب الضب (۴۳۳۱) ابن ماجہ کتاب الصید باب الضب (۳۲۳۸) مسند احمد (۲۲۱/۴) ابوداؤد طیالسی (۱۶۵۸) المعجم الکبیر (۸۰، ۸۱/۲)\n(3) الجرح والتعدیل (۴۵۹/۲)"}],[917,"§۹۱۷ ۔ ثابت بن یزید\nیہودیوں کو تحریر لکھنے کے بارے میں سیدنا عمر رضی اللہ عنہ کے قصہ میں ان کا تذکرہ آتا ہے، عبد اللہ بن ثابت میں بھی ذکر آئے گا۔"],[918,"§۹۱۸ ۔ ثابت بن یزید(1)\n(نسب کا ذکر نہیں) باوردی، ابن مندہ اور طبرانی نے نضر بن علقمہ کی سند سے مسند شامیین میں بحوالہ ان کے بھائی محفوظ، وہ ابن عائذ سے فرماتے ہیں: ثابت بن یزید نے عرض کیا: یا رسول اللہ! میرا ایک پاؤں لنگڑا ہے جو زمین پر نہیں لگتا۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے میرے لیے دعا فرمائی تو وہ پاؤں ٹھیک ہو گیا اور دونوں برابر زمین پر لگنے لگے، جیسے دوسرا(2) پاؤں صحیح طور پر زمین کو چھوتا تھا۔ بقول ابن مندہ ہمیں انہیں صرف اسی سند سے جانتے ہیں۔ فرماتے ہیں: یہ بھی احتمال ہے کہ وہ ابن ودیعہ ہوں۔","",{"fn":"(1) اسد الغابۃ (۵۸۳)\n(2) اسد الغابۃ (۲۷۰/۱) جامع المسانید (۴۲۵/۲) معرفۃ الصحابۃ (۲۴۰/۳)"}],[919,"§۹۱۹ ۔ (ز) ثابت بن یسار\nبقول بعض ان کے متعلق یہ آیت: \"جب تم عورتوں کو طلاق دے دو اور ان کی عدت پوری ہو جائے تو یا تو بھلے طریقے سے انہیں روک لو یا بھلے طریقے سے رخصت کر دو\"۔ (البقرۃ: ۲۳۱) اسے طبرانی اور ابن المندر نے سدی کی سند سے نقل کیا ہے کہ ثابت بن یسار نامی ایک شخص تھے انہوں نے اپنی بیوی کو طلاق دی۔ جب اس کی عدت پوری ہونے لگی تو اس سے رجوع کر لیا۔ پھر طلاق دے دی۔ ایسا اس نے کئی بار کیا، جس پر یہ آیت نازل ہوئی۔ ثعلبی نے اسے بغیر سند نقل کیا ہے۔ رہی وہ آیت جو اس کے قریب ہی ہے جس میں ہے: \"انہیں مت روکو\" (البقرۃ: ۲۳۱) تو وہ معقل بن یسار کے بارے میں اتری۔"],[920,"§۹۲۰ ۔ ثابت\nاخنس بن شریق کے غلام، عبدان نے کہا وہ بدر میں شریک تھے۔ ان کی کوئی روایت مشہور نہیں۔ فتح مصر میں بھی موجود تھے جسے ابو موسیٰ نے نقل کیا ہے۔"],[921,"§۹۲۱ ۔ (ز) ثابت الحجبی\nعقبہ بن عامر کی حدیث میں ان کا ذکر آیا ہے، جسے طبرانی(1) نے مسند عقبہ بن عامر میں سعید بن عبد الجبار الکرابیس کی سند سے بحوالہ ابراہیم بن محمد بن ثابت انجی نقل کیا۔ فرماتے ہیں: مجھے میرے والد نے عقبہ بن عامر کے حوالہ سے بتایا کہ وہ غزوہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ نکلے تو حفاظت کی ذمہ داری میرے اور ثابت انجی کے سپرد ہوئی۔ تو میں نے اپنے شریک کار سے کہا: ذرا میرے علاقہ کا خیال کرنا تا کہ میں تھوڑی دیر حضور صلی اللہ علیہ وسلم کی مجلس میں بیٹھ آؤں۔ (حدیث)","",{"fn":"(1) المعجم الکبیر (۴۶۱۷/۵)"}],[922,"§۹۲۲ ۔ ثابت\nبقول بعض رسول اللہ صلی اللہ علیہ وسلم کے غلام ابو رافع کا نام ہے۔"],[923,"§۹۲۳ ۔ ثروان بن فزارہ(1)\nبن عبد یغوث ابن زہیر بن ربیعہ بن عمرو بن عامر بن صحصعہ۔ ابن کلبی اور طبری نے ذکر کیا کہ وہ وفد میں آئے، وہی یہ اشعار کہتے ہیں: \"اللہ کے رسول! آپ کے اشتیاق میں میری سواری صبح و شام چلتے چلتے کئی آبادیوں کی مسافت طے کر آئی\"۔ ایسا ہی ابن شاہین نے محمد بن ابراہیم سے بحوالہ محمد بن زید اپنے رجال کے ذریعہ نقل کیا ہے۔ ابو موسیٰ اور ابن فتوح نے ان کا استدراک کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۵۸۵)"}],[924,"§۹۲۴ ۔ (ز) ثعلبہ بن اوس\nانہیں ابن ناشر بھی کہا جاتا ہے، تذکرہ آئے گا۔"],[925,"§۹۲۵ ۔ ثعلبہ بن ابی بلتعہ(1)\nحاطب رضی اللہ عنہ کے بھائی۔ ابو عیسیٰ ترمذی نے انہیں صحابہ میں ذکر کیا ہے۔ فرماتے ہیں: انہوں نے دور نبوی پایا ہے اکثر روایات صحابہ سے لی ہیں۔","",{"fn":"(1) اسد الغابۃ (۵۸۶)"}],[926,"§۹۲۶ ۔ (ز) ثعلبہ بن ثابت\nعورتوں کی کنیتوں میں ام کبشہ میں تذکرہ آئے گا۔"],[927,"§۹۲۷ ۔ ثعلبہ بن حارث\nزید بن حارث میں ذکر آئے گا۔"],[928,"§۹۲۸ ۔ ثعلبہ بن حاطب(1)\nبن عمرو بن عبید بن امیہ بن زید بن مالک بن عوف بن عمرو بن عوف انصاری۔ موسیٰ بن عقبہ اور ابن اسحاق نے اصحاب بدر میں ان کا ذکر کیا۔ ایسا ہی ابن کلبی نے ان کا تذکرہ کیا۔ البتہ انہوں نے یہ اضافہ نقل کیا کہ وہ اُحد میں شہید ہوئے۔","",{"fn":"(1) اسد الغابۃ (۵۹۰) الاستيعاب (۲۷۳) تجرید (۶۶/۱)"}],[929,"§۹۲۹ ۔ ثعلبہ بن حاطب(1)\nیا ابن ابی حاطب انصاری۔ ابن اسحاق نے ان کا تذکرہ بانیان مسجد ضرار میں کیا ہے۔ باوردی، ابن السکن اور ابن شاہین وغیرہ نے معان بن رفاعہ کی سند سے بحوالہ علی بن زید، قاسم سے وہ ابو امامہ سے، سابقہ والے عنوان میں روایت کرتے ہیں کہ ثعلبہ بن حاطب انصاری نے کہا: یا رسول اللہ! میرے لیے اللہ تعالیٰ سے دعا کریں۔ اللہ تعالیٰ مجھے مال نصیب کرے۔ تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"وہ تھوڑا مال جس کا تم شکر ادا نہ کر سکو\"۔ پھر وہ لمبی حدیث(2) ذکر کر کی جس میں آپ صلی اللہ علیہ وسلم نے ان کے لیے دعا فرمائی۔ ان کا مال بڑھنا اور زکوٰۃ دینے سے باز رہنا اور اللہ تعالیٰ کا یہ ارشاد: \"ان میں سے بعض ایسے بھی ہیں جنہوں نے اللہ تعالیٰ سے عہد باندھا تھا کہ اگر اس نے اپنے فضل سے ہمیں نوازا تو ہم خیرات کریں گے\"۔ (سورۃ التوبۃ: ۷۵) نازل ہوتا، وغیرہ کا ذکر ہے۔ اس میں ہے کہ نبی صلی اللہ علیہ وسلم فوت ہو گئے اور ان سے زکوٰۃ نہیں لی اور نہ ابو بکر و عمر رضی اللہ عنہما نے۔ وہ خلافت عثمانی میں فوت ہوئے۔ اس قصہ والی شخصیت کے بارے، اگر یہ واقعہ صحیح ثابت ہو جائے لیکن میرے خیال میں صحیح نہیں ہوگا۔ حالانکہ وہ بدری صحابی ہیں، تامل ہے ابن کلبی کے قول سے ان میں فرق یقینی ہو جاتا ہے کہ بدری صحابی اُحد میں شہید ہو گئے۔ جس کی تائید اس سے بھی ہوتی ہے کہ ابن مردویہ نے عطیہ کی سند سے بحوالہ ابن عباس رضی اللہ عنہما مذکورہ آیت کے متعلق اپنی تفسیر میں نقل کیا ہے، فرماتے ہیں: یہ ایک شخص تھا جسے ثعلبہ بن ابی حاطب کہا جاتا تھا وہ انصار میں سے تھا ان کی ایک مجلس میں آ کر کہنے لگا: \"اگر اللہ تعالیٰ ہمیں اپنے فضل سے نوازے\" پھر وہ طویل قصہ ذکر کیا، فرمایا: یہ ثعلبہ بن ابی حاطب ہے۔ اور بدری صحابی کے متعلق سب کا اتفاق ہے کہ وہ ثعلبہ بن حاطب ہیں۔ اور یہ روایت پایہ ثبوت تک پہنچی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو لوگ بدر و حدیبیہ میں شریک تھے ان میں سے کوئی (مسلمان) بھی جہنم میں نہیں جائے گا\"۔(3) نیز وہ ایک حدیث قدسی ہے کہ اللہ تعالیٰ نے اہل بدر سے فرمایا: \"جو چاہے کرو میں نے تمہاری مغفرت کر دی\"۔(4) جس کا یہ مرتبہ ہوا سے اللہ تعالیٰ دل میں نفاق کا بدلہ کیسے دے گا۔ اور جو کچھ نازل ہوا اس کے متعلق کیسے نازل ہو سکتا ہے؟ لہذا یہ بات ظاہر ہو گئی کہ وہ اس شخصیت کے علاوہ ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۵۹۰) الاستيعاب (۲۷۳)\n(2) طبری (۱۳۰/۱۰) القرطبی (۲۰۹/۸) الواحدی (۱۸۰) الدر المنثور (۲۶۱/۳) تہذیب تاریخ دمشق (۲۰/۴)\n(3) مسند احمد (۳۶۳/۶) الدر المنثور (۲۸۲/۴) کنز العمال (۳۳۹۰۲) اتحاف السادۃ المتقین (۷۹/۱۰) السنۃ لابن ابی عاصم (۴۱۵/۲)\n(4) السنن الکبریٰ (۱۴۶، ۱۴۷/۹) فتح الباری (۴۷/۱۱) الدر المنثور (۲۰۳، ۲۰۴/۶) کنز العمال (۳۷۹۵۷، ۳۷۹۶۲) اتحاف السادۃ المتقین (۱۳۶/۷) (۷۹/۱۰)"}],[930,"§۹۳۰ ۔ (ز) ثعلبہ بن حرام\nابن زید میں تذکرہ آئے گا۔"],[931,"§۹۳۱ ۔ ثعلبہ بن الحکم(1)\nبن عرفط بن حارث بن لقیط بن یعمر المشدد اخ بن عوف بن کعب بن عامر بن لیث بن عبد مناف بن کنانہ الکنانی اللیثی۔ بقول امام بخاری(2) وہ صحابی ہیں، چنانچہ اپنی تاریخ صغیر میں رقمطراز ہیں: \"انہیں بچپن میں صحابہ نے گرفتار کر لیا تھا\" جس کی سند انہوں نے تاریخ کبیر میں بیان کی ہے۔ \"اوسط\" میں ستر سے اسی سال کے درمیان وفات پانے والوں میں ان کا ذکر ہے۔ ابن ماجہ میں بروایت سماک بن حرب، صحیح سند سے ان کی ایک حدیث ہے۔ فرماتے ہیں: میں نے ثعلبہ بن حکم کو فرماتے سنا: ہم لوگ نبی صلی اللہ علیہ وسلم کے ساتھ تھے ایک موقع پر لوگوں نے بکریاں لوٹ لیں تو آپ صلی اللہ علیہ وسلم نے اس سے منع فرمایا۔","",{"fn":"(1) اسد الغابۃ (۵۹۲) الاستيعاب (۲۷۸) تجرید (۶۶/۱)\n(2) التاریخ الکبیر (۱۷۳/۲)"}],[932,"§۹۳۲ ۔ (ز) ثعلبہ بن خدام انصاری\nان میں کے ایک جو غزوہ تبوک سے پیچھے رہ گئے تھے اوس بن خدام کے سوانح میں ان کا تذکرہ گزر چکا ہے۔"],[933,"§۹۳۳ ۔ ثعلبہ بن زہدم تمیمی(1)\nالحنظلی۔ از بنی ثعلبہ بن یربوع بن حنظلہ۔ بقول ابن ابی فدیک، ان کے متعلق لوگ کہتے ہیں: یہ صحابی نہیں، امام بخاری(2) نے کلمہ کہ ثوری نے فرمایا: \"انہیں شرف صحابیت حاصل ہے\"۔ جبکہ یہ بات صحیح نہیں۔ امام مسلم اور عجلی نے انہیں تابعین میں ذکر کیا ہے۔ نسائی(3) میں ان تک صحیح سند کے ساتھ ایک حدیث مروی ہے۔","",{"fn":"(1) اسد الغابۃ (۵۹۵) الاستيعاب (۲۷۷) تجرید (۶۷/۱)\n(2) التاریخ الکبیر (۱۷۳/۲)\n(3) نسائی کتاب القسامۃ باب ھل یوخذ احد ب جریرۃ غیرہ (۴۸۴۸) بمعناہ"}],[934,"§۹۳۴ ۔ (ز) ثعلبہ بن زید\nبن حارث بن حرام بن غنم بن کعب بن سلمہ بن سعد بن علی ابن ساردہ بن یزید بن جشم بن خزرج انصاری خزرجی۔ موسیٰ بن عقبہ نے شرکاء بدر میں ان کا ذکر کیا ہے۔ فرماتے ہیں وہ طائف میں شہید ہوئے۔ انہی ثعلبہ کا لقب \"جَدَع\" ہے اور یہ ان ثابت کے والد ہوتے ہیں جن کا تذکرہ پہلے ہو چکا ہے۔ ابن مندہ نے ان کا یوں ذکر کیا ہے: ثعلبہ بن الجدع، ان کے لقب کو ان کے والد کا نام بنا دیا۔ جب دوبارہ ان کا تذکرہ کیا تو یوں کہا: \"ثعلبہ بن حارث\" انہیں ان کے دادا کی طرف منسوب کر دیا۔ ابو موسیٰ اور ابن فتوح نے ان کا استدراک کیا تو کہا: ثعلبہ بن حرام انہیں ان کے والد کے دادا کی طرف منسوب کر کے ایک شخص تین افراد میں تبدیل ہو گیا۔"],[935,"§۹۳۵ ۔ ثعلبہ بن زید انصاری(1)\nبن عمرو بن عوف کے فرد ہیں۔ بقول ابن مندہ، مغازی میں ان کا ذکر آتا ہے۔ عبد الغنی بن سعید ثقفی نے اپنی تفسیر میں سیدنا ابن عباس رضی اللہ عنہما سے اپنی سند سے نقل کیا۔ یہ ان میں سے ایک ہیں جن کے متعلق یہ ارشاد باری تعالیٰ نازل ہوا: \"اور نہ ان لوگوں پر جہاد میں نہ جانے میں کوئی حرج ہے جب وہ آپ کے پاس آئیں تاکہ آپ انہیں سواری کا جانور دیں\"۔ (التوبۃ: ۹۲) اور عبدان نے احمد بن سیار سے نقل کیا کہ ثعلبہ بن زید بنی حرام سے تعلق رکھتے ہیں۔ جو انصار کے بہت رونے والے(2) شخص تھے۔ ابو موسیٰ نے ان کا استدراک کیا ہے۔ میں کہتا ہوں: جن کا تعلق بنی حرام سے ہے وہ پہلے والی شخصیت ہے اور جن کا تعلق بن عمرو بن عوف سے ہے وہ یہی صاحب سوانح شخصیت ہے اس لیے ممکن ہے کہ دونوں زیادہ رونے والے ہوں اور یہ بھی احتمال ہے کہ صاحب سوانح شخص کا نام تبدیل ہو گیا۔ اور مجمع بن حارثہ نے زیادہ رونے والوں کے نام شمار کیے ہیں ان میں ثعلبہ بن زید کو نہیں گنا۔ البتہ ثعلبہ بن زید حارثی کو شامل ہے۔ ابن مردویہ نے اپنی تفسیر میں یہ بات نقل کی کی ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۵۹۷) تجرید (۶۷/۱)\n(2) اسد الغابۃ (۲۷۵/۱)"}],[936,"§۹۳۶ ۔ ثعلبہ بن ساعدہ(1)\nبن مالک، ابو الاسود نے بحوالہ عمروہ شہداء اُحد میں ان کا ذکر کیا ہے جسے طبرانی، ابن مندہ(2) نے نقل کیا ہے۔ ابو نعیم فرماتے ہیں: میرے خیال میں یہ سہل بن سعد کے بھائی ہیں۔ ایسا لگتا ہے اس میں تحریف ابن لہیعہ سے ہوئی ہے۔ جو ابو الاسود سے روایت کرنے والے ہیں۔ میں کہتا ہوں: ابو عمر نے اس بات پر یقین کیا ہے کہ وہ ابو حمید ساعدی کے چچا ہیں۔ لہذا دونوں جدا ہو گئے۔","",{"fn":"(1) اسد الغابۃ (۵۹۹) تجرید (۶۷/۱)\n(2) المعجم الکبیر (۱۳۹۲، ۱۳۹۳/۲)"}],[937,"§۹۳۷ ۔ ثعلبہ بن سَعْد(1)\nبن مالک بن خالد ابن ثعلبہ بن حارثہ بن عمرو بن الخزرج بن ساعدہ خزرجی ساعدی سہل بن سعد کے بھائی، بدر میں شریک اور اُحد میں شہید ہوئے۔ طبرانی نے عبد المیمن بن عباس بن سہل بن سعد سے بحوالہ اپنے والد وہ اپنے دادا سے روایت کرتے ہیں، فرمایا: میرا بھائی بدر میں شریک اور اُحد میں شہید ہوا۔ موسیٰ بن عقبہ(2) نے شہداء اُحد میں ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۰۰) الاستيعاب (۲۷۱)\n(2) المعجم الکبیر (۸۹/۲)"}],[938,"§۹۳۸ ۔ ثعلبہ بن سعیہ\nان لوگوں میں سے ہیں جو یہودیت(1) سے اسلام لائے، اسد بن سعیہ میں ذکر گزر چکا ہے۔","",{"fn":"(1) المعجم الکبیر (۱۳۸۸/۲) مجمع الزوائد (۳۲۷/۶)"}],[939,"§۹۳۹ ۔ ثعلبہ بن سلام(1)\nعبد اللہ بن سلام رضی اللہ عنہ کے بھائی۔ طبرانی نے ابن جرتج کا یہ یقینی قول نقل کیا ہے کہ یہ ان میں سے ایک نہیں جن کے متعلق ارشاد باری تعالیٰ نازل ہوا: \"اہل کتاب کی ایک جماعت حق پر قائم ہے\"۔ (آل عمران: ۱۱۳) ابو عمر نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۰۲) الاستيعاب (۲۷۴)"}],[940,"§۹۴۰ ۔ (ز) ثعلبہ بن سوید انصاری(1)\nابن فتوح نے انہیں صحابہ میں ذکر کیا ہے۔ ان کے بھائی اوس بن سوید میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) الاستيعاب (۲۸۵/۱)"}],[941,"§۹۴۱ ۔ ثعلبہ بن سہیل(1)\nبقول بعض یہ ابو امامہ حارثی کا نام ہے (لیکن) مشہور یہ ہے کہ ابو امامہ حارثی کا نام ایاس بن ثعلبہ، کنیتوں میں آئے گا۔ ثعلبہ نامی حضرات کے آخر میں اس اختلاف کا سبب آئے گا۔","",{"fn":"(1) اسد الغابۃ (۶۰۳) الاستيعاب (۲۷۶) تجرید (۶۷/۱)"}],[942,"§۹۴۲ ۔ ثعلبہ بن صغیر(1)\nانہیں ابن ابی صغیر بن عمرو بن زید بن سنان بن سلمان بن سماک بن سماک بن قضاعی عذری بھی کہا جاتا ہے۔ بنی زہرہ کے حلیف۔ بقول طبرانی: یہ صحابی ہیں اور ان کا بیٹا عبد اللہ دیدار سے مشرف ہے۔ ابن ابی عاصم اور باوردی وغیرہ نے بکیر بن وائل کی سند سے بحوالہ زہری عبداللہ بن ثعلبہ بن صغیر سے وہ اپنے والد سے صدقہ فطر(2) کے متعلق روایت کرتے ہیں، فرماتے ہیں: اس میں ہمام، بکیر سے روایت کرنے میں متفرد ہے۔ میں کہتا ہوں: بکیر بن کنیز سقاء نے بحوالہ زہری بکیر کی متابعت کی ہے جسے حسن بن سفیان نے نقل کیا ہے اور ان کی سند سے ابو نعیم نے روایت کیا ہے۔ مذکورہ حدیث کو ابو داؤد نے نعمان بن راشد کی سند سے بحوالہ زہری روایت کیا ہے تو یوں کہا: ثعلبہ بن ابی صغیر اپنے والد سے، اور ایک روایت میں ان کے ہاں ہے عبد اللہ بن ثعلبہ یا ثعلبہ بن عبد اللہ۔ ابن السکن فرماتے ہیں: ثعلبہ بن عبد اللہ بن ابی صغیر عذری کا سماع صحیح نہیں۔ پھر اپنی سند جو ابن معین تک ہے سے روایت کرتے ہیں، فرمایا ثعلبہ بن ابی صغیر نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے۔ ابن شاہین نے یحییٰ بن خارجہ کی سند سے بحوالہ زہری نقل کیا تو کہا: عبد اللہ بن ثعلبہ بن ابی صغیر سے مروی ہے۔ بقول ابن شاہین: اس روایت کو یحییٰ بن خارجہ نے مرسل روایت کیا ہے۔ ان کا تذکرہ ان کے بیٹے عبد اللہ بن ثعلبہ کے سوانح میں آئے گا۔ امام بخاری رحمہ اللہ اپنی تاریخ میں لکھتے ہیں: عبد اللہ بن ثعلبہ بن صغیر نبی صلی اللہ علیہ وسلم سے مرسل روایت کرتے ہیں، ہاں جہاں \"عن ابیہ\" کے الفاظ ہوں وہ زیادہ مناسب ہے۔ رہے ثعلبہ بن ابی صغیر تو وہ ان لوگوں میں سے نہیں۔ میں کہتا ہوں: اس کا تقاضا تو یہ ہے کہ ثعلبہ بن صغیر، ثعلبہ بن ابی صغیر کے علاوہ کوئی شخصیت ہو نی چاہیے۔ فاللہ اعلم","",{"fn":"(1) اسد الغابۃ (۶۰۴) الاستيعاب (۲۷۹) تجرید (۶۷/۱)\n(2) ابوداؤد کتاب الزکاۃ باب من روی نصف صاع من قمح (۱۶۱۹) المعجم الکبیر (۸۷/۲) السنن الکبریٰ (۱۶۷/۴)"}],[943,"§۹۴۳ ۔ (ز) ثعلبہ بن عبد اللہ بن سام\nثعلبہ بن ابی مالک میں آئے گا۔"],[944,"§۹۴۴ ۔ ثعلبہ بن عبد الرحمٰن انصاری(1)\nان کے متعلق کہا جاتا ہے کہ وہ نبی صلی اللہ علیہ وسلم کی خدمت کرتے تھے۔ ابن شاہین اور ابو نعیم نے ایک طویل روایت سلیم بن منصور بن عمار کی سند سے بحوالہ ان کے والد وہ منکدر بن محمد بن منکدر وہ اپنے والد سے وہ جابر سے کہ انصار کا ایک نوجوان ثعلبہ بن عبد الرحمٰن نبی صلی اللہ علیہ وسلم کی خدمت کرتا تھا، آپ نے اسے کسی کام سے بھیجا وہ کسی انصاری کے گھر سے گزرے ان کی بیوی غسل کر رہی تھی تو اسے گھورنے لگا۔ اتنے میں دل میں خوف ہوا کہ وحی نازل نہ ہو جائے۔ سیدھا بھاگ نکلا اور مکہ و مدینہ کے درمیان پہاڑوں میں رہنے لگا۔ نبی صلی اللہ علیہ وسلم نے اسے چالیس دن گم پایا اور یہ وہ دن تھے جن میں (وحی کا سلسلہ موقوف تھا اور) لوگ کہتے پھرتے تھے: \"انہیں (محمد صلی اللہ علیہ وسلم کو) ان کے رب نے چھوڑ دیا اور ان سے ناراض ہے\"۔ جبرائیل علیہ السلام آ کر کہنے لگے: \"محمد (صلی اللہ علیہ وسلم)! بھاگنے والا پہاڑوں میں جہنم سے میری پناہ مانگتا ہے\"۔ آپ صلی اللہ علیہ وسلم نے اس کی طرف سیدنا عمر رضی اللہ عنہ کو روانہ کیا، اور فرمایا: تم اور سلمان جاؤ، اسے میرے پاس لے آؤ۔ راستہ میں انہیں ذو فافہ نامی گڈر یا ملا، وہ کہنے لگا: شاید تم دونوں کو جہنم سے بھاگنے والے کی تلاش ہے۔ پھر اس کے لانے کے بارے میں لمبی حدیث ذکر کی۔ اوس کا بیمار پڑ جانا اور اپنے گناہ کے خوف سے فوت ہو جانے کا قصہ(2) بیان کیا۔ ابن مندہ نے یہ قصہ مختصر روایت کرنے کے بعد کہا: منصور نے نقل کرنے میں متفرد ہے۔ میں کہتا ہوں: وہ ضعیف ہے اور اس کا شیخ اس سے زیادہ ضعیف ہے۔ اور روایت کے بیان سے پتہ چلتا ہے یہ حدیث کمزور ہے۔ اس واسطے کہ آیت ﴿مَا وَدَّعَکَ رَبُّکَ وَمَا قَلٰی﴾ (سورۃ الضحیٰ: ۳) بلا اختلاف ہجرت سے پہلے نازل ہوئی۔","",{"fn":"(1) اسد الغابۃ (۶۰۶)\n(2) کنز العمال (۴۵۸۷) الامالی للشجری (۲۴۹/۱) حلیۃ الاولیاء (۳۳۰/۹) علل الحدیث (۱۵۱، ۱۵۳) الموضوعات لابن الجوزی (۱۲۲/۸)"}],[945,"§۹۴۵ ۔ ثعلبہ بن عبید\nبن عدی۔ \"تجرید\"،(1) میں ذہبی فرماتے ہیں: ابن الجوزی نے \"تلقیح\" میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: مجھے ڈر ہے کہ ان کے والد کے نام میں غلطی واقع ہوئی ہے۔ وہ ثعلبہ بن عمہ بن عدی ہیں جن کا تذکرہ تھوڑے وقفہ سے آئے گا۔","",{"fn":"(1) تجرید (۲۰/۱)"}],[946,"§۹۴۶ ۔ ثعلبہ بن عمرو جذامی(1)\nابن اسحاق(2) نے مغازی میں ان لوگوں میں ذکر کیا ہے جنہیں زید بن حارثہ رضی اللہ عنہ نے بنی جذام سے ان کے مسلمان ہو جانے کے بعد گرفتار کیا گیا تھا اور آپ صلی اللہ علیہ وسلم نے انہیں آزاد کر دینے کا حکم دیا تھا۔","",{"fn":"(1) اسد الغابۃ (۶۱۰)\n(2) السیرۃ النبویۃ عن ابن اسحاق (۹۹۱/۴، ۲۱۳)"}],[947,"§۹۴۷ ۔ (ز) ثعلبہ بن عمرو(1)\nبن محسن ابن عمرو بن عتیک بن عمرو بن مبذول بن مالک بن النجار انصاری۔ موسیٰ بن عقبہ بن اہل بدر میں ان کا ذکر کیا اور کہا وہ حمر ابی عبید کے روز شہید ہوئے۔ بقول واقدی خلافت عثمانی میں فوت ہوئے۔","",{"fn":"(1) اسد الغابۃ (۶۰۹) الاستيعاب (۲۷۲)"}],[948,"§۹۴۸ ۔ (ز) ثعلبہ بن عمرو\nبقول بعض جسے بغوی نے نقل کیا ہے، ابو عمرہ انصاری کا نام ہے۔"],[949,"§۹۴۹ ۔ ثعلبہ بن عنمہ(1)\nابن عدی بن نابی بن عمرو بن سواد بن غنم بن کعب بن سلمہ انصاری سلمی خزرجی، موسیٰ بن عقبہ اور عمروہ وغیرہ نے شرکاء بدر و عقبہ میں ان کا ذکر کیا ہے۔ ان میں سے تھے جو بنی سلمہ کے بت توڑتے تھے۔ بقول ابن اسحاق: غزوہ خندق میں شہید ہوئے، حمیرہ بن ابی وہب نے آپ کو شہید کیا۔ ابن لہیعہ۔ بحوالہ ابو الاسود عمروہ سے نقل کرتے ہیں کہ وہ خیبر میں شہید ہوئے۔ ابن کلبی نے ذکر کیا کہ انہوں نے پوچھا کہ ہلال (چاند) کیسے چھوٹا سا ظاہر ہو کر بڑھتا رہتا ہے؟ اس پر اللہ تعالیٰ کا ارشاد نازل ہوا \"لوگ آپ سے چاند کے متعلق پوچھتے ہیں\"۔ (سورۃ البقرۃ: ۱۸۹)(2)","",{"fn":"(1) اسد الغابۃ (۶۱۱) الاستيعاب (۲۷۰)\n(2) المعجم الکبیر (۱۴۰۳/۲) معرفۃ الصحابۃ (۲۶۹/۳) اسد الغابۃ (۲۸۰/۱)"}],[950,"§۹۵۰ ۔ (ز) ثعلبہ بن قیس\nسلمہ بن سلام میں ان شاء اللہ ذکر آئے گا۔"],[951,"§۹۵۱ ۔ ثعلبہ بن قیظی(1)\nبن صحر بن سلمہ انصاری۔ مطین اور طبرانی(2) وغیرہ نے عبد اللہ بن ابی رافع کی سند سے ان اہل بدر میں ان کا ذکر کیا ہے جو صفین میں شریک تھے، عبد اللہ تک سند بہت کمزور ہے۔","",{"fn":"(1) اسد الغابۃ (۶۱۲) تجرید (۶۹/۱)\n(2) المعجم الکبیر (۸۷/۲)"}],[952,"§۹۵۲ ۔ ثعلبہ بن ابی مالک القرظی(1)\nان کے صحابی ہونے میں اختلاف ہے۔ ابن معین فرماتے ہیں: انہیں دیدار حاصل ہے اور ابن سعد نے کہا: ابو مالک جن کا نام عبد اللہ بن سام تھا یمن سے آئے ان کا تعلق کندہ سے تھا۔ انہوں نے قریظہ کی ایک خاتون سے شادی کر لی تو قریظی مشہور ہو گئے۔ بقول مصعب زبیری یہ ان لوگوں میں سے تھے جن کی قریظہ کے دن میں نہ پھوٹی تھیں تو انہیں بھی عطیہ کی طرح چھوڑ دیا گیا۔ میں کہتا ہوں: عطیہ کا ذکر آئے گا۔ بغوی وغیرہ نے ابن اسحاق کی سند سے بحوالہ ابو مالک بن ثعلبہ بن ابی مالک وہ اپنے والد سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم کے پاس یہود کے لوگ آئے آپ نے یہ فیصلہ فرمایا کہ جب پانی ٹخنوں تک پہنچ جائے اوپر سے نہ روکا جائے۔ ولید بن کثیر نے ابو مالک سے روایت کرنے میں ابن اسحاق کی متابعت کی ہے اور ابن ابی عاصم نے صفوان بن سلیم کی سند سے بحوالہ ثعلبہ اسی مفہوم کو روایت کیا ہے، اس کے رجال معتبر ہیں۔ ابن ماجہ(2) نے اسے دوسری سند سے بحوالہ محمد بن عقبہ بن ابی مالک، ان کے چچا ثعلبہ بن ابی مالک سے روایت کیا ہے۔ ابن حبان(3) نے ثقات التابعین میں ان کا تذکرہ کیا ہے اور ابو حاتم(4) فرماتے ہیں: تابعی ہیں، ان کی حدیث مرسل ہے۔ میں کہتا ہوں: ان کی حدیث بحوالہ سیدنا عمر رضی اللہ عنہ صحیح بخاری میں ہے جس کے والد قریظہ میں قتل ہوں اور وہ ان لوگوں میں سے ہو کہ اگر اس کے داڑھی نہ ہوتی تو قتل کر دیا جاتا۔ اس سے کوئی مانع نہیں کہ اس کا سماع صحیح ہو۔ اسی احتمال کی بنا پر میں ان کا یہاں ذکر کر رہا ہوں۔","",{"fn":"(1) اسد الغابۃ (۶۱۳) الاستيعاب (۲۸۰) تجرید (۶۹/۱)\n(2) ابن ماجہ کتاب الرھون باب الشرب من الاودیۃ و مقدار حبس الماء (۲۴۸۱)\n(3) الثقات (۹۸/۴)\n(4) الجرح والتعدیل (۴۶۳/۲)"}],[953,"§۹۵۳ ۔ (ز) ثعلبہ بن ودیعہ انصاری\nان میں کے ایک جو غزوہ تبوک سے رہ گئے اوس بن خدام میں ان کا تذکرہ ہو چکا ہے۔"],[954,"§۹۵۴ ۔ ثعلبہ تمیمی عنبری\nہرماس بن حبیب عنبری کے دادا، اسحاق بن راہویہ نے نضر بن شمیل سے بحوالہ ہرماس سے اپنی روایت میں وہ اپنے والد سے وہ اپنے دادا سے ان کا نام لیا ہے۔ فرماتے ہیں: میں نبی صلی اللہ علیہ وسلم کے پاس اپنا ایک قرض خواہ لایا، آپ نے فرمایا: \"اس سے جدانہ ہوتا\"۔ (حدیث)(1) بقول ابن مندہ: حسن بن عمر بن شقیق نے نضر سے روایت کرنے میں ان کی مخالفت کی ہے۔ وہ کہتے ہیں: ہرماس بن حبیب سے، وہ اپنے والد سے، وہ اپنے دادا ہرماس بن زیاد سے روایت کرتے ہیں۔ ایسا ہی ابن مندہ نے قعنب بن محرر بحوالہ قتیمہ بن ہرماس بن حبیب بن ہرماس بن زیاد نقل کیا ہے اور ایک جماعت نے اسے نضر سے روایت کیا ہے، لیکن انہوں نے ہرماس بن حبیب کے دادا کا نام نہیں لیا۔ فاللہ اعلم","",{"fn":"(1) ابوداؤد کتاب الاقضیۃ باب فی الحبس فی الدین وغیرہ (۳۶۲۹) ابن ماجہ کتاب الصدقات باب الحبس فی الدین والملازمۃ (۲۴۲۷) التاریخ الکبیر (۲۴۷/۸) علل الحدیث (۱۴۲۴)"}],[955,"§۹۵۵ ۔ (ز) ثعلبہ انصاری(1)\nعبد اللہ کے والد، بقول بعض ان کے والد کا نام سہیل ہے۔ ابن ابی حاتم(2) نے ان کا تذکرہ کیا۔ باوردی اور ابو مسلم انجی نے خالد بن حارث کی سند سے اور حاکم نے متدرک میں، حسن بن سفیان اور ابو احمد حاکم(3) نے الکنی میں عبد اللہ بن حران کی سند سے دونوں عبد الحمید بن جعفر سے روایت کرتے ہیں، فرمایا: مجھے عبد اللہ بن ثعلبہ انصاری نے بتایا کہ میں نے عبد الرحمٰن بن کعب کو فرماتے سنا، میں نے تمہارے والد ثعلبہ کو فرماتے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جو شخص بھی کسی کا حق جھوٹی قسم سے مارے گا تو اس کے دل میں نفاق کی وجہ سے سیاہ داغ لگ جائے گا جسے قیامت تک کوئی چیز نہ مٹا سکے گی\"۔ بقی بن مخلد کی مسند میں ثعلبہ بن عبد اللہ لکھا ہے۔ فاللہ اعلم ابو احمد حاکم نے نقل کیا کہ حسین بن محمد قبانی نے کہا: یہ ثعلبہ ابو امامہ حارثی ہیں۔ لیکن مشہور یہ ہے کہ ابو امامہ کا نام ایاس بن ثعلبہ ہے۔ جن لوگوں نے صحابہ کے متعلق تصنیفات چھوڑی ہیں ان میں سے کئی ایک مثلاً بغوی، ابن ابی حاتم اور ابن شاہین وغیرہ نے اس پر یقین کیا کہ وہ کوئی اور ہیں۔ ادھر دونوں حدیثوں میں متن اور اسناد کے لحاظ سے فرق ہے، اس لیے احتمال ہے کہ وہ کوئی اور ہوں۔ اسی فرق پر ابو حاتم وغیرہ نے یقین کیا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۶۰۵) تجرید (۶۸/۱)\n(2) الجرح والتعدیل (۴۶۲/۲)\n(3) المستدرک (۲۹۴/۴)"}],[956,"§۹۵۶ ۔ ثعلبہ انصاری\nنزیل مصر عبد الرحمٰن کے والد۔ ان سے ان کے بیٹے عبد الرحمٰن چوری کے متعلق ایک حدیث نقل کرتے ہیں جو ابن ماجہ(1) و ابن مندہ نے یزید بن ابی حبیب کی سند سے بحوالہ عبد الرحمٰن درج کی ہے۔ ابو عمر۔ نے ذکر کیا کہ وہ ثعلبہ بن عمرو بن محصن ہیں۔ البتہ ابن ابی حاتم نے، ایسا ہی طبرانی(2) نے دونوں میں فرق کیا ہے، یہی درست ہے۔","",{"fn":"(1) ابن ماجہ کتاب الحدود باب السارق یعترف (۲۵۸۸)\n(2) المعجم الکبیر (۸۶/۲)"}],[957,"§۹۵۷ ۔ (ز) ثعلبہ (کسی قبیلہ کی طرف منسوب نہیں)\n\"ابن ثعلبہ\" کے مہمات میں ابن مندہ اور ابو نعیم نے ان کا ذکر کیا۔ اور دونوں نے یحییٰ بن جابر کی سند سے بحوالہ ابن ثعلبہ سے بحوالہ ابن ثعلبہ ان کی روایت نقل کی ہے کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آ کر عرض کرنے لگے، یا رسول اللہ! میرے لیے اللہ کے حضور شہادت کی دعا فرمائیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میرے پاس کچھ مال لاؤ\"۔ چنانچہ وہ مال لائے۔ فرمایا: \"اپنے کندھے سے کپڑا ہٹاؤ\"۔ فرماتے ہیں، آپ صلی اللہ علیہ وسلم نے ان کے بازو پر باندھ دیئے پھر ان میں پھونک مار کر فرمایا: \"اے اللہ! ثعلبہ کا خون مشرکین اور منافقین کے لیے حرام فرما دے\"۔(1) ابن الاثیر فرماتے ہیں، ان دونوں کے ہاں \"ثعلبہ کا خون\" کے الفاظ ہیں۔ سوائے اول سند کے کسی چیز سے ابن ثعلبہ کا پتہ نہیں چلتا۔ میں کہتا ہوں: ابن ثعلبہ کا نام ضمرہ ہے۔ یہ حدیث ان کے سوانح میں حرف ضاد میں گزر چکی ہے۔ لہذا اگر یہ روایت ثابت ہے تو \"وہ ابن\" ضمیر کا مرجع ثعلبہ ہو گا۔ یوں صحابہ میں ان کا ذکر متعین ہو جائے گا اور وہ اس قسم میں شمار ہوں گے جو خود بھی صحابی اور ان کے والد بھی صحابی ہیں۔ لیکن جو روایت حرف ضاد میں گزری ہے اس میں ہے: \"اے اللہ! ابن ثعلبہ کا خون حرام فرما دے\"۔ لفظ ابن کا اضافہ ہے۔ واللہ اعلم","",{"fn":"(1) مجمع الزوائد (۳۷۹/۹)"}],[958,"§۹۵۸ ۔ ثقاف بن عمرو العدوانی(1)\nبقول ابن ابی حاتم بحوالہ ان کے والد مہاجرین اولین سے ہیں۔ اور ابن مندہ نے ابن المبارک کی سند سے بحوالہ حماد بن زید انہوں نے ایوب، انہوں نے جری نے ابو قلابہ سے روایت کی ہے کہ ثمامہ بن عدی اور ثقیف بن عمرو مہاجرین اولین سے ہیں۔ ان سے کوئی حدیث منقول نہیں۔","",{"fn":"(1) اسد الغابۃ (۶۱۶)"}],[959,"§۹۵۹ ۔ ثقب بن قزوہ(1)\nبن البدرى انصاری ساعدی۔ انہیں احرش کہا جاتا ہے، ان کا نام و نسب ابن القداح کتاب نے بتایا ہے کہ وہ احد میں شہید ہوئے، لیکن نام تصغیر سے ذکر کیا جسے ابن شاہین نے درج کیا کہ ثقیف شروع کا زبر آخر میں فاء ہے، ایسا ہی ابن عبد البر(2) اور ابو موسیٰ نے ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۱۵) الاستيعاب (۲۸۴)\n(2) الاستيعاب (۲۹۰/۱)"}],[960,"§۹۶۰ ۔ ثقف بن عمرو(1)\nبن سمیط از بنی غنم بن دودان بن اسد بن خزیمہ، ابن اسحاق اور موسیٰ بن عقبہ نے ذکر کیا کہ وہ اور ان کے دونوں بھائی مدلاج اور مالک بدر میں شریک ہوئے اور وہ خود خیبر(2) میں شہید ہوئے۔ بقول واقدی: ثقاف بن عمرو کو اسید بن رزام یہودی نے شہید کیا۔","",{"fn":"(1) اسد الغابۃ (۶۱۷) الاستيعاب (۲۸۵) تجرید (۶۹/۱)\n(2) المعجم الکبیر (۱۰۴/۲)"}],[961,"§۹۶۱ ۔ ثمامہ بن اثال(1)\nبن نعمان بن مسلمہ بن عتبہ بن ثعلبہ بن یربوع بن ثعلبہ بن دؤل بن حنیفہ ابو امامہ یمامی، ان کی حدیث بخاری(2) میں سعید المقبری کی سند سے بحوالہ سیدنا ابو ہریرہ رضی اللہ عنہ مروی ہے، فرماتے ہیں کہ نبی صلی اللہ علیہ وسلم نے نجد کی جانب ایک دستہ بھیجا تو وہ بنی حنیفہ کے ایک شخص کو پکڑ لائے جسے ثمامہ بن اثال کہا جاتا تھا۔ اسے لا کر مسجد کے ستون سے باندھ دیا۔ نبی صلی اللہ علیہ وسلم باہر تشریف لائے۔ فرمایا: \"ثمامہ کو چھوڑ دو\"۔ وہ مسجد کے قریب نخلستان میں غسل کر کے واپس مسجد آ کر کہنے لگے: میں اللہ کے معبود ہونے اور محمد (صلی اللہ علیہ وسلم) کے رسول ہونے کی گواہی دیتا ہوں۔ اسی طرح انہوں نے طویل روایت نقل کی ہے جسے ابن اسحاق نے مغازى میں سعید المقبری سے طویل نقل کیا ہے جس کا آغاز اس طرح ہے کہ ثمامہ جب آپ کے سامنے قتل کے ارادے سے آئے آپ نے اپنے رب سے دعا کی کہ مجھے اس پر قابو دے دے۔ اسلام لانے کے بعد جب وہ عمرہ کرنے مکہ گئے تو (کفار مکہ سے) کہنے لگے: اس ذات کی قسم جس کے قبضہ قدرت میں میری جان ہے، (اگر تم باز نہ آئے) تمہارے پاس یمامہ سے ایک دانہ بھی نہیں پہنچے گا۔ وہ مکہ والوں کی معیشت کی وسعت کا ذریعہ تھا۔ یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم نے اجازت دے دیں۔(3) اسے حمید نے سفیان سے بحوالہ ابن عجلان سعید سے انہوں نے سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کیا ہے۔ نیز ابن اسحاق نے ذکر کیا کہ جب اہل یمامہ مرتد ہوئے تو ثمامہ اسلام پر ثابت قدم رہے اور ان کے پیروکار جو ان کی قوم سے تعلق رکھتے تھے کوچ کر گئے، اور علاء حضرمی رضی اللہ عنہ سے مل کر بحرین کے مرتدوں کے خلاف جنگ کی۔ جب انہیں فتح ہو گئی تو ثمامہ نے وہ جوڑا خریدا جو ان کے سردار کا تھا، جب انہیں بنی قیس بن ثعلبہ کے لوگوں نے دیکھا وہ سمجھے کہ انہی نے اسے قتل کر کے اس کا لباس اتارا ہے اور انہیں شہید کر دیا۔ عامر بن سلمہ کے سوانح میں ان کا تذکرہ وہ آئے گا۔ ابن مندہ نے علماء بن احمری کی سند سے بحوالہ عکرمہ، ابن عباس رضی اللہ عنہ سے روایت میں ثمامہ کے اسلام لانے اور یمامہ جانے، قریش کو غلہ سے روکنے اور اللہ تعالیٰ کے اس ارشاد کے نازل ہونے کا قصہ نقل کیا ہے: \"ہم نے انہیں (قحط کے) عذاب میں مبتلا رکھا پھر بھی یہ اپنے رب کے سامنے نہ جھکے اور نہ عاجزی اختیار کرتے ہیں\"۔ (سورۃ المؤمنون: ۷۶)۔ اس روایت کی سند حسن ہے۔ دہیمہ نے فتنہ ارتداد میں ان کا کارنامہ ذکر کیا ہے اور بنی حنیفہ کی مخالفت میں ان کے اشعار نقل کیے ہیں۔ میں ایک بات کو چھوڑنے کا قصد کرتا ہوں لیکن نبی محمد صلی اللہ علیہ وسلم کا احسان مجھے واپس (اپنی حالت پر) لے آتا ہے۔ میں بیڑیوں سے آزاد کرانے پر ان کا شکریہ ادا کیا جبکہ مجھے تلواروں کے سائے نظر آ رہے تھے۔","",{"fn":"(1) اسد الغابۃ (۶۱۹) الاستيعاب (۲۸۲)\n(2) بخاری کتاب الصلاۃ باب الاغتسال اذا اسلم و ربط (۴۶۲)\n(3) اسد الغابۃ (۲۸۲/۱)"}],[962,"§۹۶۲ ۔ ثمامہ بن انس\nبقی بن مخلد نے اپنی مسند میں ان کی ایک حدیث روایت کی ہے۔ احتمال ہے کہ وہ ثمامہ بن انس بن مالک ہوں، اس بنا پر یہ حدیث مرسل ہو گی۔"],[963,"§۹۶۳ ۔ ثمامہ بن بجاد العبدی(1)\nابو حاتم،(2) ابن السکن اور باوردی نے کہا: انہیں شرف صحابیت حاصل ہے۔ کتاب الزہد میں امام لکھتے ہیں: ہمیں ابو داؤد نے نے بحوالہ زمیر، ابو اسحاق سے بتایا اور ابو اسحاق سے بحوالہ ثمامہ بن بجاد جنہیں شرف صحابیت حاصل ہے روایت کرنے میں شعبہ نے ان کی متابعت کی ہے، فرمایا: میں تمہیں سوف سوف (پھر کر لوں گا) سے ڈراتا ہوں۔ اسے ابو اسحاق سے ایک جماعت نے نقل کیا (لیکن) انہوں نے یہ نہیں کہا کہ وہ صحابی ہیں۔ بقول ابو حاتم: ان سے عیزار بن حریث بھی روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابۃ (۶۲۰) الاستيعاب (۲۸۳) تجرید (۷۰/۱)\n(2) الجرح والتعدیل (۴۹۵/۲)"}],[964,"§۹۶۴ ۔ ثمامہ بن ابی ثمامہ(1)\nبن بکر جذامی ابو سوادہ۔ ابو سعید بن یونس فرماتے ہیں: میں نے عمرو بن حارث کی کتاب میں بحوالہ بکر بن سوادہ جذامی، ان کے غلام سے مروی لکھا دیکھا کہ نبی صلی اللہ علیہ وسلم نے ان کے دادا ثمامہ(2) کے لئے دعا فرمائی تھی۔ اسے ابن مندہ نے بحوالہ ابن یونس روایت کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۲۱) تجرید (۷۰/۱)\n(2) اسد الغابۃ (۲۸۴/۱) معرفۃ الصحابۃ (۲۹۵/۳)"}],[965,"§۹۶۵ ۔ ثمامہ بن حزن\nقسم ثالث میں تذکرہ آئے گا۔"],[966,"§۹۶۶ ۔ ثمامہ بن عدی قرشی\nثقف بن عمرو میں ان کا تذکرہ ہوا کہ وہ مہاجرین اولین سے ہیں۔ ابو موسیٰ(1) نے بحوالہ طبری نقل کیا کہ وہ بدر میں شریک تھے۔ اور بقول ابن السکن: انہیں شرف صحابیت حاصل ہے۔ وہ صنعاء کے گورنر تھے۔ امام بخاری نے اپنی تاریخ میں اور ابن سعد نے ابو قلابہ تک بحوالہ ابو الاشعث الصنعانی صحیح سند سے نقل کیا ہے، جب ثمامہ بن عدی کو جو صنعاء (شام) کے گورنر اور صحابی تھے سیدنا عثمان بن عفان رضی اللہ عنہ کی شہادت کی اطلاع ملی تو وہ رو پڑے اور دیر تک روتے رہے۔ جب ہوش آیا تو فرمانے لگے: یہ وہ وقت ہے جس میں نبوت کی خلافت چھن گئی۔ باوردی نے دوسری سند سے ایوب سے بحوالہ ابو قلاب نقل کیا ہے اور ابن مندہ نے نضر بن معبد کی سند سے بحوالہ ابو قلاب نقل کیا، فرماتے ہیں: ابو الاشعث صنعانی نے مجھے بتایا کہ ثمامہ صنعاء کے گورنر تھے اور ان کا تعلق اصحاب محمد صلی اللہ علیہ وسلم سے تھا۔ پھر وہ روایت ذکر کی۔","",{"fn":"(1) اسد الغابۃ (۶۲۴) الاستيعاب (۲۸۶) تجرید (۷۰/۱)"}],[967,"§۹۶۷ ۔ ثوبان(1)\nخادم رسول اللہ صلی اللہ علیہ وسلم مشہور صحابی ہیں۔ لوگوں کا کہنا ہے کہ ان کا تعلق عرب کے حکمی قبیلہ سے تھا جو حکم بن سعد بن حمیر کی طرف منسوب تھا۔ بقول بعض: فارسی سرداروں سے تھے۔ آپ نے انہیں خرید کر آزاد کر دیا۔ پھر بھی انہوں نے آپ کی وفات تک خدمت کی۔ اس کے بعد وہ رملہ پھر وہاں سے حمص منتقل ہو گئے اور وہیں بقول ابن سعد وغیرہ ۵۴ھ میں فوت ہوئے۔ ابن السکن نے یوسف بن عبد الحمید کی سند سے نقل کیا، فرماتے ہیں: میری ثوبان سے ملاقات ہوئی تو انہوں نے بتایا، رسول اللہ صلی اللہ علیہ وسلم نے اپنے گھرانے کے لیے دعا فرمائی، میں نے عرض کیا: میں بھی اہل بیت سے ہوں، تیسری مرتبہ پر آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تک تم دروازے پر رکاوٹ بنے کھڑے نہ رہو اور کسی گورنر سے سوال کرنے نہ جاؤ۔\" ابو داؤد(2) نے عاصم کی سند سے بحوالہ ابو العالیہ ثوبان سے فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو مجھے یہ ضمانت دے دے کہ وہ لوگوں سے سوال نہیں کرے گا، میں اسے جنت کی ضمانت دیتا ہوں\"۔ ثوبان بولے: میں۔ چنانچہ وہ کسی سے کچھ بھی نہیں مانگتے تھے۔","",{"fn":"(1) المعجم الکبیر (۹۰/۲)\n(2) ابوداؤد کتاب الزکاۃ باب کراہیۃ المسألۃ (۱۶۴۳)"}],[968,"§۹۶۸ ۔ ثوبان انصاری(1)\nمحمد بن عبد الرحمن بن ثوبان کے دادا، ابن مندہ محمد بن حمیر کی سند سے بحوالہ عباد بن کثیر، محمد بن عبد الرحمن بن ثوبان سے وہ اپنے والد سے بحوالہ اپنے دادا روایت کرتے ہیں، فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: جسے تم مسجد میں شعر کہتے سنو اسے کہو: اللہ تمہارے دانت توڑے۔ (حدیث) اور اسے ابو خیمہ بھی کی سند سے بحوالہ عباد بن کثیر روایت کیا تو اس میں \"دادا سے\" کے الفاظ نہیں۔ عباد اس میں ضعیف ہیں۔ یزید بن خصیفہ نے ان کے خلاف روایت کی تو کہا: محمد بن عبد الرحمن سے وہ ابو ہریرہ رضی اللہ عنہ سے، یہی محفوظ ہے جسے نسائی اور ترمذی(2) نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۲۶)\n(2) ترمذی کتاب البیوع باب النہی عن البیع فی المسجد (۱۳۲۱)"}],[969,"§۹۶۹ ۔ ثوبان(1)\nعمر بن حکم ابن ثوبان کے دادا۔ ابن ابی عاصم(2) نے ان کا تذکرہ کیا ہے اور عبید اللہ بن عبد اللہ اموی کی سند سے بحوالہ عبد الحمید بن جعفر، عمر بن الحکم بن ثوبان سے وہ اپنے چچا سے وہ اپنے والد ثوبان سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے (نماز میں) کوے کی طرح ٹھونگ مارنے سے اور درندے کی طرح بیٹھنے سے منع فرمایا ہے۔ ابن مندہ فرماتے ہیں: عبد الحمید بن جعفر کے شاگردوں نے ان کے خلاف روایت کی ہے۔ چنانچہ وہ عبد الحمید کے واسطہ سے بحوالہ عمر بن حکم بن ثوبان بحوالہ عبد الرحمن مرسل روایت کرتے ہیں۔ میں کہتا ہوں: عمر بن الحکم کا شمار تابعین میں ہوتا ہے۔ وہ سعد بن ابی وقاص جیسے اکابر صحابہ سے روایت کرتے ہیں تو ان کے دادا کیسے صحابی نہیں ہو سکتے حالانکہ وہ انصاری ہیں؟","",{"fn":"(1) اسد الغابۃ (۶۲۵)\n(2) الاحاد والمثانی (۳۳۲/۱)"}],[970,"§۹۷۰ ۔ (ز) ثوبان العنسی\nعبد الرحمن بن ثابت بن ثوبان کے دادا، ابن عساکر، اوزاعی کی سند سے ثابت بن ثوبان سے وہ اپنے والد سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم کے پاس کھانا لایا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: کھانے میں امام، یا کھانا پکانے (دینے) والا یا جوان میں ٹیک ہو وہ لوگوں میں سے پہل کرے۔(1) ثابت بن ثوبان مشہور تابعی ہیں مجھے ان کے والد کا ذکر صرف اسی روایت میں ملا ہے جس میں انہوں نے سماع کا ذکر نہیں کیا، مجھے معلوم نہیں یہ روایت مرسل ہے یا نہیں۔","",{"fn":"(1) الکامل فی الضعفاء (۲۸۱/۱، ۱۶۳۸)"}],[971,"§۹۷۱ ۔ ثوب (ابو مسلم خولانی کے والد)\nیہ لفظ ثاء کے پیش اور واؤ کے زیر سے ہے۔ ابن حبان نے ثقات التابعین میں ابو مسلم خولانی کے سوانح میں ذکر کیا ہے کہ ابو مسلم اہل شام کے عبادت گزار لوگوں میں سے تھے۔ ان کے والد صحابی ہیں۔"],[972,"§۹۷۲ ۔ ثور بن عَزْرَہ(1)\nبن عبد اللہ بن سلمہ ابو الحکیر القشیری۔ ابن شاہین نے ابو الحسن مدائنی سے بحوالہ یزید بن رومان وغیرہ سے اپنے رجال کے ذریعہ نقل کیا، وہ لوگ فرماتے ہیں: ثور بن عزرہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو آپ صلی اللہ علیہ وسلم نے انہیں حمام اور سد کے مقامات عطا کیے جو عقیق میں ہیں۔ اور انہیں ایک تحریر بنا کر دی۔ اس کے متعلق شاعر کہتا ہے: \"اگر میسرہ بن بشر تجھ پر غالب آ جائے تو تیرا باپ ابو العکسیر ہے جو مقام حمام(2) میں رہتا ہے۔\"","",{"fn":"(1) اسد الغابۃ (۶۲۸)\n(2) اسد الغابۃ (۲۸۷/۱)"}],[973,"§۹۷۳ ۔ ثور السلمی(1)\nمعن بن یزید بن اخنس سلمی کے نانا۔ ان کی کنیت ابو امامہ ہے۔ ابن حبان(2) نے ان کا صحابہ میں تذکرہ کیا ہے۔ اور باوردی نے ان کے سوانح میں ابو الجویریہ کی سند سے بحوالہ معن بن یزید بن ثور روایت نقل کی کہ وہ فرماتے ہیں: میں نے، میرے والد اور میرے دادا نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی۔ اس سیاق سے یہ ظاہر ہوتا ہے کہ ثور ان کے دادا کا نام ہے جبکہ ایسا نہیں۔ کیونکہ ان کا نام تو اخنس ہے۔ بہتر روایت وہی ہے جو ابن حبان نے بیان کی۔","",{"fn":"(1) اسد الغابۃ (۶۲۹)\n(2) الثقات (۴۹/۳)"}],[974,"§۹۷۴ ۔ (ز) ثور بن معن(1)\nبن اخنس بن حبیب بن جرو بن زغب بن مالک بن خفاف بن امرئ القیس بن بھصہ بن سلیم سلمی۔ ابو علی ہجری نے نوادر میں لکھا ہے: وہ، ان کے والد اور ان کے دادا صحابی رسول صلی اللہ علیہ وسلم ہیں۔ ابن رشاطی کی روایت کے مطابق یہ لوگ بنی معن سے مشہور ہیں۔ میں کہتا ہوں: مشہور معن بن اخنس ہے، بخاری نے ان کی حدیث نقل کی ہے ان کا ذکر آ رہا ہے۔ شاید یہ ثور ان کے چچا زاد بھائی ہیں۔ واللہ اعلم۔ اگر یہ بات پایہ ثبوت تک پہنچ جائے تو معن بن اخنس، معن بن یزید الانفس کے چچا ٹھہرے۔","",{"fn":"(1) بخاری کتاب الزکاۃ باب اذا تصدق علی ابنہ وھو لا یشعر (۱۴۲۲) مسند احمد (۴۷۰/۳، ۲۵۹/۴) المعجم الکبیر (۱۴۵۵/۲) فتح الباری (۲۹۱، ۲۹۲/۳)"}],[975,"§۹۷۵ ۔ (ز) ثابت بن مرعی\nبن سنان بن سنان بن سنان بن ثعلبہ۔ ان کے والد کے سوانح میں ان کا نسب آ رہا ہے۔ بقول عدوی: یہ رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں پیدا ہوئے، سمرہ بن جندب رضی اللہ عنہ کے ماں شریک بھائی ہیں۔ ابن فتوحون(1) نے ان کا استدراک کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۵۷۱)"}],[976,"§۹۷۶ ۔ ثابت بن طریف المرادی(1)\nفتح مصر میں شریک تھے ان لوگوں سے ہیں جنہوں نے زمانہ جاہلیت پایا ہے۔ ابن مندہ نے بحوالہ ابن یونس اور ابن حبان(2) نے ثقات التابعین میں ان کا ذکر کیا ہے۔ حاکم نے ابن عبد الاعلیٰ یعنی ابن یونس کے حوالہ سے ذکر کیا ہے کہ وہ صحابی ہیں۔ جنہوں نے دور جاہلیت پایا ہے۔ ابن الاثیر نے ان کا تعاقب کرتے ہوئے کہا کہ ابن مندہ نے ان کے صحابی ہونے کی تصریح نہیں کی۔ ان کا ذکر تو اس لحاظ سے کیا ہے کہ انہوں نے دور نبوی پایا ہے۔ اور جو لوگ سیدنا عمر رضی اللہ عنہ کے دور میں فتوحات میں شریک رہے۔ انہوں نے زمانہ نبوی پایا ہے لیکن ان میں سے بعض کو شرف صحابیت حاصل ہے اور بعض اس سے محروم ہیں، او مختصراً۔(3)","",{"fn":"(1) اسد الغابۃ (۵۶۰)\n(2) الثقات (۹۴/۴)\n(3) اسد الغابۃ (۲۶۱/۱)"}],[977,"§۹۷۷ ۔ ثعلبہ بن ابی رقیہ اللخمی(1)\nابن یونس نے ان کا ذکر کیا کہ وہ فتح مصر میں شریک تھے ایسے ہی ابن مندہ نے ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۵۹۲)"}],[978,"§۹۷۸ ۔ (ز) ثمامہ بن اوس\nبن ثابت بن لام طائی۔ سیف نے فتوح میں ان کا ذکر کیا ہے، انہوں نے خلافت ابی بکر میں ضرار بن ازور کی طرف سے پیام بھیجا جبکہ وہ طلیحہ سے بر سر پیکار تھے کہ میرے ساتھ جذیمہ قبیلہ کے پانچ سو آدمی ہیں۔ پھر وہ قصہ ذکر کیا جس سے معلوم ہوتا ہے انہوں نے دور جاہلیت پایا ہے۔"],[979,"§۹۷۹ ۔ ثمامہ بن حزن(1)\nبن عبد اللہ بن سلمہ بن قشیر بن کعب بن ربیعہ بن عامر بن صعصعہ قشیری ابو الورد بن ثمامہ کے والد۔ نبی صلی اللہ علیہ وسلم کے عہد میں نوجوان آدمی تھے۔ مسلم نے مختصرین میں اور ابن حبان(2) نے ثقات التابعین میں شمار کیا ہے۔ بقول ابو نعیم: انہوں نے دور نبوی تو پایا لیکن آپ صلی اللہ علیہ وسلم کو نہ دیکھ پائے۔ تاریخ بخاری(3) میں لکھا ہے: وہ سیدنا عمر رضی اللہ عنہ کی خلافت میں ان کے پاس آئے۔ اس وقت ان کی عمر پینتالیس سال تھی۔ اور بقول ابن عبد البر بنی عامر کے بعض اہل نسب نے ذکر کیا کہ ثمامہ بن حزن صحابی ہیں۔","",{"fn":"(1) اسد الغابۃ (۶۲۲)\n(2) الثقات (۹۷/۴)\n(3) التاریخ الکبیر (۱۷۶/۲)"}],[980,"§۹۸۰ ۔ (ز) ثمامہ الردمانی ان کے غلام\nخارجہ بن عراک۔ انہوں نے زمانہ نبوی پایا ہے اور اپنے آقا کے ساتھ فتح مصر میں عمرو بن العاص کی معیت میں شریک تھے۔ ابن یونس نے ان کا ذکر کیا ہے۔"],[981,"§۹۸۱ ۔ ثور بن تلدہ(1)\nانہیں باء سے ثوب بھی کہا جاتا ہے۔ یوں اس نام کو قلمبند کرنے میں اختلاف رونما ہوا۔ بقول ابن کلبی: ثیاب واحد کا لفظ ہے اور جسے دارقطنی نے یثم بن عدی کی پیروی میں ثاء کے پیش کے واؤ کے زبر سے لکھا ہے۔ رہا ان کے والد کا نام تو یثم اور ابن کلبی نے کہا: وہ ثاء کے زیر اور لام کے سکون سے ہے جبکہ دارقطنی نے تاء کے زبر سے تحریر کیا ہے۔ نیز انہیں تصغیر سے تثلیدہ کہا جاتا ہے ان کا تعلق بنی والبہ بن حارث بن ثعلبہ بن دودان بن اسد بن خزیمہ، بقول بعض تلدہ یا تلیدہ ان کی والدہ، باندی یا انہیں گود لینے والی خاتون ہے اور ان کے والد کا نام ربیعہ ہے۔ یہ بات سیف نے فتوح میں ذکر کی ہے۔ ابو حاتم بستانی(2) نے معمرین میں ان کا ذکر کرتے ہیں کہ وہ امیر معاویہ کے پاس آئے تھے، آپ نے ان سے پوچھا: میرے آباء و اجداد میں سے تم نے کسی کا زمانہ پایا ہے؟ تو وہ بولے: امیہ بن عبد شمس کا دور میں نے پایا ہے۔ وہ نابینے ہو گئے تھے۔ اور ان کا غلام ذکوان ان کا ہاتھ تھامے لے جاتا تھا۔ سیدنا معاویہ جھٹ سے بولے: ارے وہ تو ان کا بیٹا تھا۔ وہ کہنے لگے: یہ بات تو آپ لوگ کہتے ہیں۔ سیدنا معاویہ نے فرمایا: ان لوگوں میں سے امیہ کے زیادہ مشابہ کون ہے؟ وہ بولے: یہ اور عمرو بن العاص بن امیہ کی جانب اشارہ کیا۔ جو \"اشدق\" کے عرف سے مشہور ہیں۔ اس قصہ کا کچھ حصہ ابو موسیٰ نے ذیل میں ابو یعقوب سراج کی سند سے نقل کیا ہے کہ انہوں نے ان کا صحابہ میں ذکر کیا ہے جس کی سند عاصم بن ابی النجود سے ہے، فرمایا: ہم یعنی بنی اسد بن خزیمہ بدر کے روز مہاجرین کا ساتواں حصہ تھے۔ ہمارا ایک آدمی تھا جس کا نام ثور بن تلدہ تھا اس کی عمر ایک سو بیس(۱۲۰) سال ہو گئی تھی پھر کچھ واقعہ ذکر کیا۔ ابو موسیٰ، عاصم کی یہ بات \"ہمارا ایک آدمی تھا\" سے یہ سمجھ بیٹھے کہ اس کا تعلق \"ہم بدر کے روز\" سے ہے، یوں صاحب عنوان شخصیت بدریین میں شمار ہوتی ہے جبکہ ایسا نہیں۔ بلکہ عاصم کا ارادہ اپنی قوم کی خصوصیات شمار کرنا ہے۔ اس لیے انہوں نے ذکر کیا کہ وہ مہاجرین کا ساتواں حصہ تھے اور ان میں اس عمر رسیدہ شخص کا تذکرہ کیا۔ اگر بات بظاہر ایسی ہوتی جیسی ابو موسیٰ سمجھے ہیں تو \"ہم\" کہنے سے عاصم بھی بدریین میں شمار ہوتے، جبکہ وہ چھوٹے تابعی ہیں، ان کی روایات تابعین سے ہے۔ دارقطنی نے مؤتلف میں ابو بکر بن عیاش کی سند سے بحوالہ عاصم روایت کی فرمایا کہ ثور بن تلدہ نے فرمایا: میں نے والبات کی تین پشتیں دیکھی ہیں۔ راوی کا بیان ہے کہ ان کی عمر دو سو چالیس(۲۴۰) سال ہو گئی تھی۔ ابن کلبی نے ان کا شعر کہا ہے۔ اگر آدمی نوے سے دو سو سال تک بھی زندہ رہے یہ ساری مدت اپنی جگہ پھر بھی اس نے جانا ہے۔ فرماتے ہیں: مجھے معلوم نہیں جب انہوں نے امیر معاویہ کے سامنے یہ اشعار کہے پھر اس کے بعد زندہ رہے یا نہیں۔ سیف بن عمر نے ذکر کیا کہ وہ فتوحات میں شریک اور قادسیہ میں موجود تھے اس میں انہوں نے اشعار کہے، مرزبان نے ان کے وہ اشعار نقل کیے ہیں جو آمدی نے کسی اور کے حوالہ سے ذکر کیے ہیں۔ ان شاء اللہ تعالیٰ حرف نون میں نمیر بن ثور بجلی کے سوانح میں آئے گا۔","",{"fn":"(1) اسد الغابۃ (۶۲۷)\n(2) المعمرین (۸۴/۱)"}],[982,"§۹۸۲ ۔ (ز) ثور بن قدامہ\nدور نبوی پایا ہے اور فتوح میں وہ کافی معرکوں میں رہے۔ امام بخاری رحمہ اللہ نے ان کی سند سے نقل کیا، فرمایا: ہمارے پاس سیدنا عمر رضی اللہ عنہ کا خط آیا۔ ان سے ابراہیم عقیلی روایت لیتے ہیں۔ ابن حبان(1) نے ان کا ثقات التابعین میں ذکر کیا ہے۔","",{"fn":"(1) الثقات (۱۰۰/۴)"}],[983,"§۹۸۳ ۔ ثور بن مالک الکندی\nنبی صلی اللہ علیہ وسلم کے عہد میں تھے اور یمن تھے، معاذ بن جبل رضی اللہ عنہ کے ساتھ تھے۔ جنب سیدنا معاذ رضی اللہ عنہ کو نبی صلی اللہ علیہ وسلم کی وفات کی اطلاع ملی تو انہیں اپنا نائب بنا کر گئے۔ یہ روایت وثیمہ نے بحوالہ ابن اسحاق ان کا ذکر کیا ہے، جنب اہل کندہ نے ارتداد کا پختہ عزم کر لیا تو انہوں نے وہاں جو تاریخی خطاب کیا وہ بھی ذکر کیا ہے اور ان کا جواب بھی بیان کیا ہے پھر ان کی جو بات چلی یہاں تک کہ مسلمانوں نے ان لوگوں پر حملہ کر دیا چنانچہ وہ ان اشعار میں کہتے ہیں: \"میں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کا دین اختیار کیے رہو تو وہ بے وقوفی سے کہنے لگے: تمہارے منہ میں خاک پڑے۔ پھر کیا تھا ان کی ہلاکت پر میں رونے لگا جو کچھ انہوں نے کیا میں اس میں شریک نہ ہوا۔\""],[984,"§۹۸۴ ۔ (ز) ثابت بن اجدع\nثابت ابن الجذرع میں تذکرہ ہو چکا ہے۔"],[985,"§۹۸۵ ۔ ثابت بن ابی الاقلاع\nابو تیم نے دلائل میں محمد بن مروان کی سند سے بحوالہ کلبی، ابو صالح سے ابن عباس رضی اللہ عنہ کی روایت نقل کی ہے کہ عقبہ بن ابی معیط کو بدر سے قید کے بعد ثابت بن ابی الاقلاع نے قتل کیا۔ مشہور یہ ہے کہ اسے عاصم بن ثابت بن ابی الاقلاع نے قتل کیا تھا۔"],[986,"§۹۸۶ ۔ (ز) ثابت بن ابی زید الانصاری\nبعض نے حاکم کی کتاب \"علوم الحدیث\" کی طرف نسبت کرتے ہوئے ان کا تذکرہ کیا ہے کہ عزرہ بن ثابت، محمد بن ثابت اور علی بن ثابت ان کے والد ثابت بن ابی زید صحابی رسول صلی اللہ علیہ وسلم ہیں۔ لفظ صحابی مجرور واقع ہو کر ابو زید کی صفت ہے۔ جنہوں نے انہیں صحابہ میں ذکر کیا وہ یہ سمجھے کہ یہ لفظ مرفوع ہے، اس صورت میں وہ ثابت کی صفت بن جائے گی جبکہ ایسا نہیں۔ واللہ اعلم"],[987,"§۹۸۷ ۔ ثابت بن الضحاک(1)\nبن ثعلبہ۔ ابو موسیٰ نے بحوالہ سعید بن یعقوب سراج ان کا استدراک کیا ہے۔ استدراک کی کوئی وجہ بنی نہیں اس لیے کہ ابن مندہ نے ان کا صحیح اندراج کیا ہے۔ جبکہ نسب سے صرف ایک شخص ساقط ہوا ہے اور وہ ثابت بن الضحاک بن خلیفہ بن ثعلبہ ہے جیسا کہ قسم اول میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۵۵۸) الاستيعاب (۲۶۱)"}],[988,"§۹۸۸ ۔ ثابت بن عمرو انصاری(1)\nبدر(2) میں شریک ہوئے۔ ابو تیم نے بحوالہ موسیٰ بن عقبہ ابن ان کے اور انھجی جو انصار کے حلیف ہیں اور ان کا تذکرہ پہلے ہو چکا ہے کے درمیان فرق کر کے ان کا ذکر کیا ہے۔ حالانکہ وہ ایک شخصیت ہے۔ انہیں وہم ہو گیا۔","",{"fn":"(1) اسد الغابۃ (۵۶۷) تجرید (۶۴/۱)\n(2) اسد الغابۃ (۲۶۳/۱)"}],[989,"§۹۸۹ ۔ (ز) ثابت بن قیس انصاری\nحدیث جابر میں ان کا تذکرہ آتا ہے۔ ابو داؤد فرماتے ہیں: اس کے راوی سے غلطی ہوئی ہے۔ ابو داؤد، قاضی اسماعیل(1) نے \"احکام\" میں اور ابو مسلم کجی نے \"سنن\" میں بشر بن مفضل کی سند سے بحوالہ ابن عقیل، جابر رضی اللہ عنہ سے روایت کی ہے، فرمایا: ہم لوگ نبی صلی اللہ علیہ وسلم کی معیت میں نکلے۔ چلتے چلتے ہم لوگ انصار کی ایک خاتون کے ہاں آئے، وہ جلدی سے دو بچیاں لا کر کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم! یہ دونوں ثابت بن قیس کی بیٹیاں ہیں۔ وہ آپ صلی اللہ علیہ وسلم کے ساتھ احد میں شرکت کے باعث شہید ہو گئے۔ (حدیث) ابو داؤد فرماتے ہیں: راوی سے غلطی ہوئی جبکہ صحیح یہ ہے کہ وہ سعد بن ربیع ہیں۔ اس کے بعد ابن وہب کی سند سے بحوالہ داؤد بن قیس وغیرہ سے، ابن عقیل سے نقل کرتے ہیں، فرماتے ہیں کہ عبید اللہ بن عمرو نے بحوالہ ابن عقیل ایسا ہی فرمایا ہے۔ جو درست ہے۔ میں کہتا ہوں: اگر حدیث کا مخرج ایک نہ ہوتا تو واقعہ میں تعدد ہو سکتا تھا۔","",{"fn":"(1) ابوداؤد کتاب الفرائض باب ماجاء فی میراث الصلب (۲۸۹۱)"}],[990,"§۹۹۰ ۔ (ز) ثابت بن قیس (دوسرے)\nابو المتوکل، میم میں، کنیتوں میں تذکرہ آئے گا۔"],[991,"§۹۹۱ ۔ ثابت بن مسعود(1)\nعبدان نے ان کا مختصر ذکر کیا ہے کہ ان کا صرف صفوان بن محرز کی حدیث میں تذکرہ آتا ہے۔ جبکہ سعید بن یعقوب سراج نے صحابہ میں ان کا ذکر کیا ہے۔ اور حماد بن ثابت بنانی کی سند سے بحوالہ صفوان بن محرز ان کی روایت نقل کی ہے، فرمایا: میں مقام ابراہیم کے پیچھے نماز پڑھتا تھا، میرے ساتھ ایک صحابی رسول صلی اللہ علیہ وسلم ہوتے، جنہیں وہ ثابت بن مسعود سمجھتے ہیں۔ فرمایا: میں جب اونچی آواز میں قراءت کرتا وہ اپنی آواز پست کر لیتے۔ میں نے ان سے اچھا کوئی پڑوسی نہیں دیکھا۔ مجھے جب اٹکن ہوتی تو وہ فتح (لقمہ) دے دیتے۔ نماز سے فراغت کے بعد میں طواف میں شامل ہو گیا۔ بعد میں وہ بھی آ گئے اور میرا ہاتھ تھام کر فرمانے لگے: \"رو میں جمع کیا ہوا لشکر ہیں۔\" (حدیث)(2) \"ذیل،\" میں ابو موسیٰ لکھتے ہیں: انہوں نے ایسا ہی درج کیا۔ دو حافظ الحدیث شخصیتوں پر تعجب ہے کہ ان سے یہ بھول کیسے ہو گئی؟ درست عبارت یوں ہے: ہمارے خیال میں وہ ثابت (جو البنانی ہیں) بن مسعود ہیں۔ ابن مسعود نحسبہ کا مفعول ثانی ہے جس سے عبد اللہ بن مسعود مراد ہیں۔ میں کہتا ہوں: باوردی نے اس سلسلہ میں ان سے اتفاق کیا ہے اور ثابت بن مسعود کا عنوان قائم کیا ہے اور یہ حدیث انہی کے سوانح میں حماد کی سند سے بحوالہ ثابت روایت کی ہے جہاں تک ابو عمر کا تعلق ہے تو وہ فرماتے ہیں: ثابت بن مسعود، فرمایا: صفوان بن محرز نے جو اصحاب رسول صلی اللہ علیہ وسلم میں سے ایک شخص میرے پڑوسی تھے، میرے گمان میں وہ ثابت بن مسعود تھے، میں نے ان سے بڑھ کر اچھا پڑوسی نہیں دیکھا۔ پھر وہ روایت ذکر کی: یہ ان کے الفاظ ہیں۔ ثابت کے حذف سے جو اسے صفوان سے روایت کرنے والے ہیں یہ یقین پیدا ہو جاتا ہے کہ جنہیں وہ ابن مسعود سمجھ بیٹھے وہ صفوان ہیں۔ ذہبی(3) نے \"تجرید\" میں یہ ابو عمر کا عیب شمار کیا ہے۔ میں کہتا ہوں: مجھے یہاں صفوان بن محرز کی جانب سے توقف ہے اس لیے کہ میرے خیال میں انہوں نے ابن مسعود کو نہیں دیکھا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۵۷۲) الاستيعاب (۲۶۶)\n(2) بخاری کتاب الانبیاء باب الارواح جنود مجندة (۳۳۳۶) مسلم کتاب البر والصلة باب الارواح جنود مجندة (۵۶۵۰، ۵۶۵۱) ابوداؤد کتاب الادب باب من یومر ان یجالس (۳۸۳۴) مسند احمد (۵۳۹/۲) المعجم الکبیر (۳۲۳/۶) حلیۃ الاولیاء (۱۹۸/۱) المستدرک (۲۴۰، ۲۴/۴)\n(3) التجريد (۲۵/۱)"}],[992,"§۹۹۲ ۔ (ز) ثابت بن معاذ انصاری\nسیدنا انس رضی اللہ عنہ کی ایک حدیث جو ضعیف سند سے بیان کی گئی ہے اس میں ان کا ذکر آتا ہے جسے خطیب نے \"مؤتلف\" میں قاسم بن خلیفہ کی سند سے بحوالہ ابو بکر تیمی اسماعیل بن ابراہیم، مطیر ابو خالد سے وہ انس بن مالک رضی اللہ عنہ سے، روایت کیا ہے۔ فرماتے ہیں: \"ہم لوگ جب رسول اللہ صلی اللہ علیہ وسلم سے کوئی بات پوچھنا چاہتے تو سیدنا علی، سلمان فارسی یا ثابت بن معاذ رضی اللہ عنہم نے کہتے، کیونکہ صحابہ میں یہ لوگ آپ صلی اللہ علیہ وسلم کے سامنے جرات کر لیتے تھے۔ پھر جب ((إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ)) (سورۃ النصر: ۱) نازل ہوئی۔\" اس کے بعد راوی نے سیدنا علی رضی اللہ عنہ کی فضیلت میں ایک منکر (ضعیف راوی کی ایسی روایت جو ثقات کے خلاف ہے) حدیث ذکر کی۔ اس میں ہے: \"یہ (علی رضی اللہ عنہ) میرے بھائی، میرے وزیر، میرے اہل بیت میں میرے خلیفہ اور میرے بعد خلیفہ ہونے کے لئے بہترین آدمی ہیں۔\" خطیب(1) فرماتے ہیں: مطیر مجہول راوی ہے۔ میں کہتا ہوں: جبکہ ابو بکر تیمی تو بے حد کمزور راوی ہے۔","",{"fn":"(1) السلسلۃ الصحیحۃ (۱۷۵۰)"}],[993,"§۹۹۳ ۔ ثابت بن معبد(1)\nتابعی، مرسل اور موصول روایت کر دیتے ہیں جس سے بعض راویوں کو شبہ ہو جاتا ہے۔ ابن مندہ نے ان کا ذکر کیا اور ان کے متعلق وہم کی وجہ بیان کی۔ فرمایا: عمرو بن خالد نے عبید اللہ بن عمرو سے بحوالہ عمرو بن عمیر وہ کلب کے ایک شخص سے بحوالہ ثابت بن معبد روایت کی ہے کہ ایک شخص نے نبی صلی اللہ علیہ وسلم سے ایک عورت کے بارے میں پوچھا جس کے حسن سے وہ متاثر ہو گیا تھا۔ (حدیث)(2) عمرو نے ایسا ہی کہا۔ جبکہ علی بن سعید وغیرہ نے اسے عبید اللہ بن عمرو سے بحوالہ عبد الملک انہوں نے ثابت بن معبد سے وہ کلب کے ایک شخص کے واسطہ سے یہ روایت نقل کرتے ہیں۔ ابن مندہ فرماتے ہیں: یہی درست ہے، اسے عمرو بن خالد نے آگے پیچھے کر دیا تھا۔ تاریخ بخاری میں ہے: ثابت بن معبد سے وہ کلب کے ایک شخص کے واسطہ سے یہ روایت نقل کرتے ہیں۔ ابن مندہ فرماتے ہیں: یہی درست ہے، اسے عمرو بن خالد نے آگے پیچھے کر دیا تھا۔ تاریخ بخاری میں ہے: ثابت بن معبد سے عبد الملک بن عمیر کوفیوں میں ان کی منقطع حدیث روایت کرتے ہیں۔ ابن حبان(3) نے \"تابعین\" میں لکھا ہے، ثابت بن معبد اپنے چچا سے روایت کرتے ہیں اور ان سے عبد الملک بن عمیر روایت لیتے ہیں۔ ابن ابی حاتم(4) اپنے والد کے حوالہ سے فرماتے ہیں: ثابت بن معبد سیدنا عمر بن الخطاب رضی اللہ عنہ سے روایت کرتے ہیں اور ان سے عبد الملک، ابن مندہ فرماتے ہیں: وہ تابعی ہیں اہل کوفہ میں ان کا شمار ہوتا ہے۔","",{"fn":"(1) اسد الغابۃ (۵۷۳) تجرید (۶۵/۱)\n(2) اسد الغابۃ (۲۶۶/۱) معرفۃ الصحابۃ (۲۵۳/۳)\n(3) الثقات (۹۲/۴)\n(4) الجرح والتعدیل (۴۵۷/۲)"}],[994,"§۹۹۴ ۔ ثابت بن المنذر(1)\nبن حرام بن عمرو از بنی مالک بن نجار بن اوس۔ بدر میں شریک تھے ایسا ہی ابن مندہ نے نقل کیا اور پھر ابن اسحاق تک اپنی سند سے بیان کیا: وہ لوگ جو بدر میں شریک ہوئے ان کے نام یہ ہیں: از بنی مالک بن نجار بن اوس بن ثابت بن المنذر پھر ان کا تذکرہ کیا۔ ابو تیم نے ان کا تعاقب کرتے ہوئے لکھا ہے: یہ کھلا وہم ہے اس واسطے کہ نجار تو ثعلبہ بن مالک کے بیٹے ہیں۔ درست نسب وہ ہے جو ابراہیم بن سعد وغیرہ نے ابن اسحاق سے نقل کیا ہے۔ وہ فرماتے ہیں: بنی عمرو بن مالک بن نجار سے اوس بن ثابت بن المنذر بن منذر بن حرام بدر میں شریک ہوئے۔ تو کاتب نے اوس سے پہلے ابن بڑھا دیا جس سے یہ انتہائی برا وہم پیدا ہو گیا۔ ابن مندہ جیسے پیشوا شخص سے یہ بات کیسے پوشیدہ رہ گئی کہ ثابت بن منذر جو سیدنا حسان اور ان کے بھائیوں کے والد ہیں انہوں نے اسلام کا دور نہیں پایا ہے؟ ادھر موسیٰ بن عقبہ نے مغازی میں اوس بن ثابت کا ذکر بدریین میں صحیح طرح کیا ہے۔ اور کئی لوگوں نے اس طرح ذکر کیا ہے جیسا پہلے ان کے سوانح میں گزر چکا ہے۔ اس میں طبرانی سے بھی بھول ہو گئی چنانچہ وہ لکھتے ہیں: ثابت بن منذر بن حرام۔ اور ابن لہیعہ تک اپنی سند میں: ابو الاسود سے بحوالہ عروہ، اہل بدر کے نام لیتے ہوئے فرماتے ہیں: بنی مالک بن نجار سے ثابت بن المنذر۔(2) ابو تیم کا خیال ہے کہ وہم ابن لہیعہ کی وجہ سے پیدا ہوا۔ فاللہ اعلم اس کی نظیر ابن عبد البر کے ساتھ حارثہ بن مالک کے سوانح میں بھی پیش آئی ہے۔","",{"fn":"(1) اسد الغابۃ (۵۷۴)\n(2) المعجم الکبیر (۷۷/۲) السیرۃ النبویۃ (۱۱۸/۳)"}],[995,"§۹۹۵ ۔ ثابت بن واثلہ(1)\nخیبر میں شہید ہوئے۔ ابن عبد البر(2) نے ایسا ہی درج کیا ہے البتہ انہوں نے ان کے والد کا نام بدل دیا۔ جو واثلہ حمزہ کے زبر اور ثاء کے سکون سے ہے جیسا کہ پہلے درست گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۵۷۹) الاستيعاب (۲۶۷)\n(2) الاستيعاب (۲۸۲/۱)"}],[996,"§۹۹۶ ۔ ثابت بن وقش(1)\nبن زغوراء۔ احد میں شہید ہوئے۔ ابن شاہین نے ان کا تذکرہ کیا ہے ان میں اور ثابت بن وقش بن زغبہ بن زغوراء میں فرق کیا ہے۔ بقول ابن الاثیر(2) یہ فرق بہت بعید ہے۔ پھر فرمایا: اس میں تو شک نہیں کہ دونوں ایک ہی شخصیت ہیں۔ نسب سے زغبہ کے رہ جانے سے یہ پتہ نہیں چلتا کہ دونوں میں فرق ہے۔","",{"fn":"(1) اسد الغابۃ (۵۸۱) الاستيعاب (۲۵۸) تجرید (۶۵/۱)\n(2) اسد الغابۃ (۲۶۹/۱)"}],[997,"§۹۹۷ ۔ ثابت بن یزید الانصاری(1)(2)\nباوردی اور ابو تیم نے ان کا صحابہ میں ذکر کیا ہے اور شریک کی سند سے بحوالہ ابو اسحاق، عامر بن سعد سے روایت کرتے ہیں۔ فرمایا: میں قرظہ بن کعب ثابت بن یزید اور ابو مسعود کے پاس آیا تو وہاں چھوکریاں اور دوسری لہو و لعب کی چیزیں تھیں۔ میں نے تعجب سے کہا: آپ لوگ اصحاب رسول ہو کر یہ شغل کر رہے ہیں؟ وہ حضرات بولے: ہمیں شادی کے موقع پر اتنے لہو و لعب کی اجازت ہے۔ میں کہتا ہوں: یہ ثابت بن یزید وہی ابن ودیعہ ہیں۔ جس نے انہیں دو شخصیتین سمجھا اسے وہم ہوا ہے۔ چنانچہ ابو داؤد طلیا کی اپنی مسند میں شعبہ سے بحوالہ ابو اسحاق یہ حدیث روایت کرتے ہوئے فرماتے ہیں: ثابت بن ودیعہ۔ ابو اسحاق سے کئی طرق کے ذریعہ یہ روایت محفوظ ہے۔ اس سے زیادہ تعجب کی بات یہ ہے کہ ابن ابی حاتم سے یہ نام تبدیل ہو گیا۔ ودیعہ کی جگہ وداۃ کر دیا۔ ان میں اور ثابت بن یزید بن ودیعہ کے درمیان فرق کیا چنانچہ وہ لکھتے ہیں: ثابت بن یزید بن ودیعہ بن ودیعہ کے رہنے والے صحابی ہیں۔ ان سے براء، زید بن وہب اور عامر بن سعد روایت کرتے ہیں۔ جبکہ اس سے پہلے لکھتے ہیں: \"ثابت بن یزید بن ودیعہ\" اور اسی طرح کی بات ذکر کی۔ اور اس سے پہلے انہوں نے فرمایا: ثابت بن زید صحابی ہیں جن سے عامر بن سعد وغیرہ روایت کرتے ہیں، یوں ایک شخصیت سے تین افراد قرار دیئے۔","",{"fn":"(1) اسد الغابۃ (۵۸۴) تجرید (۶۵/۱)\n(2) ابوداؤد طیالسی فی مسندہ (۱۲۲۱)"}],[998,"§۹۹۸ ۔ ثابت بن یزید\nابو اسید انصاری ابن مندہ نے ان کا تذکرہ کیا ہے۔ مشہور یہ ہے کہ ان کا نام عبد اللہ بن ثابت ہے جیسا کہ اپنے مقام پر آئے گا۔ \"زیتون کھایا کرو\" (حدیث)(1) حدیث کے راوی ہیں، بقول بعض ان کا نام ان کی کنیت ہے۔","",{"fn":"(1) ترمذی کتاب الاطعمۃ باب ما جاء فی اکل الزیت (۱۸۵۱، ۱۸۵۲) ابن ماجہ باب الزیت (۳۳۱۹، ۳۳۲۰) مسند احمد (۴۹۷/۳) دارمی باب فضل الزیت (۱۰۲/۲) المعجم الکبیر (۲۷۰/۱۹) المستدرک (۳۹۸/۲) علل الحدیث (۱۲۵۰)"}],[999,"§۹۹۹ ۔ ثابت انصاری\nعدی بن ثابت کے والد، ابو موسیٰ نے ذیل میں بحوالہ ابن ماجہ ان کا ذکر کیا ہے اور ہم ثابت بن قیس بن خطیم کا ذکر پہلے کر چکے ہیں۔ اگر ابن کلبی کی بات صحیح ثابت ہو جائے کہ عدی بن ثابت ہی ابن ابان بن ثابت بن قیس بن خطیم ہے اور عدی کی نسبت ان کے دادا کی طرف بھی کی جاتی ہے۔ تو پھر یہ بات ثابت ہو جائے گی کہ انہیں شرف صحابیت حاصل ہے۔ ورنہ نہیں۔ اس کے باوجود ان کے دوبارہ ذکر کرنا زاوہم ہے۔ واللہ اعلم"],[1000,"§۱۰۰۰ ۔ ثعلبہ بن الجذع\nابن مندہ نے ان کا تذکرہ کیا کہ وہ بدر میں شریک تھے۔ ان میں اور ثعلبہ بن حارث جن کا لقب جذع ہے فرق کر کے ان کے لقب کو ان کے والد کا نام قرار دے کر دوسری شخصیت سمجھ بیٹھے۔ ان لوگوں کے اوہام کو ہم پہلے بیان کر آئے ہیں۔ جو ثعلبہ بن زید بن حارث کے سوانح میں ہے وہاں ہم نے اسے درست ذکر کیا ہے۔"],[1001,"§۱۰۰۱ ۔ ثعلبہ بن زبیب العنبری(1)\nان سے ان کے بیٹے عبد اللہ روایت کرتے ہیں جس میں ارسال اور ضعف ہے تجرید میں ایسا ہی تحریر ہے۔ میں کہتا ہوں: یہ نسب پلٹ گیا ہے جبکہ یہ \"عبد اللہ بن زبیب بن ثعلبہ\" وہ اپنے والد سے روایت کرتے ہیں۔","",{"fn":"(1) اسد الغابۃ (۵۹۴) تجرید (۶۷/۱)"}],[1002,"§۱۰۰۲ ۔ ثعلبہ بن العلاء الکنانی(1)\nابو احمد العسال نے صحابہ میں ان کا تذکرہ کیا ہے۔ اور حجاج بن ارطاۃ کی سند سے بحوالہ سماک بن حرب، ثعلبہ بن العلاء کنانی سے روایت نقل کی ہے۔ فرمایا: میں نے خیبر(2) کے روز نبی صلی اللہ علیہ وسلم کو فرماتے سنا آپ صلی اللہ علیہ وسلم مثلہ (ناک، کان، ہونٹ کاٹ کر عیب دار) کرنے سے منع فرما رہے تھے۔ ابو موسیٰ فرماتے ہیں: اسے زہیر بن معاویہ نے سماک بن حرب سے بحوالہ ثعلبہ بن حکم بن لیث کے بھائی سے اسی مفہوم میں نقل کیا ہے۔ میں کہتا ہوں: بنی لیث کا تعلق بنی کنانہ سے اس لحاظ سے نسب ایک ہوا اور راوی بھی ایک۔ ہاں یہ ہو سکتا ہے کہ حجاج کو ان کے والد کے نام میں وہم ہو گیا یا علاء ان کے آباء میں سے کسی کا نام ہو۔ قسم اول میں ثعلبہ بن حکم کا درست عنوان گزر چکا ہے۔ اس کی نظیر ابن عبد البر کے ساتھ حارثہ بن مالک کے سوانح میں بھی پیش آئی ہے۔","",{"fn":"(1) اسد الغابۃ (۶۰۸) تجرید (۶۸/۱)\n(2) ابن ماجہ کتاب الفتن باب النھی عن النھبۃ (۳۹۳۸) المصنف لعبد الرزاق (۱۸۸۴۱) المعجم الکبیر (۱۲۷۵) مجمع الزوائد (۴۹/۵) جامع المسانید والسنن (۴۳۲/۲) معرفۃ الصحابۃ (۲۵۶/۳)"}],[1003,"§۱۰۰۳ ۔ (ز) ثعلبہ بن مُغَن\nبن محصن از بنی عامر بن مالک بن نجار، ابن فتوحون نے ان کے بارے تلافی مافات کی ہے اور کہا کہ ابن ابی حاتم(1) نے بحوالہ اپنے والد ان کا ذکر کیا ہے۔ میں کہتا ہوں: یہ نام ابن ابی حاتم کی کتاب کے اکثر نسخوں میں ثعلبہ بن عمرو بن محصن ہے ابو عمر نے ان کا حوالہ دیا اس لیے استدراک کی ضرورت نہیں۔","",{"fn":"(1) الجرح والتعدیل (۴۶۱/۲)"}],[1004,"§۱۰۰۴ ۔ ثعلبہ البہرانی(1)\nعبدان نے ان کا ذکر کیا اور موسیٰ بن امین کی سند سے بحوالہ عبد الکریم جزری، فرات سے وہ ثعلبہ بہرانی سے مرفوع روایت کرتے ہیں: \"عنقریب علم اٹھک لیا جائے گا۔\" (حدیث)(2) یہ سلسلہ سند غلط ہے جو لفظی غلطی سے پیدا ہوا۔ روایت فرات بن ثعلبہ سے ہے۔ لفظ ابن کو عن بنا دیا گیا۔ فرات بن ثعلبہ مشہور تابعی ہیں۔ ابن حبان نے ان کا ثقات التابعین میں ذکر کیا ہے کہ اہل شام ان سے روایت کرتے ہیں۔ بقول ابو موسیٰ: مذکورہ حدیث ابو درداء رضی اللہ عنہ سے مشہور ہے۔","",{"fn":"(1) اسد الغابۃ (۵۸۷) تجرید (۶۶/۱)\n(2) کنز العمال حدیث (۳۸۵۲۴)"}],[1005,"§۱۰۰۵ ۔ الثلب العنبری\nابن الامین نے استدراک کرتے ہوئے ان کا ذکر کیا ہے، درست تاء سے ہے جیسا کہ پہلے گزر چکا اور قسم اول میں اس پر تنبیہ بھی کی گئی ہے۔"],[1006,"§۱۰۰۶ ۔ (ز) ثَلْدَہ الاسدی\nابن الامین وغیرہ نے ان کا استدراک کیا ہے جو وہم پر مبنی ہے۔ درست ثور یا ثوب بن ثلدہ ہے جیسا کہ قسم ثالث میں گزر چکا ہے۔ اور وہاں یہ بھی بتایا جا چکا ہے کہ بقول عوام ثلدہ ان کی والدہ کا نام ہے۔"],[1007,"§۱۰۰۷ ۔ (ز) ثوبان بن فزارہ العامری\nمرزبانی نے معجم الشعراء میں ثوبان نامی لوگوں میں رسول اللہ صلی اللہ علیہ وسلم کے غلام ثوبان کے ساتھ ان کا ذکر کیا ہے۔ مگر ان سے لفظی غلطی ہوئی ہے۔ درست ثوبان راء پھر واؤ سے ہے جیسا کہ پہلے قسم اول میں گزر چکا ہے۔"],[1008,"§۱۰۰۸ ۔ جابان(1)\nمیمون کے والد، ابن مندہ نے ابو سعید مولا بنی ہاشم کی سند سے بحوالہ ابو خالد روایت کیا ہے۔ فرماتے ہیں: میں نے میمون بن جابان سے بحوالہ ان کے والد سنا، انہوں نے کئی بار جس کی تعداد دس بن جاتی ہے نبی صلی اللہ علیہ وسلم کو فرماتے سنا: \"جو کسی عورت سے اس نیت سے شادی کرے کہ اسے مہر نہیں دے گا اس کی اللہ تعالیٰ سے اس حال میں ملاقات ہو گی کہ وہ زانی شمار ہو گا۔\"(2) میں کہتا ہوں: اگر یہ محفوظ ہے تو انہوں نے اپنے والد کے حوالے سے ایسا ہی کہا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۳۰) تجرید (۷۱/۱)\n(2) المعجم الکبیر (۴۱/۸) المعجم الصغیر (۴۲/۱) مجمع الزوائد (۶۶۵۲) تہذیب تاریخ دمشق (۴۰۰/۶) کنز العمال (۴۴۷۲۵) اتحاف السادۃ المتقین (۱۰/۱۰) الترغیب والترھیب (۵۹۹/۲)"}],[1009,"§۱۰۰۹ ۔ جابر بن الازرق الغاضری(1)\nان کی حدیث اہل حمص سے ملتی ہے۔ ابن مندہ نے فرمایا: وہ حمص میں فروکش ہوئے۔ اور نضر بن علقمہ کی سند سے بحوالہ اپنے بھائی محفوظ، عبد الرحمن بن عائذ سے وہ ابو راشد حیرانی سے فرمایا: مجھے جابر بن ازرق غاضری نے بتایا: میں ایک سواری پر اپنے ساتھ کچھ سامان لے کر نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، تو مجھے ایک شخص نے ہٹا دیا۔ میں نے کہا: یمن کے دور دراز علاقہ سے نبی صلی اللہ علیہ وسلم کی بات سننے آیا ہوں تاکہ اسے محفوظ (یاد) کر کے پیچھے رہ جانے والے لوگوں کو سناؤں (میرا تو یہ مقصد ہے) اور تم مجھے (اندر جانے سے) روک رہے ہو۔ اس شخص نے کہا: تم نے سچ کہا۔ پھر رسول اللہ صلی اللہ علیہ وسلم سوار ہوئے۔ اس کے بعد وہ حدیث ذکر کی۔ اسی میں آپ صلی اللہ علیہ وسلم کی سرمنڈانے والوں کے لیے تین بار(2) کی دعا ہے۔ (ابن مندہ) فرماتے ہیں: انوکھی روایت ہے جو صرف اسی سند سے پہچانی جاتی ہے۔","",{"fn":"(1) اسد الغابۃ (۶۳۱) تجرید (۷۱/۱)\n(2) بخاری کتاب الحج باب الحلق والتقصیر (۱۷۲۶) مسلم کتاب الحج باب تفضیل الحلق علی التقصیر و جواز التقصیر (۳۱۳۲) ابوداؤد کتاب المناسک باب الحلقۃ والتقصیر (۱۹۷۹) ترمذی کتاب الحج باب ما جاء فی الحلقۃ والتقصیر (۹۱۳) ابن ماجہ کتاب المناسک باب الحلق (۳۰۴۴) کنز العمال (۱۲۷۴۲)"}],[1010,"§۱۰۱۰ ۔ جابر بن اسامہ الجہنی(1)\nکنیت ابو سعاد تھی۔ مصر فروکش ہوئے اور وہیں وفات پائی۔ یہ بات ابو یونس نے ایک حدیث ذکر کر کے اس میں کہی جو ابن وہب سے بحوالہ اسامہ بن زید مروی ہے۔ امام بخاری رحمہ اللہ نے اپنی تاریخ میں، ابن ابی عاصم اور طبرانی وغیرہ اسامہ بن زید کی سند سے بحوالہ معاذ بن عبد اللہ بن حبیب، جابر بن اسامہ جہنی سے روایت کرتے ہیں، فرماتے ہیں: میں نے بازار میں نبی صلی اللہ علیہ وسلم سے ملاقات کی آپ صلی اللہ علیہ وسلم کے ساتھ آپ کے صحابہ تھے۔ میں نے ان لوگوں سے پوچھا آپ صلی اللہ علیہ وسلم کا کہاں کا ارادہ ہے؟ انہوں نے بتایا: تمہاری قوم کی مسجد بنانے کا۔ میں اپنی قوم کے پاس واپس آیا تو وہ لوگ آپ سے کہنے لگے: ہمارے لیے مسجد کا نقشہ بنا دیں اور قبلہ کی جانب ایک لکڑی گاڑ دیں۔(2) ابن السکن نے کہا: ان سے اس سند کے سوا کچھ مروی نہیں۔ اسی مفہوم سے ملتی جلتی بات بغوی نے لکھی ہے۔","",{"fn":"(1) اسد الغابۃ (۶۳۲) الاستيعاب (۳۰۲) تجرید (۷۱/۱)\n(2) المعجم الکبیر (۱۹۳/۲، ۱۹۴) المعجم الصغیر (۵۸/۱) التاریخ الکبیر (۲۰۲/۱)"}],[1011,"§۱۰۱۱ ۔ جابر بن حابس(1)\nعابس العبدی۔ طبرانی(2) نے حصین بن نمیر کی سند سے فرمایا: مجھے میرے والد نے اپنے والد کے حوالے سے بتایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جس نے جان بوجھ کر میرے متعلق جھوٹ کہا وہ اپنا ٹھکانہ جہنم میں بنا لے۔\" اس کی سند مجہول ہے اور یوسف بن خلیل کی روایت میں ان کے قلم سے عابس ہے ایسا ہی ابن الجوز کے ہاں مرقوم ہے۔","",{"fn":"(1) اسد الغابۃ (۶۳۳) الاستيعاب (۲۹۹) تجرید (۷۱/۱)\n(2) المعجم الکبیر (۱۳۵/۱) (۳۲/۷)"}],[1012,"§۱۰۱۲ ۔ (ز) جابر بن حارث العبدی\nاس وفد کے ایک آدمی جو ان کے ہمراہ آ کر مسلمان ہوئے ان کا تذکرہ صحار العبدی کے سوانح میں ان شاء اللہ آئے گا۔"],[1013,"§۱۰۱۳ ۔ جابر بن خالد(1)\nبن مسعود بن عبد الاشہل بن حارثہ بن دینار بن نجار خزرجی۔ موسیٰ بن عقبہ نے بحوالہ ابن شہاب، اور ابو الاسود نے بحوالہ عروہ اور محمد بن اسحاق نے بدر کے شرکاء میں ان کا تذکرہ کیا ہے۔ ابن اسحاق کے ہاں جابر بن عبد اللہ لکھا ہے جبکہ درست پہلا نام ہے۔","",{"fn":"(1) اسد الغابۃ (۶۳۵) الاستيعاب (۳۰۱) تجرید (۷۱/۱)"}],[1014,"§۱۰۱۴ ۔ جابر بن رِناب\nابن عبد اللہ بن رکاب میں تذکرہ آئے گا۔"],[1015,"§۱۰۱۵ ۔ جابر بن ابی سبرہ الاسدی(1)\nحاکم اور بیہقی نے \"شعب\"(2) میں اور ابن مندہ نے ابن عجلان کی سند سے بحوالہ موسیٰ بن سائب، سالم بن ابی الجعد سے انہوں نے جابر بن ابی سبرہ سے روایت نقل کی ہے۔ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ نے جہاد کا تذکرہ کرتے ہوئے فرمایا: \"شیطان انسان کے راستوں میں بیٹھا ہوتا ہے۔\" (حدیث) ابن مندہ فرماتے ہیں، انوکھی روایت ہے جس میں طارق منفرد ہے اس میں محفوظ سالم بن ابی الجعد، بحوالہ سبرہ بن ابی فاکہہ ہے، جیسا کہ اپنے مقام پر آئے گا۔","",{"fn":"(1) اسد الغابۃ (۶۳۴) الاستيعاب (۲۸۸)\n(2) شعب الایمان (۴۲۶۴)"}],[1016,"§۱۰۱۶ ۔ جابر بن سفیان(1)\nاز بنی زریق خزرجی، معمر بن حبیب نجمی کے حلیف۔ ان دونوں کے والد نے معمر سے معاہدہ کیا اور مکہ میں مقیم ہو گئے۔ اسلام لانے کے بعد حبشہ ہجرت کی پھر وہ اور ان کے دونوں بیٹے جابر اور جنادہ حبشہ سے دو کشتیوں میں آئے۔ یہ ابن اسحاق کا قول ہے۔ ابن کلبی(2) اور ابن اسحاق ہی کا کہنا ہے کہ تینوں خلافت فاروقی میں فوت ہوئے۔ ابن اسحاق کہتے ہیں کہ شعبیل بن حسنہ، جابر اور جنادہ کے باپ شریک ایک بھائی تھے۔ پھر شعبیل کا سعید بن المعلی کے ساتھ پیش آمدہ وہ قصہ ذکر کیا جب وہ انصار سے علیحدہ ہو کر بنی زہرہ کے حلیف بن گئے۔","",{"fn":"(1) اسد الغابۃ (۶۳۶) الاستيعاب (۲۹۲)\n(2) السیرۃ النبویۃ (۲۵۹/۱) (۲۶۹/۱)"}],[1017,"§۱۰۱۷ ۔ جابر بن سلیم\nبقول بعض سلیم بن جابر یا جابر بن سلیمی۔ کنیت زیادہ مشہور ہے۔ اس لیے کنیتوں میں آئے گا۔"],[1018,"§۱۰۱۸ ۔ جابر بن سمرہ(1)\nبن جنادہ بن جندب بن حجیر بن رکاب بن حبیب بن سوادہ بن عامر بن صحصعہ عامری سوائی۔ بنی زہرہ کے حلیف، ان کی والدہ خالدہ بنت ابی وقاص، سعد بن ابی وقاص کی بہن ہیں۔ انہیں (جابر) اور ان کے والد کو شرف صحابیت حاصل ہے۔ صحیح کے مصنفین نے ان کی احادیث نقل کی ہیں۔ شریک نے سماک سے بحوالہ جابر بن سمرہ رضی اللہ عنہ روایت کی ہے، فرمایا: میں کوئی سو سے زائد بار نبی صلی اللہ علیہ وسلم کی مجلس میں بیٹھا ہوں، اسے طبرانی(2) نے نقل کیا ہے۔ صحیح روایت میں ان سے مروی ہے، فرمایا: میں نے نبی صلی اللہ علیہ وسلم کی اقتداء میں دو ہزار سے زیادہ بار نماز پڑھی ہے۔ بقول ابن السکن: ان کی کنیت ابو عبد اللہ، بقول بعض ابو خالد ہے۔ کوفہ فروکش ہوئے تو وہیں ایک حویلی بنائی۔ عراق میں بشر کی گورنری کے دوران فوت ہوئے۔ جو ۴۷ھ کا سن ہے۔ مسلم بن جنادہ بحوالہ اپنے والد روایت کرتے ہیں کہ عمرو بن حریث نے ان کا جنازہ پڑھایا۔","",{"fn":"(1) اسد الغابۃ (۶۳۸) الاستيعاب (۳۰۲)\n(2) المعجم الکبیر (۱۹۴/۲) (۲۲۶/۲)"}],[1019,"§۱۰۱۹ ۔ جابر بن شیبان(1)\nبن عجلان بن عتاب بن مالک انصاری۔ مدائنی نے \"اخبار ثقیف\" نامی کتاب میں ذکر کیا کہ وہ بیعت رضوان میں شریک تھے۔ ابن دباغ نے ان کا استدراک کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۳۹)"}],[1020,"§۱۰۲۰ ۔ جابر بن صخر(1)\nبن امیہ انصاری۔ جبار کے بھائی بقول ابن القدام عقبہ میں شریک تھے۔ اور بدر کے علاوہ باقی غزوات میں شرکت کی ہے۔ ایسا ہی ابن اسحاق نے کہا ہے ابن سعد لکھتے ہیں: واقدی ان سے واقف نہیں اور نہ موسیٰ بن عقبہ کو ان کی خبر ہے مند مسدد میں ابن اسحاق کی سند سے بحوالہ ابو سعد جابر بن عبد اللہ سے مروی لکھا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں اور جابر بن صخر کو اپنی اقتداء میں کھڑا کر کے نماز پڑھائی۔(2) ان کے علاوہ نے روایت کی تو جابر بن صخر کہا، یہی محفوظ ہے جیسا کہ ان شاء اللہ تعالیٰ آ رہا ہے۔","",{"fn":"(1) مسند احمد (۶۴۱)\n(2) مسند احمد (۴۲۱/۳) المعجم الکبیر (۲۱۳۷/۲) مجمع الزوائد (۹۵/۲)"}],[1021,"§۱۰۲۱ ۔ جابر بن ابی صعصعہ\nابن عمرو میں تذکرہ آئے گا۔"],[1022,"§۱۰۲۲ ۔ جابر بن طارق(1)\nبن ابی طارق بن عوف الا حمی انجلی۔ اپنے دادا کی طرف نسبت کیے جانے سے جابر بن عوف اور جابر بن ابی طارق کہلاتے ہیں۔ امام بخاری فرماتے ہیں: شرف صحابیت سے مشرف ہیں ان کی حدیث نسائی کے ہاں صحیح سند سے مروی ہے۔ بغوی کا قول ہے مجھے ان کی اور حدیث معلوم نہیں۔ ادھر ابن السکن اسماعیل بن ابی خالد کی سند سے بحوالہ حکیم بن جابر سے (جو اہل قادسیہ سے تھے) وہ اپنے والد سے، پھر حدیث ذکر کی۔ یہی روایت شیرازی کی کتاب \"الالقاب\" میں اس قول کے بغیر ہے \"وہ اہل قادسیہ سے تھے\" کہ ایک دہیاتی نے نبی صلی اللہ علیہ وسلم کی نعت کہی یہاں تک کہ بولتے بولتے اس کے منہ کے کناروں سے جھاگ نمایاں ہونے لگی۔ آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: \"تم لوگ کم بولا کرو، اس لیے کہ گفتگو کی فصاحت و بلاغت شیطان کا حصہ ہے۔\" ابن حبان(2) نے جابر بن طارق انجسی(3) اور جابر بن عوف انجسی میں فرق کر کے پہلی شخصیت کے متعلق کہا: وہ کوفہ میں رہے سرخ خضاب لگاتے تھے اور دوسری کے متعلق کہا: انہیں شرف صحابیت حاصل ہے، حکیم کے والد ہیں۔ ایسا ہی ابو عمر (کی کتاب) پر ابن فتوحون نے استدراک میں کہا ہے۔ چنانچہ جہاں انہوں نے جابر بن عوف درج کیا ابن فتوحون نے جابر بن طارق لکھا ہے۔ یہ سارے وہم ہیں، شخصیت ایک ہی ہے۔","",{"fn":"(1) اسد الغابۃ (۶۴۲) تجرید اسماء الصحابۃ (۷۲/۱)\n(2) تفسیر ابن کثیر (۴۳۰/۲)\n(3) الثقات (۵۳/۳)"}],[1023,"§۱۰۲۳ ۔ جابر بن ظالم(1)\nبن حارثہ بن عتاب بن ابی حارثہ بن جدی بن تدول بن نکر البحتری الطائی۔ بقول طبری نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو کر اسلام لائے۔ آپ نے انہیں ایک تحریر دی جوان لوگوں کے پاس(2) ہے ابن فتوحون اور شمالطی نے ان کا استدراک کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۴۴) الاستيعاب (۲۹۸)\n(2) اسد الغابۃ (۲۹۲/۱)"}],[1024,"§۱۰۲۴ ۔ جابر بن عباس\nیہی ابن حابس ہیں، تذکرہ گزر چکا ہے۔ ان کا نسب تجرید کی تلخیص میں ہے وہاں تنبیہ نہیں ہے کہ یہ شخصیت پہلے مذکور ہو گئی ہے۔"],[1025,"§۱۰۲۵ ۔ جابر بن عبداللہ(1)\nبن رئاب بن نعمان بن سنان بن عبید بن عدی بن غنم ابن کعب بن سلمہ انصاری سلمی ان چھ میں کے ایک جو عقبہ اولیٰ میں حاضر تھے۔ ابن اسحاق فرماتے ہیں: مجھے عاصم بن عمر بن قتادہ نے اپنی قوم کے شیوخ کے حوالہ سے بتایا، فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم انصار کے چھ آدمیوں: اسعد بن زرارہ، جابر بن عبداللہ بن رئاب، قطبہ بن عامر، رافع بن مالک، عقبہ بن عامر بن زید، عوف بن مالک سے ملے تو یہ لوگ اسلام لے آئے۔ اور پھر وہ حدیث ذکر کی۔(2) موسیٰ بن عقبہ نے ابن شہاب سے اور ابوالاسود نے عروہ سے شرکائے بدر میں ان کا تذکرہ کیا ہے ابن عبدالبر ان کے سوانح میں لکھتے ہیں: ابن کلبی کے ہاں بحوالہ ابوصالح ان سے مروی ایک حدیث ہے مجھے اس کے علاوہ ان کی روایت معلوم نہیں۔\n\nمیں کہتا ہوں: جابر بن عبداللہ بن رئاب سے مروی ضعیف طرق سے کئی اور احادیث بھی ہیں جن میں سے بغوی، ابن السکن وغیرہ نے وازع بن نافع کی سند سے بحوالہ ابوسلمہ جابر بن عبداللہ بن رئاب سے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا کہ \"میکائیل علیہ السلام فرشتوں کی ایک جماعت سمیت میرے پاس سے گزرے\"۔ (حدیث)(3) بغوی فرماتے ہیں: وازع ضعیف ترین راوی ہے۔ فرماتے ہیں: مجھے جابر کی اس کے علاوہ کوئی مسند روایت معلوم نہیں۔\n\nمیں کہتا ہوں: کیوں نہیں ان کی ایک روایت اور بھی ہے جسے بخاری نے تاریخ میں ابن اسحاق کی سند سے بحوالہ کلبی، ابوصالح سے وہ جابر بن عبداللہ بن رئاب سے ابو یاسر بن اخطب کے قصہ میں نقل کرتے ہیں۔ جسے یونس بن بکیر نے مغازی میں ذکر کیا ہے۔ جس کی سند یوں ہے ابن اسحاق، محمد بن ابی محمد سے وہ عکرمہ یا سعید بن جبیر سے بحوالہ ابن عباس رضی اللہ عنہما اور جابر بن رئاب رضی اللہ عنہما روایت کرتے ہیں کہ ابو یاسر بن اخطب نبی صلی اللہ علیہ وسلم کے ہاں سے گزرے، آپ صلی اللہ علیہ وسلم سورۃ فاتحہ اور ((الم۔ ذٰلِکَ الْکِتٰبُ لَا رَیْبَ فِیْہِ)) (سورۃ البقرہ: ۱، ۲) کی تلاوت فرما رہے تھے۔ پھر وہ قصہ ذکر کیا۔ لگتا ہے جابر کی نسبت ان کے دادا کی طرف ہوئی۔\n\nاسی طرح ابن شاہین اور ابن مردویہ ہمام کی سند سے بحوالہ کلبی اللہ تعالیٰ کے ارشاد: \"اللہ تعالیٰ جو چاہتا ہے مٹا دیتا ہے اور جو چاہتا ہے برقرار رکھتا ہے\"۔ (سورۃ الرعد: ۳۹) کے متعلق نقل کرتے ہیں، فرمایا: رزق کا کچھ حصہ ختم کر دیتا ہے۔ میں نے کہا: آپ سے یہ بات کس نے بیان کی؟ فرمایا: ابوصالح نے بحوالہ جابر بن رئاب رسول اللہ صلی اللہ علیہ وسلم سے۔","",{"fn":"(1) اسد الغابہ (۶۴۶) الاستيعاب (۲۸۹) تجريد (۷۲/۱)\n(2) المعجم الكبير (۱۷۶۷/۲) السنن الكبرى (۱۳۱/۳) دلائل النبوة حديث (۱۳۱/۳) كنز العمال (۲۲۶۳۴)\n(3) التاريخ الكبير (۲۰۸/۱)"}],[1026,"§۱۰۲۶ ۔ جابر بن عبداللہ(1)\nبن عمرو بن حرام بن کعب بن غنم بن کعب بن سلمہ انصاری سلمی۔ ابوعبداللہ، ابوعبدالرحمن اور ابومحمد کنیت رکھنے کے کئی اقوال ہیں۔ نبی صلی اللہ علیہ وسلم کے ارشادات بکثرت روایت کرنے والوں میں سے ایک ہیں ان سے صحابہ کی ایک جماعت روایت کرتی ہے اور ان کے والد دونوں صحابی ہیں۔(2) صحیح میں ان سے مروی ہے کہ وہ عقبہ میں شریک تھے۔ امام بخاری رحمہ اللہ(3) نے اپنی تاریخ میں ابوسفیان سے بحوالہ جابر رضی اللہ عنہ صحیح سند سے نقل کیا ہے، فرمایا: \"جنگ بدر کے روز میں اپنے ساتھیوں کے لیے چلو بھر بھر کر پانی لاتا تھا\"۔ اور حجاج بن مؤاف کی سند سے مروی ہے، فرمایا: \"مجھے ابوزبیر نے بحوالہ جابر بتایا، آپ نے ان سے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے بنفس نفیس اکیس(۲۱) غزوات کیے جن میں سے میں انیس(۱۹) غزوات میں شریک ہوا\"۔ واقدی نے ابوسفیان کی جابر سے بیان کردہ روایت کا انکار کیا ہے۔ امام مسلم(4) زکریا بن اسحاق کی سند سے بحوالہ ابوزبیر روایت کی ہے انہوں نے سیدنا جابر رضی اللہ عنہ کو فرماتے سنا: میں نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں انیس(۱۹) غزوات کیے۔ سیدنا جابر خود فرماتے ہیں کہ میں بدر و احد میں شریک نہ ہو سکا مجھے میرے والد نے کم سنی کی وجہ سے منع کر دیا تھا۔ جب وہ شہید ہو گئے تو پھر میں پیچھے نہ رہا۔ سیدنا جابر رضی اللہ عنہ سے مروی ہے، اونٹ (کی خریداری) کی رات رسول اللہ صلی اللہ علیہ وسلم نے میرے لیے پچیس بار استغفار فرمایا۔ اسے امام احمد وغیرہ(5) نے حماد بن سلمہ کی سند سے ابوزبیر سے بحوالہ جابر رضی اللہ عنہ نقل کیا ہے۔\n\nمصنف وکیع میں ہشام بن عروہ سے مروی ہے، فرمایا: جابر بن عبداللہ رضی اللہ عنہ کا مسجد نبوی میں ایک حلقہ لگتا تھا جہاں سے لوگ علم حاصل کرتے تھے۔ بغوی نے عاصم بن عمرو بن قتادہ کی سند سے نقل کیا، فرمایا: ہمارے پاس جابر بن عبداللہ رضی اللہ عنہ اس وقت تشریف لائے جب ان کی بینائی ختم ہو چکی تھی انہوں نے اپنے سر اور اپنی داڑھی پر زرد خضاب کر رکھا تھا۔(6)\n\nابو ہلال کی سند سے بحوالہ قتادہ مروی ہے، فرمایا: مدینہ میں صحابہ میں سے سیدنا جابر نے سب سے آخر میں وفات پائی۔ بغوی فرماتے ہیں: یہ وہم ہے، وہاں سہل بن سعد آخری صحابی فوت ہوئے۔ یحییٰ بن بکیر وغیرہ کا قول ہے: سیدنا جابر رضی اللہ عنہ کا انتقال ۷۸ھ میں ہوا۔ علی بن مدائنی نے فرمایا: سیدنا جابر ابن عمر رضی اللہ عنہما کے بعد فوت ہوئے۔ آپ نے یہ وصیت بھی فرمائی تھی کہ حجاج(7) میرا جنازہ نہ پڑھانے پائے۔\n\nمیں کہتا ہوں: یہ ہیثم بن عدی کے قول کے موافق ہے کہ وہ ۷۴ھ میں فوت ہوئے۔ طبری اور تاریخ بخاری(8) میں اس کا شاہد موجود ہے کہ حجاج ان کے جنازے میں شریک تھا۔ بعض کا کہنا ہے کہ وہ ۷۳ھ میں فوت ہوئے اور بقول بعض وہ چورانوے(۹۴) سال زندہ رہے۔","",{"fn":"(1) اسد الغابۃ (۶۴۷) الاستيعاب (۲۹۰)\n(2) المعجم الكبير (۱۸۰۔۱۸۲/۲) مجمع الزوائد (۱۶۴/۵)\n(3) التاريخ الكبير حديث (۲۰۷/۱)\n(4) مسلم باب عدد غزوات النبی صلی اللہ علیہ وسلم حديث (۴۶۷۱)\n(5) ترمذی كتاب المناقب باب فی مناقب جابر بن عبد الله رضى الله عنهما (۳۸۵۲) نسائی فی المناقب السنن الكبرى على تحفة الأشراف (۲۹۴/۲) جامع المسانيد والسنن (۱۱۳/۲۵)\n(6) المعجم الكبير (۱۸۲/۲) مجمع الزوائد (۱۶۴/۵)\n(7) المعجم الكبير (۱۸۰/۲، ۱۸۱) مجمع الزوائد (۴۳۱/۹)\n(8) التاريخ الكبير (۲۰۷/۲)"}],[1027,"§۱۰۲۷ ۔ (ز) جابر بن عبداللہ(1)\nانہیں ابن عبید بن جابر العبدی بھی کہا جاتا ہے۔ امام مالک رحمہ اللہ نے کتاب الاشربہ میں اور ان سے بغوی نے حارث بن مرہ کی سند سے بحوالہ نفیس، عبداللہ بن جابر عبدی سے روایت کی ہے، فرمایا: \"عبدالقیس کا جو وفد نبی صلی اللہ علیہ وسلم کے پاس آیا میں بھی اس میں تھا، اگرچہ میرا تعلق اس قبیلہ سے نہیں، میں تو اپنے والد کے ساتھ تھا رسول اللہ صلی اللہ علیہ وسلم نے انہیں (مخصوص) برتنوں میں پینے سے منع فرمایا تھا\"۔ (حدیث)(2)\n\nاسی میں ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم کے بعد اپنے والد کے ہمراہ حج کیا، تو سیدنا حسن بن علی رضی اللہ عنہ کے پاس آئے۔ انہیں سلام کیا، آپ رضی اللہ عنہ نے انہیں خوش آمدید کہا۔ اتنے میں سیدنا حسن رضی اللہ عنہ سے کسی نے گھڑے میں نبیذ بنانے کے متعلق پوچھا تو آپ نے اسے رخصت دی۔ تو میرے والد نے ان سے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم کے منع کرنے کے بعد بھی رخصت ہے؟ انہوں نے فرمایا: ہاں! تم لوگوں کے بعد آپ علیہ السلام نے اس کی رخصت دے دی۔ اس کی سند حسن ہے (لیکن) مجھے یہ روایت مسند احمد میں نہیں ملی۔ البتہ ابو نعیم نے اسے قطیعی سے بحوالہ عبداللہ بن احمد بن حنبل بحوالہ ان کے والد روایت کیا ہے۔ ابن الاثیر نے انوکھا کام کیا کہ اسے مسند کی سند سے بیان کیا۔ لگتا ہے انہوں نے جب ابو نعیم کی اسناد دیکھی تو اسے مقدم کیا۔ جبکہ وہ کتاب الاشربہ امام احمد کی روایت ہے۔ ادھر باوردی نے نضر بن شمیل کی سند سے بحوالہ حبیب بن ابی جویرہ طفاوی نقل کیا، فرماتے ہیں: مجھے قیس نے بتایا کہ میں حج کے ارادے سے رخت سفر باندھ کر نکلا تو قبیلہ عبدالقیس کے ایک شخص سے ملاقات ہوگئی جس کا نام عبداللہ بن جابر تھا۔ وہ شخص کہنے لگے: میں نے اپنے والد کے ہمراہ حج کیا تھا پھر ہم لوگ مدینہ کے رخ چل پڑے۔ فرمانے لگے: ام المومنین کے ہاں نہ اتریں؟ میں نے کہا: کیوں نہیں۔ ہم ان کے ہاں روانہ ہو گئے۔ میرے والد نے ان سے عرض کیا میں سن رہا تھا: میں اس وفد کے ساتھ تھا جو بحرین سے آیا تھا، کیا آپ نے نبی صلی اللہ علیہ وسلم سے سنا ہے کہ آپ نے ہمارے بعد مشروبات کے بارے میں کوئی نیا حکم صادر فرمایا ہو؟\n\nانہوں نے کہا: نہیں۔","",{"fn":"(1) اسد الغابۃ (۶۴۸) الاستيعاب (۳۰۰) تجريد (۷۳/۱)\n(2) بخاری كتاب الاشربة باب ترخيص النبی صلی اللہ علیہ وسلم فی الاوعية (۵۵۹۴) مسلم كتاب الاشربة باب النهى عن الانتباذ فى المزفت (۵۱۷۲) نسائی كتاب الاشربة باب النهى عن نبيذ (۵۶۴۸) ابن ماجہ كتاب الاشربة باب النهى عن نبيذ الأوعية (۳۴۰۳) مسند احمد (۹۰/۳)"}],[1028,"§۱۰۲۸ ۔ جابر بن عبداللہ راسبی(1)\nصالح جزرہ کا قول ہے بصرہ فروکش ہوئے اور ابو عمر نے کہا: ان سے ابو شداد روایت کرتے ہیں۔ ابن مندہ نے عمر بن برقان کی سند سے بحوالہ ابو شداد، جابر بن عبداللہ راسبی سے نبی صلی اللہ علیہ وسلم کا یہ ارشاد نقل کیا ہے: \"جس نے اپنے (رشتہ دار) کے قاتل سے درگزر کیا وہ جنت میں جائے گا\"۔(2) فرماتے ہیں: یہ انوکھی روایت ہے، اگر محفوظ ہو۔ ابونعیم فرماتے ہیں: انہیں راسبی کہنا وہم ہے وہ تو انصاری ہیں۔","",{"fn":"(1) اسد الغابۃ (۶۴۵) الاستيعاب (۲۹۱) تجريد (۷۲/۱)\n(2) كنز العمال (۳۹۸۵۵)"}],[1029,"§۱۰۲۹ ۔ (ز) جابر بن عبداللہ از انصار\nابوالفتح عمری نے سیرۃ نبویہ میں ان کا ان لوگوں میں ذکر کیا ہے جنہیں نبی صلی اللہ علیہ وسلم نے احد کے روز (کم عمری کے باعث) واپس کر دیا تھا۔ فرماتے ہیں: یہ وہ نہیں جن سے حدیث مروی ہے۔\n\nمیں کہتا ہوں: انصار کے علاوہ کوئی ایسے صحابی نہیں دیکھے گئے جنہیں جابر بن عبداللہ کہا جاتا ہو سوائے عبدی کے۔ اگر یہ بات صحیح ہے تو یہ شخصیت راسبی ہے۔ لیکن ان میں سے کسی کے متعلق یہ بیان نہیں کیا گیا کہ انہیں اُحد سے واپس بھیج دیا گیا ہو، ہوسکتا ہے یہ تیسری شخصیت ہو۔ پھر مجھے ابن فتحون کے \"ذیل\" میں ان کا ذکر مل گیا۔ فرماتے ہیں: ابن سعد نے کہا: ہمیں ابن سماعہ نے بحوالہ قاضی ابو یوسف، عثمان بن عبداللہ بن یزید بن حارثہ سے وہ اپنے چچا ابن یزید بن حارثہ سے وہ اپنے والد کے واسطے سے بتاتے ہیں، فرمایا کہ اُحد کے روز رسول اللہ صلی اللہ علیہ وسلم نے ابن عمر زید بن ارقم ابو سعید اور جابر بن عبداللہ کو کم سن قرار دیا یہ وہ جابر نہیں جن سے حدیث مروی ہے۔ ان میں سعد بن حبتہ بھی شامل ہیں، اسے طبری نے بحوالہ ابن سعد نقل کیا ہے۔"],[1030,"§۱۰۳۰ ۔ جابر بن عتیک(1)\nبن قیس بن حارث بن ہیثہ بن حارث بن امیہ بن زید بن معاویہ بن مالک بن عمرو بن عوف بن مالک بن الاوس انصاری۔ ابن کلبی اور ابن اسحاق نے ان کا یہی نسب بیان کیا ہے اور فرماتے ہیں: وہ بدر اور باقی غزوات میں شریک رہے۔ امام مالک(2) نے موطا میں عبداللہ بن عبداللہ بن جابر بن عتیک سے بحوالہ عتیک بن حارث بن عتیک (وہ عبداللہ کے نانا ہیں) روایت کی ہے کہ جابر بن عتیک نے انہیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم عبداللہ بن ثابت رضی اللہ عنہ کی عیادت کرنے آئے تو انہیں بے ہوش پایا، آپ نے انہیں آواز دی تو وہ کوئی جواب نہ دے سکے۔ آپ نے انا للہ وانا الیہ راجعون پڑھا، فرمایا: ابوربیع ہم تمہارے بارے میں قضاء الہی سے ہار گئے۔ (حدیث) اسے ابو داؤد اور نسائی نے امام مالک رحمہ اللہ کی سند سے روایت کیا اور نسائی نے عبدالملک بن عمیر کی سند سے روایت کیا تو فرمایا: جبر بن عتیک سے روایت ہے کہ وہ نبی صلی اللہ علیہ وسلم کے ساتھ ایک میت کے پاس گئے تو عورتیں رو پڑیں۔(3) (حدیث) اور ابن ماجہ وغیرہ نے ابواسامہ اور دیگر لوگوں کی سند سے بحوالہ ابو العميس، عبداللہ بن عبداللہ بن جبر سے وہ اپنے والد سے وہ اپنے دادا سے وہ اسی مفہوم کی روایت کرتے ہیں۔ اور نسائی نے جعفر بن عون کی سند سے بحوالہ ابو العميس سے ہے اس میں عبداللہ بن عبداللہ بن جابر بن عتیک وہ اپنے والد سے وہ اپنے دادا سے مروی ہے بہر کیف اس میں کافی اختلاف ہے ان سب میں امام مالک کی روایت معتبر ہے جس کی ترجیح ابوداؤد اور نسائی کی اس روایت سے ہوتی ہے جو محمد بن ابراہیم تیمی کی سند سے بحوالہ ابن جابر بن عتیک ان کے والد سے مرفوع منقول ہے: \"غیرت کی بعض چیزیں اللہ تعالیٰ کی ناراضگی کا باعث ہیں\"۔ (حدیث)(4) اس کی سند صحیح ہے۔ تاریخ بخاری میں نافع بن یزید کی سند سے بحوالہ ابوسفیان بن جابر بن عتیک ان کے والد سے مروی ہے انہوں نے نبی صلی اللہ علیہ وسلم کو فرماتے سنا: \"جس نے کسی مسلمان شخص کا مال اپنی (جھوٹی) قسم کے ذریعہ دبا لیا اللہ تعالیٰ اس کے لئے جنت حرام کر دے گا\"۔(5)\n\nان تمام احادیث سے یہ بات ظاہر ہوئی ہے کہ ان کا نام جابر ہے لیکن وہ آخری حدیث جو آئندہ عنوان میں آ رہی ہے اس کا احتمال رکھتی ہے۔ اس لئے کہ ان کے دادا کا نام نہیں لیا گیا۔ دمیاطی نے اس بات کو صحیح قرار دیا ہے کہ ان کا نام جبر تھا۔ جبکہ دوسرے علماء بغوی وغیرہ نے اس کا یقین کیا ہے کہ جبر ان کے بھائی کا نام ہے۔ ابن اسحاق وغیرہ نے اس روایت پر اعتماد کیا ہے کہ جبر بن عتیک بدر میں شریک ہوئے۔ اور صحابہ میں جابر بن عتیک نامی ان کے علاوہ دو شخصیتیں ہیں۔ ان میں سے ایک","",{"fn":"(1) اسد الغابۃ (۶۴۹) الاستيعاب (۲۹۴)\n(2) مؤطا مالك كتاب الجنائز باب النهى عن البكاء على الميت (۵۵۲)\n(3) ابوداؤد كتاب الجنائز باب فى فضل من مات بالطاعون (۳۱۱) نسائی كتاب الجنائز باب النهى عن البكاء على الميت (۱۸۴۵) ايضا كتاب الجهاد باب من خان غازيا فى اهله (۳۱۹۴) ابن ماجہ كتاب الجهاد باب ما يرجى فيه الشهادة (۲۸۰۳)\n(4) ابوداؤد كتاب الجهاد باب فى الخيلاء فى الحرب (۲۶۵۹) نسائی كتاب الزكاة باب الاختيال فى الصدقة (۲۵۵۷)\n(5) مسلم كتاب الايمان باب وعيد من اقتطع حق مسلم بيمين فاجرة بالنار (۳۵۱) نسائی كتاب آدات القضاء باب القضاء فى قليل المال و كثيره (۵۴۳۴) ابن ماجہ كتاب الاحكام باب من حلف على يمين فاجرة ليقتطع بها مالا (۲۳۲۴) مؤطا مالك كتاب الاقضية باب ما جاء في الحنث على منبر النبی صلی اللہ علیہ وسلم (۱۳۳۵) المعجم الكبير (۲۴۹/۱) (۲۱۰/۲) السنن الكبرى (۱۷۹/۱۰)"}],[1031,"§۱۰۳۱ ۔ جابر بن عتیک\nبن نعمان بن عتیک انصاری ہیں۔ ابن حبان نے ان کا صحابہ میں تذکرہ کر کے لکھا ہے، ان کی کنیت ابوعبداللہ ہے اور شرف صحابیت سے مشرف ہیں۔ ان سے ان کا بیٹا ابوسفیان روایت کرتا ہے۔\n\nمیں کہتا ہوں: ابوسفیان بن جابر کی روایت کردہ حدیث جو ان کے والد کے حوالہ سے مروی ہے تاریخ بخاری میں ہے۔ انہوں نے نبی علیہ السلام کو فرماتے سنا: \"جس نے کسی مسلمان کا مال اپنی (جھوٹی) قسم سے دبا لیا اللہ تعالیٰ اس کے لئے جنت حرام کر دے گا\"۔(1) فرماتے ہیں: ابوسفیان مصر آئے کسی کو ان کا نام معلوم نہیں (کنیت سے ہی مشہور ہیں)۔ دوسری شخصیت","",{"fn":"(1) حوالہ گزر چکا۔"}],[1032,"§۱۰۳۲ ۔ جابر بن عتیک\nبن قیس بن اسود بن مری بن کعب بن غنم بن سلمہ انصاری سلمی ہے۔ پہلی شخصیت(۱۰۳۰) کی ہمنام حتی کہ ان کے والد اور دادا کا نام بھی ایک جیسا ہے برخلاف ثانی کے، لیکن اس میں اختلاف ہے کہ آیا وہ احد میں شریک ہوئے یا نہیں۔ چنانچہ ابن سعد نے علماء سیر کی ایک جماعت سے نقل کیا ہے کہ وہ احد کے بعد والی مہمات میں شریک تھے۔ وہ عبدالملک بن جابر بن عتیک کے والد ہیں جو جابر بن عبداللہ سے یہ روایت کرتے ہیں: جب کوئی شخص کسی قوم سے کوئی بات کر کے چلا جائے تو وہ بات امانت ہوگی۔(1) یہ دمیاطی کا قول ہے۔","",{"fn":"(1) ابوداؤد كتاب الادب باب فى نقل الحديث (۴۸۶۸) ترمذی كتاب البر والصلة باب ما جاء فى المجالس امانة (۱۹۵۹) مسند احمد (۳۷۹/۳) السنن الكبرى (۲۴۷/۱۰) الدر المنثور (۲۲۶/۵) فتح البارى (۸۲/۱۱) كنز العمال (۵۳۷۸)"}],[1033,"§۱۰۳۳ ۔ جابر بن ابی صعصعہ(1)\nعمرو بن زید بن عوف بن مبذول بن عمرو بن غنم بن مازن بن النجار انصاری مازنی ابن القداح نے انصار کے نسب میں ان کا تذکرہ کیا ہے، فرماتے ہیں: عوف بن مبذول کی اولاد سے قیس بن ابی صعصعہ ہیں جو عقبہ، بدر میں شریک ہوئے اور ان کے بھائی جابر بن ابی صعصعہ نے اُحد اور بعد کے غزوات میں شرکت کی۔ اور جنگ موتہ میں شریک ہوئے۔ ایسا ہی ابن سعد اور ابن شاہین نے جابر کے متعلق لکھا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۴۲) الاستيعاب (۲۹۷)"}],[1034,"§۱۰۳۴ ۔ جابر بن عمیر انصاری(1)\nامام بخاری رحمہ اللہ کا ارشاد ہے: انہیں شرف صحابیت حاصل ہے۔ اور بقول ابن حبان(2) بعض لوگوں کا کہنا ہے کہ یہ صحابی ہیں۔ نسائی(3) نے عطاء سے صحیح سند کے ساتھ روایت کیا، فرمایا: میں نے جابر بن عبداللہ اور جابر بن عمر کو کشتی کرتے دیکھا، ان میں سے ایک اکتا کر بیٹھ گئے تو ان کے ساتھی کہنے لگے: ست پڑ گئے ہو کیا؟ فرمایا: ہاں۔ فرمایا جہاں تک میرا تعلق ہے تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"سوائے چار چیزوں کے جس میں اللہ کا ذکر نہیں ہوگا وہ کھیل تماشا ہے\"۔ (حدیث)","",{"fn":"(1) اسد الغابۃ (۶۵۰) الاستيعاب (۲۹۶) تجريد اسماء الصحابة (۷۳/۱)\n(2) الثقات (۵۳/۳)\n(3) نسائی فی عشرة النساء فی السنن الكبرى على ما فى تحفة الأشراف (۴۰۴/۲)"}],[1035,"§۱۰۳۵ ۔ (ز) جابر بن عوف\nابن طارق میں تذکرہ ہو چکا ہے۔"],[1036,"§۱۰۳۶ ۔ جابر بن عوف الثقفی(1)\nسعید بن یعقوب نے ان کا ذکر کیا اور یعلی بن عطاء کی سند سے بحوالہ ان کے والد اوس بن ابی اوس (ان کا نام جابر بن عوف) سے روایت نقل کی ہے کہ نبی صلی اللہ علیہ وسلم نے نماز پڑھی اور اپنے پیروں پر تر ہاتھ پھیرا۔(2) (کتابوں میں) محفوظ، ابواوس کا نام حذیفہ ہے جیسا کہ آئے گا۔","",{"fn":"(1) اسد الغابۃ (۶۵۱) تجريد (۷۳/۱)\n(2) اسد الغابۃ (۲۹۷/۱)"}],[1037,"§۱۰۳۷ ۔ جابر بن ماجد الصدفی(1)\nابن یونس نے ان کا تذکرہ کیا اور کہا کہ وہ نبی صلی اللہ علیہ وسلم کے پاس وفد میں آئے اور فتح مصر میں شریک تھے۔ ابن لہیعہ نے عبدالرحمن بن قیس بن جابر صدفی سے وہ اپنے والد وہ اپنے دادا سے ایک حدیث روایت کرتے ہیں جس کا متن یہ ہے: \"عنقریب میرے بعد خلفاء ہوں گے، پھر امراء اس کے بعد ظالم بادشاہ ہوں گے\"۔ (حدیث)(2) اوزاعی نے اس کے خلاف روایت کی ہے، چنانچہ وہ اسے قیس بن جابر سے وہ اپنے والد اپنے دادا سے، اس بنا پر روایت جابر کے والد ماجد کی ہوگی اور ابن لہیعہ والی روایت میں \"اپنے دادا سے\" مراد قیس ہوں گے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۶۵۳) الاستيعاب (۲۹۲)\n(2) ابن حبان (۱۵۵۶) سنن الكبرى (۱۵۸/۸) كنز العمال (۳۸۶۶۷)"}],[1038,"§۱۰۳۸ ۔ جابر بن نعمان(1)\nبن عمیر بن مالک بن قمیر بن مالک بن سواد البلوی۔ انصار کے حلیف۔ ابن کلبی نے ان کا ذکر کر کے کہا: وہ کعب بن عجرہ کے خاندان سے تعلق رکھتے ہیں اور صحابی ہیں۔ ان کے نسب میں سواد نامی شخص کا نام ابن ماکولا(2) نے شروع کے پیش سے قلمبند کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۵۴) الاستيعاب (۲۹۵)\n(2) الاكمال (۴۲/۲)"}],[1039,"§۱۰۳۹ ۔ جابر بن یاسر(1)\nبن عویص بروزن قدیر (ع اور صاد سے) الرعینی۔ بقول ابن مندہ صحابہ میں ان کا ذکر آتا ہے اور ابن یونس لکھتے ہیں: فتح مصر میں شریک تھے یہ عباس بن جابر کے بیٹوں عباس اور جابر کے دادا ہیں۔ ان کی کوئی حدیث معروف نہیں ہے۔","",{"fn":"(1) اسد الغابۃ (۶۵۵)"}],[1040,"§۱۰۴۰ ۔ (ز) جابر الاسدی\nسیف نے فتوح میں ذکر کیا کہ سعد بن ابی وقاص نے قادسیہ کی لڑائی میں بعض مہمات کا انہیں امیر مقرر کیا تھا۔ اور یہ پہلے گزر چکا ہے کہ امارت صرف صحابہ کو دی جاتی تھی۔ ابن فتحون نے ان کا استدراک کیا ہے۔"],[1041,"§۱۰۴۱ ۔ جاحل ابو مسلم الصدفی(1)\nابن مندہ نے ابن وہب کی سند سے بحوالہ ابوالاشیم دمیاط کی مسجد کے موذن وہ شراحیل بن یزید سے وہ محمد بن مسلم بن جاحل سے وہ اپنے والد وہ اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس قرآن کو زیادہ یاد رکھنے والے میری اُمت کے منافق لوگ ہوں گے\"۔(2) فرماتے ہیں: یہ انوکھی حدیث ہے جسے ہم اسی سند سے پہچانتے ہیں۔ ابونعیم نے ان کا تذکرہ کرتے ہوئے لکھا: میرے نزدیک ان کا صحابی ہونا مسلّم نہیں۔ متقدمین و متاخرین میں سے کسی نے ان کا ذکر نہیں کیا۔ محمد بن ربیع جیزی نے مصر فروکش ہونے والے صحابہ میں ان کا ذکر کیا ہے۔ فرمایا: ہم نہیں جانتے وہ فتح میں شریک تھے اور نہ مصر میں ان کی کوئی جائیداد ہی ہے۔ البتہ مصری ان کے حوالہ سے ایک حدیث روایت کرتے ہیں پھر وہ حدیث ذکر کی، اسے ابن یونس اور ابن زبر نے ذکر کیا ہے۔ ان میں ابن مندہ قابل نمونہ ہیں۔","",{"fn":"(1) اسد الغابۃ (۶۵۶)\n(2) جمع الجوامع (۶۱۲۴) جامع المسانيد والسنن (۵۸۵/۲)"}],[1042,"§۱۰۴۲ ۔ الجارود بن المعلّی(1)\nانہیں ابن عمرو بن المعلی بھی کہا جاتا ہے۔ بقول بعض الجارود بن العلاء، ترمذی نے \"عبدی ابوالمنذر\" نسبت و کنیت سے ان کا ذکر کیا ہے۔ بقول بعض ابوغیاث (زیادہ صحیح غین اور ثاء سے ہے) بعض نے عین اور باء سے کہا ہے۔ کچھ لوگوں کا کہنا ہے کہ ان کا نام بشر بن حنش ہے (حا اور نون زبر والا پھر شین نقطوں والا) اور ابن اسحاق فرماتے ہیں: جارود بن عمرو بن حنش پہلے عیسائی تھے نبی صلی اللہ علیہ وسلم کے پاس آئے پھر وہ قصہ ذکر کیا۔ ان کے نام کے متعلق اور کچھ بھی لوگوں نے کہا ہے، ان کا لقب جارود (خالی کر دینے والا) اس وجہ سے پڑا کیونکہ انہوں نے بکر بن وائل پر حملہ کر کے ان کا استیصال کر دیا تھا۔ شاعر کہتا ہے: \"ہم نے ہر طرف سے ان پر گھوڑے گھسیڑ دیئے جیسے جارود نے بکر بن وائل کا صفایا کر دیا تھا\"۔ وہ قبیلہ عبدالقیس کے سردار تھے۔ ابن السکن ان کے لقب کی یہ وجہ بیان کرتے ہیں کہ عبدالقیس کے علاقہ میں قحط پڑا تو جارود کے چند اونٹ رہ گئے۔ وہ انہیں لے کر اپنے ماماؤں بنی قدید بن شیبان کے ہاں چل دیئے۔ ان کے ماماؤں کے اونٹ خارشی ہونے لگے تو لوگ کہتے پھرتے تھے بشر نے انہیں خارشی بنا دیا ہے، یوں \"جاروڈ\" ان کا لقب پڑ گیا۔ اور شاعر نے کہا پھر وہ اشعار ذکر کیے۔\n\nجارود عبدالقیس کے آخری وفد میں ۱۰ھ میں آئے۔ نبی صلی اللہ علیہ وسلم ان کے اسلام لانے سے بہت خوش ہوئے۔ طبرانی(2) نے زربی بن عبداللہ کی سند سے سیدنا انس رضی اللہ عنہ سے روایت نقل کی ہے۔ فرمایا: جب جارود نبی صلی اللہ علیہ وسلم کے پاس وفد میں آئے تو آپ ان سے بے حد خوش ہوئے انہیں اپنے قریب رکھا اور نزدیک بٹھایا۔ ابن اسحاق کا مغازی میں قول ہے: ان کا اسلام بہت عمدہ تھا اور بڑے کٹر دیندار تھے۔ طبرانی(3) نے ابن سیرین کی سند سے بحوالہ جارود روایت کرتے ہیں۔ فرمایا: میں نے نبی صلی اللہ علیہ وسلم کے پاس آ کر عرض کیا: میرا ایک مذہب ہے، میں اپنا مذہب چھوڑ کر آپ کے دین میں داخل ہوا تو اللہ تعالیٰ مجھے عذاب تو نہیں دے گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں دے گا۔ بغوی نے اسے طویل ذکر کیا ہے۔\n\nجارود سیدنا ابو ہریرہ رضی اللہ عنہ کے داماد تھے اور بحرین میں ان کے ساتھ تھے۔ جب سیدنا عمر رضی اللہ عنہ نے انہیں روانہ فرمایا تھا جیسا کہ قدامہ بن مظعون رضی اللہ عنہ کے سوانح میں آئے گا۔ وہ فارس کی زمین عقبہ الطین (مٹی کی گھاٹی) میں شہید ہوئے، اس کا نام ہی عقبہ الجارود پڑ گیا۔ یہ سیدنا عمر کی خلافت ۲۱ھ کی بات ہے۔ بقول بعض وہ نہاوند میں نعمان بن مقرن کے ساتھ شہید ہوئے اور ایک قول ہے کہ سیدنا عثمان رضی اللہ عنہ کی خلافت تک زندہ رہے۔ ابن مندہ نے ابوبکر بن ابی الاسود کی سند سے بحوالہ جارود کی اولاد میں سے کسی شخص نے نقل کیا کہ وہ سیدنا عمر رضی اللہ عنہ کی خلافت میں فارس کی زمین میں شہید ہوئے۔ ابوعمر رضی اللہ عنہ کہتے ہیں: ان کے عمدہ اشعار یہ ہیں:\n\n\"میں گواہی دیتا ہوں کہ اللہ تعالیٰ برحق ہے اور میرے دل کے خیالات گواہی دینے اور اٹھنے سے چشم پوشی کرتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم تک میرا پیام پہنچا دے، میں جہاں بھی زمین پر ہوا دین حنیف پر رہوں گا۔ اگرچہ میرا گھر یثرب میں تمہارے درمیان نہیں، پھر بھی اٹھتے بیٹھتے میں تمہارے ساتھ ہوں۔ میں اپنی جان کو تم پر آنے والی ہر مصیبت کے سامنے ڈھال بنالوں گا اور اپنی عزت سے تمہاری عزت بچاؤں گا\"۔\n\nان کے بیٹے المنذر بن الجارود بصرہ میں عبدالقیس کے سرداروں میں سے تھے، جن کی تعریف اشیٰ حرمازی نے کی ہے اور ان کا پوتا حکم بن منذر وہی ہے جس کے متعلق یہی اشیٰ کہتا ہے:\n\n\"اے حکم! منذر بن جارود کے بیٹے، بزرگی کی قناتیں تجھ پر تنی ہیں۔ تو سخی کا بیٹا قابل تعریف سخی ہے تو سخاوت والے گھر میں سخاوت میں پلا ہے\"۔\n\nفرماتے ہیں: حجاج ان کے اشعار کی وجہ سے حکم سے حسد کرتا تھا۔","",{"fn":"(1) اسد الغابۃ (۶۵۷) الاستيعاب (۴۵۴) تجريد (۷۴/۱)\n(2) المعجم الكبير (۲۶۴/۲)\n(3) المعجم الكبير (۲۶۸/۲)"}],[1043,"§۱۰۴۳ ۔ الجارود بن المنذر العبدی(1)\nیہ دوسرے ہیں۔ امام بخاری نے ان میں اور سابقہ شخصیت کے درمیان کتاب الوحدان میں فرق کیا ہے یہ ابن مندہ کا قول ہے اور انہیں وہی شخصیت قرار دیا ہے جن سے حضرت ابن سیرین روایت کرتے ہیں۔ رہے حسن بن سفیان اور طبرانی وغیرہ تو انہوں نے ابن سیرین کی حدیث سابقہ والے جارود کے سوانح میں نقل کی ہے۔ درست یہ ہے کہ یہ دو شخص ہیں۔ اس لئے کہ جارود بن منذر اتنا زندہ رہے کہ ان سے حسن بصری اور ابن سیرین نے روایت لی ہے۔ اور جارود بن معلی اس سے پہلے فوت ہو گئے۔ منذر ان کی کنیت ہے ان کے والد کا نام نہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۶۵۸)"}],[1044,"§۱۰۴۴ ۔ جاریہ بن اصرم کلبی اجداری(1)\nاز بنی عامر بن عوف، عامر اجدار کے نام سے شہرت رکھتے ہیں۔ شرقی بن قطامی نے زہیر بن منظور سے بحوالہ جابر بن اصرم روایت کیا ہے: میں نے جاہلیت میں دومۃ الجندل میں ود بت کو مرد کی صورت میں دیکھا۔(2) ابن ماکولا(3) فرماتے ہیں: جاریہ بن اصرم صحابی کا شمار بصری صحابہ میں ہوتا ہے۔ اور ابونعیم لکھتے ہیں: وہ صحابی نہیں ہیں۔","",{"fn":"(1) اسد الغابۃ (۶۵۹)\n(2) ايضًا (۲۹۹/۱)\n(3) الاكمال (۲۹۲/۲)"}],[1045,"§۱۰۴۵ ۔ جاریہ بن جابر العصری\nرشاطی نے ان کا ذکر کیا کہ وہ وفد عبد القیس کے ایک فرد تھے۔ میں کہتا ہوں: ابن مندہ نے ان کا \"جویریہ العصری\" کے نام سے ذکر کیا ہے۔ میرے خیال میں یہ وہی ہیں۔ صحار بن عباس عبدی کے سوانح میں ان کا ذکر ہے کہ جو لوگ اشج کے ساتھ آ کر اسلام لائے ان میں یہ بھی تھے۔"],[1046,"§۱۰۴۶ ۔ جاریہ بن حمیل(1)\n(بے نقطے حرف سے تصغیر ہے) ابن شبہ بن قرط الاشجعی۔ بقول طبری: اسلام لائے اور نبی صلی اللہ علیہ وسلم کے صحابی ہوئے۔ دار قطنی وغیرہ نے ان کے حوالہ سے اُن کا ذکر کیا ہے۔ ابن کلبی کہتے ہیں: جاریہ بن حمیل بن شبہ بن قرط بن مرہ بن بصار بن دہمان بن نصر بن سمیع بن بکر بن اشجع دھمانی اشجعی، نبی صلی اللہ علیہ وسلم کی معیت میں بدر میں شریک ہوئے۔ بقول ابن البرقی: احد میں شہید ہوئے۔(2)","",{"fn":"(1) اسد الغابۃ (۶۶۰) الاستيعاب (۳۰۷)\n(2) اسد الغابۃ (۲۹۹/۱) الاستيعاب (۳۰۰/۱)"}],[1047,"§۱۰۴۷ ۔ جاریہ بن زید(1)\nابن کلبی نے انہیں سیدنا علی رضی اللہ عنہ کے ساتھ صفین میں شریک صحابہ میں شمار کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۶۱) الاستيعاب (۳۰۹)"}],[1048,"§۱۰۴۸ ۔ جاریہ بن ظفر الیمامی الحنفی(1)\nابو نمران۔ بقول ابن حبان: صحابی ہیں۔ اور بروایت دہشم بن قرآن، بحوالہ نمران بن جاریہ وہ اپنے والد سے، ابن ماجہ میں دو حدیثیں ہیں۔(2) ان کی روایت صرف دہشم کی سند سے مشہور ہے۔ اور دہشم بے حد ضعیف راوی ہے۔ یزید بن معبد حنفی یمامی کے سوانح میں جاریہ کا تذکرہ آئے گا۔","",{"fn":"(1) اسد الغابۃ (۶۶۲) الاستيعاب (۳۰۸) تجريد (۷۵/۱)\n(2) ابن ماجہ كتاب الاحكام باب الرجلان يدعيان فى خص (۲۳۴۲)"}],[1049,"§۱۰۴۹ ۔ جاریہ بن عبداللہ الاشجعی\nانصار میں سے بنی سلمہ کے حلیف۔ ابن فتحون نے ان کا استدراک کیا اور سیف بن عمر سے نقل کیا کہ وہ جنگ یرموک کے روز سیدنا خالد بن ولید کے ہمراہ بائیں دستے کے امیر تھے۔ اسے دار قطنی اور ابن ماکولا نے سیف سے روایت کیا ہے اور یہ پہلے گزر چکا ہے کہ سیدنا عمر رضی اللہ عنہ کے زمانے کی جنگوں میں صرف صحابہ کو امارت ملتی تھی۔"],[1050,"§۱۰۵۰ ۔ جاریہ بن قدامہ(1)\nبن مالک بن زہیر بن حصن بن رزاح بن سعد بن بکیر بن ربیعہ بن کعب بن سعد بن زید مناۃ ابن تمیم تیمی سعدی۔ انہیں \"احنف کا چچا\" بھی کہا جاتا ہے۔\n\nطبرانی فرماتے ہیں کہ احنف انہیں تعظیماً چچا کہا کرتے تھے، ورنہ وہ دونوں سعد بن زید میں یکجا ہو جاتے ہیں۔ ابن سعد نے بصرہ فروکش ہونے والے صحابہ میں ان کا ذکر کیا ہے اور ابن ابی حاتم(2) بحوالہ اپنے والد فرماتے ہیں: یہ صحابی ہیں۔ امام احمد نے یحییٰ بن سعید وغیرہ سے بحوالہ ہشام بن عروہ وہ اپنے والد سے وہ احنف سے وہ جاریہ بن قدامہ سے روایت کرتے ہیں۔ فرمایا: میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! مجھے کوئی وصیت فرمائیے اور ہو بھی مختصر سی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"غصہ نہ کرنا\"۔(3) یہ روایت ابن مندہ کی \"معرفت\" نامی کتاب میں عالی سند سے ہے۔ اس میں ہشام سے آگے اختلاف ہے۔ ان کے اکثر شاگرد نے ایسا ہی نقل کیا ہے جیسا پہلے گزر گیا۔ ابن حبان نے اپنی سند سے اس کی تصحیح کی ہے اور ابو معاویہ اور یحییٰ بن ابی زکریا غسانی اور سعید بن یحییٰ اللحمی نے اسے ہشام سے نقل کیا تو اس میں یہ اضافہ کیا \"جاریہ سے وہ اپنے چچا سے\" جبکہ اسے ابن ابی شیبہ نے عبدہ بن سلیمان سے بحوالہ ہشام اس کے برعکس روایت کیا ہے۔ فرماتے ہیں: \"احنف سے وہ اپنے چچا سے وہ جاریہ سے\"۔\n\nابو یعلی کی روایت میں لکھا ہے: جاریہ بن قدامہ سے وہ اپنے والد کے چچا سے پھر وہ حدیث ذکر کی۔ پہلی سند زیادہ بہتر ہے۔ چنانچہ طبرانی نے ابن ابی زناد کی سند سے بحوالہ ان کے والد وہ عروہ سے، اور محمد بن کریب کی سند سے بحوالہ ان کے والد مروی ہے، فرمایا: میں احنف کے پاس تھا وہ اپنے چچا سے وہ اپنے چچا جاریہ بن قدامہ سے وہ ابن عباس رضی اللہ عنہما کے پاس تھے، انہوں نے عرض کیا: مجھے کوئی ایسی بات بتائیں جو مجھے نفع دے اور مختصر کریں... (حدیث)\n\nابو عمر رضی اللہ عنہ فرماتے ہیں: وہ سیدنا علی رضی اللہ عنہ کی جنگوں میں ان کے ساتھی تھے۔ یہ وہی ہیں جنہیں عبداللہ بن حضرمی نے بصرہ کے دارسعید میں جلا دیا تھا۔ اس لئے کہ سیدنا معاویہ نے ابن حضرمی کو ان کی گرفتاری کے لیے بھیجا تھا۔ سیدنا علی رضی اللہ نے اعین بن ضبیعہ کو روانہ کیا وہ قتل ہو گئے تو جاریہ بن قدامہ کو روانہ کیا۔ ابن حضرمی نے ان کا محاصرہ کر لیا پھر آگ لگا دی۔ بقول بعض وہ جویریہ بن قدامہ ہیں جو بخاری میں اپنے چچا سے روایت کرتے ہیں۔\n\nان جاریہ کا امیر معاویہ کے ساتھ ایک قصہ پیش آیا جس میں وہ کہتے ہیں: سیدنا معاویہ نے ان سے کہا: ابو قندس! اپنی ضرورت بیان کرو۔ انہوں نے کہا: لوگوں کو ان کے گھروں میں رہنے دو، انہیں اپنے پاس بلانے کے لیے قاصد نہ بھیجئے اس لئے کہ وہ آپ کے پاس مالداروں کو تو لے آتے ہیں جبکہ ناداروں کو چھوڑ آتے ہیں۔","",{"fn":"(1) اسد الغابۃ (۶۶۴) الاستيعاب (۳۰۶) تجريد (۷۵/۱)\n(2) الجرح والتعديل (۵۲۰/۲)\n(3) بخاری كتاب الادب باب الحذر من الغضب (۶۱۱۶) ترمذی كتاب البر والصلة باب ما جاء فى كثرة الغضب (۲۰۲۰) مسند احمد (۴۸۴/۳) المستدرك (۶۱۵/۳) الصحيح لابن حبان (۱۹۷۱، ۱۹۷۲) المصنف لابن ابی شيبہ (۳۴۵/۸) المعجم الكبير (۲۶۱، ۲۶۲/۲) السنن الكبرى (۱۰۵/۱۰) التاريخ الكبير (۲۶۷/۵)"}],[1051,"§۱۰۵۱ ۔ جاریہ بن مجمّع(1)\nبن جاریہ انصاری۔ طبرانی وغیرہ نے ان کا ذکر تو کیا ہے لیکن انہوں نے ان کے سوانح میں یہ ذکر کر دیا ہے کہ وہ قرآن(2) جمع کرنے والوں میں سے ایک ہیں۔ جبکہ محفوظ روایت ان کے والد کے بارے میں ہے۔","",{"fn":"(1) اسد الغابۃ (۶۶۵) تجريد اسماء الصحابة (۷۵/۱)\n(2) المعجم الكبير (۲۶۱/۲) الفتح للحافظ (۵۳/۹)"}],[1052,"§۱۰۵۲ ۔ جاہمہ بن العبّاس(1)\nبن مرداس اسلمی، سنن میں ابن ماجہ نے ان کا یہی نسب بیان کیا ہے اور ابن السکن فرماتے ہیں: انہیں ابن العباس بن مرداس بھی کہا جاتا ہے۔ ابن سعد(2) نے خندق میں شریک طبقہ میں ان کا ذکر کیا کہ وہ اسلام لائے اور صحابی بنے۔ بغوی، ابن ابی خیثمہ اور طبرانی نے سفیان بن حبیب کی سند سے بحوالہ ابن جریج محمد بن طلحہ بن یزید بن رکانہ سے انہوں نے معاویہ بن جاہمہ سلمی سے وہ اپنے والد سے روایت کرتے ہیں، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس جہاد میں شرکت کے مشورے کے لیے آیا، آپ نے فرمایا: کیا تمہاری والدہ زندہ ہے؟ میں نے عرض کیا: جی ہاں۔ فرمایا: \"بس اس کی خدمت میں لگے رہو\"۔(3) اس روایت میں ابن جریج سے آگے راویوں کا اختلاف ہے۔ سفیان بن حبیب نے عمدہ سند بیان تو کی لیکن طلحہ کو سند سے ساقط کر دیا۔ یہ بغوی کا قول تھا بقول بعض: یحییٰ بن سعید قطان سے بحوالہ ابن جریج ایسی ہی روایت منقول ہے اور یحییٰ بن سعید اموی نے ابن جریج سے بحوالہ محمد بن طلحہ بن یزید بن رکانہ وہ اپنے والد سے وہ معاویہ بن جاہمہ سے روایت کرتے ہیں، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آیا۔ بغوی نے یہ روایت شریح بن یونس سے بحوالہ اموی نقل کی ہے پھر اسے حجاج بن محمد کی سند سے بحوالہ ابن جریج روایت کی تو محمد بن طلحہ کا نسب مختلف کر دیا۔ چنانچہ لکھتے ہیں: محمد بن طلحہ بن عبداللہ بن عبدالرحمن وہ اپنے والد طلحہ سے وہ معاویہ بن جاہمہ سے کہ جاہمہ نبی صلی اللہ علیہ وسلم کے پاس آئے پھر وہ حدیث ذکر کی۔ ایسا ہی نسائی اور ابن ماجہ نے حجاج کی سند سے روایت کیا ہے امام بیہقی فرماتے ہیں: حجاج کی روایت زیادہ صحیح ہے۔ ابو عاصم نے ان کی متابعت کی ہے وہ روایت ابن شاہین کی کتاب میں معاویہ بن جاہمہ کے سوانح میں درج ہے۔\n\nمیں کہتا ہوں: امام احمد رحمہ اللہ نے یہ روایت بحوالہ روح بن عبادہ، حجاج کی روایت کی طرح نقل کی ہے جبکہ ابن ماجہ نے محمد بن اسحاق کی سند سے یوں نقل کی: محمد بن طلحہ بن عبدالرحمن بن ابی بکر سے، حجاج کی موافقت تو کی البتہ عبداللہ بن طلحہ کا نام حذف کر دیا۔ اور ابن شاہین نے معاویہ بن جاہمہ کے سوانح میں ابراہیم بن سعد کی روایت سے بحوالہ ابن اسحاق نقل کی تو ان کا نام برقرار رکھا۔ ادھر محمد بن سلمہ خزاعی نے بحوالہ محمد بن اسحاق ان کی متابعت کی ہے یہی ان سے مشہور ہے۔ بقول بعض: ابن اسحاق سے بحوالہ زہری وہ ابن طلحہ سے وہ معاویہ سلمی سے۔ ابن لہیعہ نے کہا: یونس بن یزید سے بحوالہ ابن اسحاق اسی سند سے لیکن صحابی کا نام اور نسبت بدل دی، یوں کہا: \"جہم اسلمی ہے\" اور عبدالرحمن بن سلیمان نے بحوالہ ابن اسحاق روایت کی تو کہا: محمد بن طلحہ اپنے والد طلحہ بن معاویہ بن جاہمہ سے، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آیا۔ یہ غلط ہے جو لفظی غلطی ہے اور ادل بدل سے پیدا ہوئی۔ درست یوں ہے: محمد بن طلحہ سے وہ معاویہ بن جاہمہ سے وہ اپنے والد سے۔ لکھنے والے نے \"عن\" کو \"ابن\" کر دیا اور \"عن ابیہ\" کو مقدم کر دیا جس سے یہ ظاہر ہوا کہ طلحہ کے لیے صحابیت ثابت ہے جبکہ ایسا ہے نہیں۔ بلکہ حقیقت یہ ہے کہ ان میں اور معاویہ بن جاہمہ میں خاندانی نسبت نہیں۔ اگر معاملہ سند کے ظاہر پر ہوتا تو یہ چاروں حضرات یکے بعد دیگرے اصحاب رسول صلی اللہ علیہ وسلم بن جاتے: طلحہ بن معاویہ بن جاہمہ بن عباس بن مرداس۔ طبرانی(4) نے سلیمان بن حرب کی سند سے بحوالہ محمد بن طلحہ بن مصرف، معاویہ بن درہم سے روایت نقل کی ہے کہ درہم نبی صلی اللہ علیہ وسلم کے پاس آئے، کہنے لگے: میں آپ صلی اللہ علیہ وسلم کے پاس جہاد میں شرکت کے مشورہ کے لیے آیا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تمہاری والدہ زندہ ہے یا نہیں؟ انہوں نے عرض کیا: جی ہاں، زندہ ہے۔ فرمایا: \"بس اس (کی خدمت) سے جدا نہ ہونا\"۔ یہی قصہ بعینہ جاہمہ کے ساتھ پیش آیا۔ اگر لفظ جاہمہ درہم سے بدل گیا ہو، ان کے نسب میں محمد بن طلحہ لکھا ہے یوں ان کے دادا کے نام میں وہم ہوا، ورنہ یہ کوئی اور قصہ ہے جو کسی دوسری شخصیت کے ساتھ پیش آیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۶۶) الاستيعاب (۳۵۶) تجريد (۷۵/۱)\n(2) الطبقات الكبرى (۱۷/۴)\n(3) نسائی كتاب الجهاد باب الرخصة فى التخلف لمن له والدة (۳۱۰۴) ابن ماجہ كتاب الجهاد باب الرجل يغزو وله ابوان (۲۷۸۱)\n(4) المعجم الكبير (۲۸۹/۲)"}],[1053,"§۱۰۵۳ ۔ جبّار بن الحارث\nعبد الجبار میں تذکرہ آئے گا۔"],[1054,"§۱۰۵۴ ۔ جبار بن الحکم السلمی(1)\nابن سعد اور مدائنی نے نبی صلی اللہ علیہ وسلم کے پاس وفد میں آ کر اسلام لانے والوں میں ان کا تذکرہ کیا ہے۔(2)","",{"fn":"(1) اسد الغابۃ (۶۶۸)\n(2) اسد الغابۃ (۳۰۲/۱)"}],[1055,"§۱۰۵۵ ۔ جبار بن سلمیٰ(1)\n(سین کے پیش سے)\n\n(بقول بعض زیر ہے) ابن مالک بن جعفر بن کلاب بن ربیعہ بن عامر بن صعصعہ کلابی۔ ان کے والد کو \"نزال المضیق\" کہا جاتا ہے۔ ابن سعد نے ذکر کیا کہ وہ نبی صلی اللہ علیہ وسلم کے پاس عامر بن طفیل کے ساتھ وفد میں آئے۔ یہ عامر بن طفیل وہی مشرک ہے، جس نے عامر بن فہیرہ رضی اللہ عنہ کو شہید کیا تھا۔ مغازی ابن اسحاق میں ہے، جبار بن سلمی کی اولاد میں سے ایک شخص نے مجھے بتایا، جبار ان لوگوں میں سے تھے جو اس روز عامر بن طفیل کے ساتھ بئر معونہ میں شریک تھے۔ بعد میں اسلام لائے۔ واقدی نے ذکر کیا کہ وہ ضحاک بن سفیان کلابی کے ہاتھ پر مسلمان ہوئے تھے۔ واقدی ہی نے موسیٰ بن شیبہ کے واسطہ سے خارجہ سے بحوالہ عبداللہ بن کعب بن مالک روایت کی ہے کہ بنی کلاب کا وفد آیا اس میں تیرہ مرد تھے جن میں لبید بن ربیعہ بھی تھے یہ لوگ رملہ بنت حارث کے گھر فروکش ہوئے۔ جبار بن سلمی اور کعب بن مالک کے درمیان دوستانہ تھا۔ کعب نے انہیں خوش آمدید کہا اور جبار بن سلمی کا اعزاز و اکرام کیا اور ان کے ساتھ نبی صلی اللہ علیہ وسلم کے پاس چل کر گئے۔ پھر وہ قصہ ذکر کیا۔ ابن اسحاق اور واقدی وغیرہ نے ذکر کیا ہے کہ جبار بن سلمی وہی ہیں جنہوں نے اس روز عامر بن فہیرہ رضی اللہ عنہ کو نیزہ مارا تھا۔ تو انہوں نے کہا تھا: رب کعبہ کی قسم! میں کامیاب ہو گیا۔ نیزہ لگنے سے وہ زمین پر گرے تو سہی لیکن ان کا جسم نہ ملا۔ اس کرامت کی وجہ سے جبار اسلام لے آئے، بہترین مسلمان بن گئے۔(2) ابن کلبی روایت کرتے ہیں: لوگوں کا کہنا تھا کہ وہ عامر بن طفیل سے زیادہ گھڑ سوار تھے۔","",{"fn":"(1) اسد الغابۃ (۶۶۹) الاستيعاب (۳۱۱)\n(2) اسد الغابۃ (۳۰۲/۱)"}],[1056,"§۱۰۵۶ ۔ جبّار بن صخر(1)\nبن امیہ بن خنساء بن سنان بن عبید بن عدی بن غنم بن کعب بن سلمہ انصاری ثم سلمی۔ کنیت ابو عبداللہ تھی۔ موسیٰ بن عقبہ نے بحوالہ ابن شہاب اہل عقبہ میں ان کا ذکر کیا ہے۔ اور ابوالاسود نے بحوالہ عروہ اہل بدر میں۔ طبرانی(2) نے ابن اسحاق کی سند سے بحوالہ عبداللہ بن ابی بکر بن حزم نقل کیا کہ عبداللہ بن رواحہ تو صرف ایک سال پھل کا اندازہ لگانے گئے پھر وہ غزوہ موتہ میں شہید ہو گئے اس کے بعد رسول اللہ صلی اللہ علیہ وسلم جبار بن صخر کو اہل خیبر کے پھلوں کا اندازہ لگانے بھیجتے تھے۔\n\nمغازی ابن اسحاق میں ہے مجھے عبداللہ بن ابی بکر نے بحوالہ عبد بن مکتف بتایا کہ حارثہ نے مجھ سے بیان کیا: جب سیدنا عمر رضی اللہ عنہ نے خیبر کے یہودیوں کو باہر نکال دیا تو سوار ہو کر مہاجرین و انصار میں گھومے آپ کے ساتھ جبار بن صخر بھی تھے وہ اہل مدینہ کے قیاس گر اور ان کے خزانچی تھے (زرعی حساب و کتاب ان کے پاس تھا)۔ امام مسلم(3) نے عبادہ بن ولید کی سند سے بحوالہ جابر بن عبداللہ روایت کی ہے کہ وہ کسی غزوہ میں نبی صلی اللہ علیہ وسلم کی معیت میں تھے۔ پھر حدیث ذکر کی، فرماتے ہیں: آپ علیہ السلام نے فرمایا: \"ہم سے سے پہلے جا کر کون ہمارے لیے حوض کو جھری مٹی سے بند کرے گا تا کہ خود بھی سیراب ہو اور ہمیں بھی سیراب کرے\"۔ جابر فرماتے ہیں، میں نے عرض کیا: یہ شخص۔ آپ علیہ السلام نے فرمایا: \"جابر کے ساتھ کون ہے؟\" تو جبار بن صخر کھڑے ہو کر بولے: میں یا رسول اللہ صلی اللہ علیہ وسلم۔ (حدیث)\n\nامام احمد رحمہ اللہ(4) اور بغوی وغیرہ نے ابن ابی اویس کی سند سے بحوالہ شرجیل بن سعد جبار بن صخر سے اسی مفہوم کی حدیث روایت کی ہے۔ بغوی کہتے ہیں: مجھے اس کے علاوہ ان کی کوئی حدیث معلوم نہیں۔\n\nمیں کہتا ہوں: بلکہ ان کی ایک اور روایت بھی ہے جسے ابن شاہین اور ابن السکن وغیرہ نے زہیر بن محمد کی سند سے بحوالہ شرحبیل انہوں نے جبار بن صخر سے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"ہمیں اپنے اعضاء مستورہ دیکھنے سے روک دیا گیا ہے۔\"(5) ابراہیم بن ابی یحییٰ نے شرحبیل سے روایت کرنے میں ان (زہیر) کی متابعت کی ہے۔ اسے ابن مندہ نے نقل کیا ہے اور ابن السکن وغیرہ فرماتے ہیں: جبار بن صخر ۳۰ھ خلافت عثمانی رضی اللہ عنہ میں فوت ہوئے۔ ابو نعیم نے یہ اضافہ کیا ہے کہ وہ باسٹھ(۶۲) سال کے تھے۔","",{"fn":"(1) اسد الغابۃ (۶۷۰) الاستيعاب (۳۱۰)\n(2) المعجم الكبير (۲۷۰/۲)\n(3) مسلم كتاب الزهد باب حديث جابر الطويل و قصة ابی اليسر (۷۴۳۷)\n(4) مسند احمد (۴۲۱/۳)\n(5) كنز العمال (۲۱۶۸۴)"}],[1057,"§۱۰۵۷ ۔ (ز) جبّار الثعلبی\nواقدی نے مغازی میں ذکر کیا ہے کہ اصحاب رسول اللہ صلی اللہ علیہ وسلم نے ذی امر جاتے ہوئے انہیں ربیع الاول میں (جو ہجرت کا پچیسواں ابتدائی مہینہ بنتا تھا) گرفتار کیا تھا۔ نبی علیہ السلام کے پاس لائے، آپ صلی اللہ علیہ وسلم نے انہیں اسلام کی دعوت دی تو وہ مسلمان ہو گئے۔ دوسری جگہ انہوں نے ذکر کیا کہ وہ غطفان کی پیش قدمی میں نبی صلی اللہ علیہ وسلم کے راہ نما تھے (لیکن) وہ لوگ بھاگ نکلے تھے۔"],[1058,"§۱۰۵۸ ۔ (ز) جبّار بے نسبت\nجبلہ میں تذکرہ آئے گا۔"],[1059,"§۱۰۵۹ ۔ جبارہ (زیر اور تخفیف سے)\nابن زرارہ بلوی۔ ابن یونس(1) نے ان کا ذکر کیا ہے کہ وہ نبی صلی اللہ علیہ وسلم کے ساتھ رہے اور فتح مصر میں شریک ہوئے ان کی کوئی روایت نہیں ہے۔","",{"fn":"(1) اسد الغابۃ (۶۷۱) الاستيعاب (۳۸۷)"}],[1060,"§۱۰۶۰ ۔ جَبجَاب\nدو جیموں اور دو باؤں سے، بے نقطی حاء میں آئے گا۔"],[1061,"§۱۰۶۱ ۔ جبر بن انس\nبن سعد بن عبد اللہ بن عبدیالیل بن خزاق بن غفار غفاری۔ ابن ماکولا(1) نے ان کا ذکر کیا کہ وہ صحابی ہیں۔ انہیں جبر بن عبداللہ قبطی بھی کہا جاتا ہے، تذکرہ آئے گا۔","",{"fn":"(1) الاكمال (۱۱۵/۲)"}],[1062,"§۱۰۶۲ ۔ جبر بن انس(1)\nبن ابی زریق طبرانی(2) نے بحوالہ مطین ان کی سند سے جو عبداللہ بن ابی رافع تک ہے ان کا ذکر شرکائے صفین صحابہ میں کیا ہے جو سیدنا علی رضی اللہ عنہ کے ہمراه تھے۔ فرماتے ہیں: بدری ہیں۔ اس کی سند ضعیف ہے۔ مغازی کے مصنفین نے بدری صحابہ میں ان کا ذکر نہیں کیا۔ البتہ انہوں نے جبیر بن ایاس کا تذکرہ کیا ہے۔\n\nمیں کہتا ہوں: ابو موسیٰ نے روایت کیا ہے۔ انہیں جزء بن انس بھی کہا جاتا ہے، صحیح نہیں۔ اس واسطے کہ جزء بن انس کا تذکرہ آئے گا کہ وہ سلمی ہیں جبکہ یہ انصاری ہیں۔","",{"fn":"(1) اسد الغابۃ (۶۷۳)\n(2) المعجم الكبير (۲۵۹/۲)"}],[1063,"§۱۰۶۳ ۔ (ز) جبر بن ایاس\nجبیر میں تذکرہ ہوگا۔"],[1064,"§۱۰۶۴ ۔ جبر بن عبداللہ قبطی(1)\nبنی غفار کے غلام، انہیں ابو بصرہ غفاری کا غلام بھی کہا جاتا ہے۔ ابن یونس نے حسن بن علی بن خلف بن قدید سے نقل کیا ہے کہ وہ ماریہ قبطیہ رضی اللہ عنہا کو نبی صلی اللہ علیہ وسلم کے پاس پہنچانے کے مقوقس کی جانب سے قاصد تھے۔ حسن کہتے ہیں: مجھے مصر میں ان کی اولاد میں سے کوئی نظر آیا تھا۔ ہانی بن منذر کہتے ہیں: وہ ۶۳ھ میں فوت ہوئے۔(2)","",{"fn":"(1) اسد الغابۃ (۶۷۵) الاستيعاب (۳۱۴)\n(2) اسد الغابۃ (۳۰۴/۱) الاكمال (۱۴/۲)"}],[1065,"§۱۰۶۵ ۔ (ز) جبر بن ابی عبید ثقفی\nبلاذری نے ذکر کیا ہے کہ وہ اپنے والد کے ساتھ جسر کے روز شریک ہوئے جس کی تفصیل ابوعبید کے سوانح میں کنیتوں میں ان شاء اللہ آئے گی۔"],[1066,"§۱۰۶۶ ۔ جبر بن عتیک(1)\nبن قیس بن ھیشہ بن حارث۔ جابر بن عتیک میں ان کا تذکرہ گزر چکا ہے کہ وہ بدر میں شریک تھے۔ اور بعض کا قول ہے کہ وہ جابر بن عتیک کے بھائی ہیں۔ جن کا ذکر پہلے ہو گیا ہے۔ فتح مکہ کے روز ان کے پاس اپنی قوم کا جھنڈا تھا۔ واقدی فرماتے ہیں: جبر بن عتیک انصاری ۶۱ھ میں فوت ہوئے۔ ابن سعد(2) لکھتے ہیں: وہ تین بھائی: جابر، جبر اور عبداللہ تھے۔ جبر ان سے بڑے ہیں۔ ابن مندہ نے ان کے سوانح میں لکھا ہے، حجاج بن ارطاۃ کی سند سے بحوالہ ابراہیم بن مہاجر، موسیٰ بن طلحہ سے مروی ہے، فرمایا: میں نے جبر، سعد اور ابن مسعود رضی اللہ عنہ کو دیکھا ہے، یہ لوگ چوتھائی اور تہائی پر اپنی زمینیں دیتے تھے۔\n\nمیں کہتا ہوں: ابوعوانہ وغیرہ نے حجاج کے خلاف روایت کی ہے انہوں نے جبر کے بدلے خباب کہا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۷۶) الاستيعاب (۳۱۳)\n(2) الطبقات الكبرى (۳۷/۳)"}],[1067,"§۱۰۶۷ ۔ جبر (بے نسبت)\nابن قانع اور ابن مندہ نے رحمہ بن مصعب کی سند سے بحوالہ شریک بن اشعث بن سلیم، اسود بن ہلال سے نقل کیا، فرمایا: ہمارے ہاں ایک دیہاتی تھا جو حیرہ میں اذان دیا کرتا، اس کا نام جبر تھا۔ اس نے کہا: عثمان جب تک خلیفہ نہیں بن جاتے ہرگز فوت نہیں ہوں گے۔ کسی نے اس سے کہا تمہیں اس کا کیسے علم ہوا؟ اس نے کہا: میں نے ایک دفعہ نبی صلی اللہ علیہ وسلم کے ساتھ فجر کی نماز پڑھی، نماز سے فراغت کے بعد آپ صلی اللہ علیہ وسلم نے ہماری طرف رخ انور متوجہ کر کے فرمایا: آج کی شب میرے صحابہ کا وزن کیا گیا۔ ابو بکر رضی اللہ عنہ کو تولا گیا تو اس کا وزن بڑھ گیا۔ عمر رضی اللہ عنہ کو تولا گیا تو وہ بھی وزنی ہوا، عثمان رضی اللہ عنہ کو تولا گیا تو وہ بھی وزن دار ہوا۔(1) ابن مندہ کہتے ہیں: یہ حدیث اس سند سے غریب ہے جبکہ ابو موسیٰ نے کہا کہ ابن مندہ نے جبر بن عتیک کے حالات میں ان کا ذکر کیا ہے۔ جبکہ درست یہ ہے کہ یہ دوسری شخصیت ہے۔ میں کہتا ہوں: ایسے ہی ابو عمر نے ان کا علیحدہ ذکر کیا ہے اس میں ہے جبر اعرابی محاربی۔","",{"fn":"(1) كنز العمال (۳۲۰۸۰) (۳۶۱۸۶) اتحاف السادة المتقين (۶۸۰/۹)"}],[1068,"§۱۰۶۸ ۔ (ز) جبر\nعامر بن حضرمی کے غلام، بعد والی شخصیت کے سوانح میں ان کا تذکرہ آئے گا۔"],[1069,"§۱۰۶۹ ۔ (ز) جبر بنی عبدالدار کے غلام\nواقدی کا بیان ہے کہ وہ مکہ میں رہنے والے یہودی تھے۔ نبی صلی اللہ علیہ وسلم سے سورہ یوسف کی تلاوت سنی تو خفیہ طور پر اسلام لے آئے۔ بعد میں اپنے مالکوں کو بتایا تو وہ انہیں اذیت پہنچانے لگے۔ فتح مکہ کے موقع پر نبی صلی اللہ علیہ وسلم سے اس کی شکایت کی، آپ صلی اللہ علیہ وسلم نے انہیں ان کی قیمت دی تا کہ اپنے آپ کو خرید کر چھڑا لیں، یوں وہ آزاد اور مالدار ہو گئے اور بنی عامر کی ایک صاحب شرافت خاتون سے نکاح کر لیا۔ مقاتل بن حیان نے اپنی تفسیر میں نقل کیا ہے کہ وہ ان میں سے ایک ہیں جن کے متعلق یہ ارشاد باری تعالیٰ نازل ہوا:\n\n\"مگر وہ شخص کافر نہیں جسے مجبور کیا گیا اور اس کا دل ایمان پر مطمئن ہو\"۔ (سورۃ النحل: ۱۰۶)\n\nاور یہ ارشاد بھی انہی سے متعلق نازل ہوا:\n\n\"ہم نے تم میں سے بعض کو بعض کے لئے آزمائش کا ذریعہ بنایا ہے\"۔ (سورۃ الفرقان: ۲۰)\n\nطبری نے اپنی تفسیر میں اللہ تعالیٰ کے ارشاد:\n\n\"اس سے بڑھ کر کون ظالم ہو گا جو اللہ تعالیٰ کے متعلق جھوٹ بولے یا یہ کہے کہ میری طرف وحی آتی ہے\"۔ (سورۃ الانعام: ۹۳)\n\nکے متعلق سدی کی سند سے نقل کیا ہے کہ عبداللہ بن سعد بن ابی سرح اسلام لانے کے بعد مرتد ہو کر مشرکین سے جا ملا۔ عمار اور جبر ابن حضرمی یا ابن عبدالدار کے غلام کی چغلخوری کی تو انہوں نے ان دونوں کو پکڑ لیا اور انہیں اذیتیں دینے لگے۔ ان دونوں نے انکار کر دیا، جس پر یہ آیت:\n\n\"اگر وہ مجبور کیا گیا اور اس کا دل ایمان پر مطمئن ہو\"۔ (سورۃ النحل: ۱۰۶)\n\nنازل ہوئی۔ ابن ابی حاتم اور عبد بن حمید کی تفسیر میں حصین بن عبد الرحمن کی سند سے بحوالہ عبداللہ بن مسلم الحضرمی منقول ہے۔ فرمایا: ہمارے دو غلام تھے، ایک کا نام یسار اور دوسرے کا جبر تھا۔ دونوں لوہار تھے۔ دونوں اپنی کتابیں پڑھتے اور ان پر عمل کرتے۔ رسول اللہ صلی اللہ علیہ وسلم وہاں سے گزرے تو دونوں کی قراءت سننے لگے لوگ کہنے لگے (محمد صلی اللہ علیہ وسلم) ان سے سیکھتا ہے جس پر یہ آیت نازل ہوئی:\n\n\"ہمیں بخوبی علم ہے کہ وہ کہتے ہیں کہ اس (پیغمبر) کو کوئی انسان سکھاتا ہے\"۔ (سورۃ النحل: ۱۰۳)\n\nیہ ذکر نہیں کیا کہ وہ مسلمان ہوئے تھے۔ اور قتادہ کی سند سے وہ ابن الحضرمی کے غلام کے بارے میں نازل ہوئی جس کا نام تحنقس تھا۔ جس کا تذکرہ عنقریب آئے گا۔ ابن فتحون نے ان کا استدراک کیا ہے۔"],[1070,"§۱۰۷۰ ۔ جبر الکندی(1)\nابن شاہین نے عمرو بن غیاث کی سند سے بحوالہ عبدالملک بن عمیر، کندہ کے ایک ابن جبر کندی نامی شخص سے وہ اپنے والد سے روایت کرتے ہیں جو وفد میں تھے کہ نبی صلی اللہ علیہ وسلم نے سکاسک اور سکون کے لیے دعا فرمائی اور فرمایا: اہل یمن مسلمان ہو گئے، وہ نرم دل لوگ ہیں۔ اور مجھے یہ روایت پہنچی ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ! ان کے دل متوجہ فرما۔\"(2) مسند بقی بن مخلد میں یہ حدیث ابن جبیر سے بحوالہ ان کے والد مروی ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۶۷۷)\n(2) بخاری کتاب المغازی باب قدوم الاشعریین واہل الیمن (۴۲۸۸) مسلم کتاب الایمان باب تفاضل اہل الایمان فیہ (۱۸۲) ترمذی کتاب المناقب باب فضل الیمن (۳۹۳۵) (۳۹۳۴) مسند احمد (۲۷۷/۲) (۲۵۵/۲) المعجم الکبیر (۱۲۵/۵) دلائل النبوۃ (۲۳۶/۶) المطالب العالیہ (۴۴۳۰) کنز العمال (۳۷۷۹۱۲)"}],[1071,"§۱۰۷۱ ۔ جبل (جیم اور باء کے زبر سے)\nابن جول(1) بن صفوان بن بلال بن اصرم بن ایاس بن عبد غنم بن جحاش بن بجالہ بن مازن بن ثعلبہ بن سعد بن ذبیان شاعر ذبیانی ثم ثعلبی۔ دار قطنی نے مؤتلف میں لکھا ہے: یہ صحابی ہیں اور ہشام بن کلبی کا قول ہے کہ یہودانِ بنی قریظہ کے ساتھ تھے۔ پھر اسلام لائے اور حیی بن اخطب کا ان اشعار میں مرثیہ کہا: تیری زندگی کی قسم! ابن اخطب نے اپنے آپ کو ملامت نہیں کی۔ لیکن بات یہ ہے کہ جسے اللہ تعالیٰ رسوا کر دے رسوا ہو جاتا ہے۔ ایسے ہی اشعار ابن اسحاق نے مغازی میں ذکر کیے ہیں۔ فرماتے ہیں: کچھ لوگوں کا کہنا ہے کہ یہ اشعار خود حیی بن اخطب کے ہیں۔ ابو عبید قاسم بن سلام نے ذکر کیا: وہ فیطیون بن عامر بن ثعلبہ کی اولاد سے تھے۔ اور معجم الشعراء میں مرزبانی نے لکھا ہے: پہلے یہودی تھے پھر اسلام لائے۔(2) جب نبی صلی اللہ علیہ وسلم نے خیبر کو فتح کیا تو انہوں نے یہ اشعار کہے: مصیبت میں نبی صلی اللہ علیہ وسلم کی طرف سے ایک ڈھل پھینکا گیا جو مہروں اور عزت والی چمکدار ہے۔\n\nدیوان حسان بن ثابت جو ابو سعد عسکری کا بحوالہ ابن حبیب تیار کردہ ہے اس میں ہے کہ سیدنا حسان بن ثابت نے جبل بن جوال ثعلبی، جو پہلے یہودی تھے بعد میں اسلام لاکر ان اشعار کا جواب دیا:\n\n\"خبردار! اے بنی معاذ کے سعد! جو کچھ قریظہ اور نفیر نے کیا ہے، تم نے اپنی ہنڈیاں چھوڑ ہیں جن میں کچھ بھی نہ تھا اور قوم کی ہنڈیاں گرم کھول رہی تھیں۔\"\n\nسیدنا حسان نے فرمایا:\n\n\"وہ جماعت یاد کرے جسے ہمارے خلاف مدد دی گئی اب ان کے شہر میں کوئی مددگار نہیں ہے۔ ان لوگوں کو کتاب دی گئی جسے انہوں نے ضائع کر دیا۔ اب وہ تو رات سے اندھی اور ہلاک ہونے والی ہے۔ بنی لوئی کے سرداروں پر وہ آگ ہلکی رہی جو بویرہ میں چھا گئی تھی\"۔ (اشعار)\n\nمرزبانی نے مذکورہ اشعار جبل کے ذیل میں ذکر کیے اور ان میں یہ اضافہ کیا ہے:\n\n\"لیکن اموات کے ساتھ ہمیشہ رہنا نہیں ہوتا جو اچک لیتی اور قبر میں سمیٹ لیتی ہیں۔ گویا وہ عید کی بکریاں ہیں جو ذبح کی جاتی ہیں ان پر کوئی نکیر کرنے والا نہیں\"۔","",{"fn":"(1) اسد الغابۃ (۶۷۸) الاستيعاب (۳۶۵)\n(2) السیرۃ النبویہ (۱۹۰/۳) (۲۱۵/۳) الاکمال (۴۷/۲) اسد الغابۃ (۳۰۵/۱)"}],[1072,"§۱۰۷۲ ۔ (ز) جبلہ بن الازرق الحمصی(1)\nامام بخاری رحمہ اللہ نے اپنی تاریخ میں، ابن السکن اور طبرانی وغیرہ نے معاویہ بن صالح کی سند سے بحوالہ راشد بن سعد، جبلہ بن الازرق سے جنہیں شرف صحابیت حاصل ہے نقل کیا ہے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ایک دیوار کی طرف رخ کر کے نماز پڑھی جس میں بہت زیادہ پتھر لگے تھے، وہ نماز ظہر کی تھی یا عصر کی نماز سے فارغ ہو کر بیٹھے ہی تھے کہ ایک بچھو نے آپ کو ڈس لیا جس کی وجہ سے آپ بے ہوش ہو گئے۔ لوگوں نے جھاڑ پھونک کی تو آپ کو افاقہ ہو گیا۔ فرمایا: اللہ تعالیٰ نے مجھے شفا دے دی لیکن تمہاری جھاڑ پھونک سے نہیں (اپنی رحمت سے)۔(2) بغوی کہتے ہیں: مجھے اس کے علاوہ ان کی کوئی روایت معلوم نہیں۔ ابن السکن کہتے ہیں: ان کے علاوہ کوئی روایت نہیں ہے۔","",{"fn":"(1) اسد الغابۃ (۶۷۹) الاستيعاب (۳۲۲)\n(2) المعجم الکبیر (۲۸۷/۲) التاریخ الکبیر (۲۱۸/۱) تفسیر القرطبی (۴۶/۲) جمع الجوامع (۴۸۶۹) الطبقات الکبریٰ (۱۴۶/۷) کنز العمال (۲۸۳۵۸) (۲۸۵۲۳)"}],[1073,"§۱۰۷۳ ۔ جبلہ بن اشعر خزاعی(1)\nواقدی نے ذکر کیا کہ وہ فتح مکہ کے روز کرز بن جابر کے ساتھ قتل ہوئے۔ ابو عمر نے بھی ان کا ذکر کیا ہے۔ مشہور یہ ہے کہ کرز کے ساتھ قتل ہونے والے حیش بن خالد تھے، وہی حیش بن اشعر ہیں۔(2) جیسا کہ اپنے مقام پر آئے گا، اشعر ان کے زیادہ بالوں کی وجہ سے ان کا لقب بن گیا۔","",{"fn":"(1) اسد الغابۃ (۶۸۰) الاستيعاب (۳۲۵)\n(2) اسد الغابۃ (۳۰۵/۱)"}],[1074,"§۱۰۷۴ ۔ جبلہ بن ثعلبہ انصاری خزرجی بیاضی(1)\nمطین نے عبید اللہ بن ابی رافع تک اپنی سند سے ذکر کیا ہے کہ اہل بدر میں سے سیدنا علی رضی اللہ عنہ کے ساتھ جنگ صفین میں شریک ہونے والوں میں شامل تھے۔ طبرانی(2) اور ابو نعیم وغیرہ نے ان کا تذکرہ کیا ہے۔ ابن حبان(3) فرماتے ہیں، جبلہ بن ثعلبہ از بنی بیاضہ بدری صحابی ہیں۔ ابن الاثیر نے کہا: درست رحیلہ بن خالد بن ثعلبہ ہے، را گر گئی اور غلطی سے اپنے دادا کی طرف منسوب ہو گئے۔\n\nمیں کہتا ہوں: یہ احتمال ہے کہ وہ کوئی اور ہوں۔ ہاں یہ بات بجا ہے کہ بدر میں شریک ہونے والے رحیلہ ہیں اور اس کا کئی بار واسطہ پڑا ہے کہ عبید اللہ بن ابی رافع تک سند انتہائی کمزور ہے۔","",{"fn":"(1) اسد الغابۃ (۶۸۱)\n(2) المعجم الکبیر حدیث (۲۱۹۸/۲)\n(3) الثقات (۵۸/۳)"}],[1075,"§۱۰۷۵ ۔ جبلہ بن ثور حنفی\nبنی حنیفہ کے وفد میں تھے، ابو عبید نے ذکر کیا کہ وہ قاتلین مسیلمہ کذاب میں شریک تھے۔ ابن فتحون نے ان کا استدراک کیا ہے۔"],[1076,"§۱۰۷۶ ۔ جبلہ بن جنادہ(1)\nبن سوید بن عمرو بن عرفطہ بن ناقد بن تیم بن سعد بن کعب بن عمرو بن ربیعہ خزاعی ان کا تذکرہ ابن شاہین نے محمد بن ابراہیم سے بحوالہ محمد بن یزید اپنے رجال کے ذریعہ نقل کیا ہے۔ ابو موسیٰ و ابن فتحون نے ان کا استدراک کیا ہے ایسا ہی انہوں نے آئندہ والی شخصیت جبلہ بن سعید کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۸۲)"}],[1077,"§۱۰۷۷ ۔ جبلہ بن حارثہ(1)\nبن سراحیل، زید بن حارثہ کے بھائی اور اسامہ بن زید کے چچا۔ جو عمر میں سیدنا زید سے بڑے ہیں۔(2) امام ترمذی رحمہ اللہ اور ابو یعلیٰ نے اسماعیل بن ابی خالد کی سند سے بحوالہ ابو عمرو الشیبانی، جبلہ بن حارثہ رضی اللہ عنہ سے روایت کی ہے، فرمایا: میں نبی صلی اللہ علیہ وسلم کے پاس آکر عرض کرنے لگا: میرے بھائی کو میرے ساتھ بھیج دیجئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے سامنے ہے اگر وہ جانا چاہے تو میں اسے منع کرنے کا نہیں\"۔ اس پر سیدنا زید بولے: یا رسول اللہ صلی اللہ علیہ وسلم! میں آپ کے مقابلہ میں کسی کو پسند نہیں کر سکتا۔ سیدنا جبلہ فرماتے تھے: میں نے اپنے بھائی کی بات کو اپنی بات سے بہتر پایا۔ تاریخ بخاری(3) میں اسی سند سے شیبانی سے منقول ہے، فرمایا: میں نے جبلہ رضی اللہ عنہ سے سنا، ان کی ایک متصل روایت صحیح سند سے نسائی(4) میں ہے جو ابو اسحاق کی روایت سے بحوالہ فروہ، جبلہ بن حارثہ رضی اللہ عنہ سے نیند کے وقت پڑھنے کے بارے میں ہے۔ اس کے الفاظ یہ ہیں: \"میں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! مجھے کوئی چیز سکھائیے جس سے اللہ تعالیٰ مجھے فائدہ پہنچائے۔\" فرمایا: \"جب اپنے بستر پر سونے کے لئے آنے لگو تو ﴿قُلْ یٰۤاَیُّہَا الْکٰفِرُوْنَ﴾ (سورۃ الکافرون: ۱) پڑھ لیا کرو۔\"","",{"fn":"(1) اسد الغابۃ (۶۸۳) الاستيعاب (۳۲۰)\n(2) ترمذی کتاب المناقب باب مناقب زید بن حارثہ (۳۸۱۵)\n(3) التاریخ الکبیر (۲۱۷/۱)\n(4) نسائی عمل الیوم واللیلۃ (۸۰۰، ۸۰۲)"}],[1078,"§۱۰۷۸ ۔ جبلہ بن سعید(1)\nبن الاسود بن سلمہ بن حجر بن وہب بن ربیعہ بن معاویہ الاکرمین۔ ابن شاہین ابو موسیٰ اور ابن فتحون نے ان کا ذکر کیا ہے جیسا کہ پہلے جبلہ بن جنادہ میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۸۴)"}],[1079,"§۱۰۷۹ ۔ جبلہ بن شراحیل کلبی\nزید بن حارثہ کے چچا، ابن مندہ نے ایک احتمالی امر سے ان کا ذکر کیا ہے جس کی شرح فصل اخیر میں ان شاء اللہ تعالیٰ آئے گی۔"],[1080,"§۱۰۸۰ ۔ جبلہ بن عمرو(1)\nبن اوس بن عامر بن ثعلبہ بن وقش بن ثعلبہ بن طریف بن خزرج بن ساعدہ ساعدی انصاری۔ ابن السکن کہتے ہیں: وہ احد میں شریک ہوئے۔ یہ ابو مسعود کے بھائی کے علاوہ ہیں، کیونکہ نسبتوں میں اختلاف تھا۔(2)\n\nمیں کہتا ہوں: بات ویسی ہی ہے جیسی انہوں نے کہی۔ ابن شبہ نے اخبار مدینہ میں عبدالرحمن بن ازھر کی سند سے نقل کیا کہ لوگوں نے جب سیدنا عثمان رضی اللہ عنہ کو بقیع میں دفن کرنا چاہا تو جبلہ بن عمرو ساعدی نے دفنانے سے روک دیا چنانچہ وہ \"حش کوکب\" ان کی میت لے گئے، ان کے ساتھ معبد بن معمر بھی تھے، جہاں انہیں دفن کر دیا۔","",{"fn":"(1) الاستيعاب (۳۲۱)\n(2) الاستيعاب (۳۰۷/۱)"}],[1081,"§۱۰۸۱ ۔ جبلہ بن عمرو(1)\nبن ثعلبہ بن اسیرہ انصاری، ابو مسعود بدری کے بھائی طبرانی(2) نے مطین سے ان عبید اللہ بن ابی رافع تک کی سند سے ان کا ذکر صفین میں سیدنا علی رضی اللہ عنہ کے ساتھ شریک صحابہ کرام میں کیا ہے۔ اور ابن السکن نے ہارون ہمدانی کی سند سے بحوالہ ثابت بن عبید روایت کی ہے۔ فرمایا: میں ابو مسعود انصاری کے بھائی جبلہ بن عمرو کے پاس گیا، وہ تازہ کھجوریں توڑ رہے تھے۔ امام بخاری(3) نے اپنی تاریخ میں اور ابن السکن نے بکر بن احج کی سند سے بحوالہ سلیمان بن سیار نقل کیا کہ وہ لوگ مغرب میں ایک غزوہ میں معاویہ بن خدیج کے ساتھ تھے۔ انہوں نے لوگوں کے لیے انعام مقرر کیا۔ ان کے ساتھ اصحاب رسول صلی اللہ علیہ وسلم تھے جس کی سوائے جبلہ بن عمرو انصاری کے کسی نے تردید نہیں کی۔ ابن مندہ نے اسے خالد بن ابی عمران کی سند سے بحوالہ سلیمان بن سیار نقل کیا ہے۔ ان سے جنگ میں انعام رکھنے کے متعلق پوچھا گیا۔ فرمایا: میں نے معاویہ بن خدیج کے ساتھ کسی کو نہیں دیکھا وہ انعام رکھتے ہوں۔ ہمیں افریقہ کے غزوے میں خمس کے بعد ثلث (تہائی) زائد حصہ ملا۔ جبکہ ہمارے ساتھ کئی ایک انصار و مہاجرین صحابہ تھے ان میں جبلہ بن عمرو انصاری بھی تھے۔(4)","",{"fn":"(1) اسد الغابۃ (۶۸۶)\n(2) المعجم الکبیر (۲۱۹۷)\n(3) التاریخ الکبیر (۲۱۸/۱)\n(4) اسد الغابۃ (۳۰۷/۱)"}],[1082,"§۱۰۸۲ ۔ جبلہ بن ابی کریب(1)\nبن قیس بن حجر بن وہب بن ربیعہ بن معاویہ الاکرمین۔ بقول ابن سعد: نبی صلی اللہ علیہ وسلم کے پاس آئے۔(2) اور ڈھائی ہزار کے عطیہ میں تھے۔ ابن شاہین نے اپنے رجال سے ان کا ذکر کیا اور ابن فتحون و ابو موسیٰ نے ان کا استدراک کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۸۷)\n(2) اسد الغابۃ (۳۰۷/۱)"}],[1083,"§۱۰۸۳ ۔ جبلہ بن مالک(1)\nبن جبلہ بن صفارہ ابن دراع بن عدی بن المدار بن ہانی بن حبیب بن تمارہ بن نم نمی داری۔ دارین کے ہمراہ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ ابن شاہین نے اپنے رجال سے ان کا ذکر کیا اور ابو عمر نے ان کا مختصر حوالہ دیا ہے۔ ابن ابی حاتم(2) بحوالہ اپنے والد فرماتے ہیں: تبوک سے واپسی پر آپ صلی اللہ علیہ وسلم کے پاس آئے۔ مجھے ان کا پتہ نہیں۔ ابو موسیٰ نے ان کا استدراک کیا ہے۔ نعیم بن اوس کے سوانح میں بحوالہ واقدی ان کا تذکرہ آئے گا۔ ابو اسحاق بن الامین نے ابن عبد البر کی کتاب پر استدراک میں حرف حاء بے نقطہ میں ان کا تذکرہ کیا ہے جبکہ ان سے گزشتہ لوگوں نے حاء میں ان کا ذکر نہیں کیا۔","",{"fn":"(1) اسد الغابۃ (۶۸۸) الاستيعاب (۳۲۴)\n(2) الجرح والتعدیل (۵۱۰/۲)"}],[1084,"§۱۰۸۴ ۔ (ز) جبلہ (بے نسبت)(1)\nامام بخاری رحمہ اللہ فرماتے ہیں: صحابی ہیں، اور ابن سیرین نے ان سے مرسل روایت کی ہے۔ میرے خیال میں یہ پہلے والے شخص ہیں یعنی جبلہ بن عمرو انصاری۔ ابن السکن فرماتے ہیں، لوگوں کا کہنا ہے کہ وہ صحابی ہیں جبکہ نبی صلی اللہ علیہ وسلم سے ان کی کوئی روایت نہیں۔ بخاری میں تعلیقاً ہے ابن سیرین نے فرمایا: ان سے روایت لینے میں کوئی مضائقہ نہیں۔ ان کی مراد بیوی اور اس بیوی کے خاوند کی پہلی بیوی سے جو بیٹی ہوئی دونوں سے نکاح کرنے میں کوئی حرج نہیں۔ ابن السکن اور بغوی نے یہ روایت حماد کی سند سے بحوالہ ایوب، ابن سیرین سے موصول نقل کی ہے، فرمایا: انصار میں سے ایک صحابی رسول صلی اللہ علیہ وسلم مصر میں رہتے تھے جن کا نام جبلہ تھا۔ انہوں نے ایک خاتون اور اس کے پہلے خاوند کی پہلی بیوی سے جو بیٹی تھی دونوں سے نکاح کیا تھا۔(2) ایوب فرماتے ہیں: حسن اسے ناپسند سمجھتے تھے۔ ابن مندہ فرماتے ہیں: ایسا ہی عفان وغیرہ نے روایت کیا جبکہ سلیمان بن حرب نے اسے حماد سے نقل کیا تو کہا: \"جبار\" پہلا نام زیادہ صحیح ہے۔\n\nمیں کہتا ہوں: اسے ابن علیہ نے ایوب سے یوں ہی نقل کیا ہے اور ابن ابی شیبہ وغیرہ نے اپنی کتاب میں درج کیا ہے اور ایسا ہی عبد الوہاب ثقفی سے بحوالہ ایوب روایت کر کے کہا: مجھے بتایا گیا کہ سعد بن قرحاء ایک صحابی رسول صلی اللہ علیہ وسلم تھے۔ پھر اسی روایت کا مفہوم ذکر کیا۔","",{"fn":"(1) اسد الغابۃ (۶۸۹) الاستيعاب (۳۲۳)\n(2) اسد الغابۃ (۳۰۸/۱)"}],[1085,"§۱۰۸۵ ۔ حبیب (جیم دو باؤں سے تصغیر ہے)\nابن الحارث۔(1) ابن السکن نے ان کا ذکر کیا کہ ان کی حدیث کی سند صحیح نہیں۔ پھر وہ خود اور طبرانی نوح بن ذکوان کی سند سے بحوالہ ہشام وہ اپنے والد سے وہ سیدہ عائشہ رضی اللہ عنہا سے روایت کرتے ہیں، فرمایا: حبیب بن حارث نبی صلی اللہ علیہ وسلم سے آکر کہنے لگے: میں ایک گنہگار شخص ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ سے توبہ کی دعا مانگو\"۔ (حدیث)(2) ابن مندہ نے کہا: غریب ہے صرف اسی سند سے پہچانی جاتی ہے۔ طبرانی نے اوسط میں لکھا ہے، ہشام سے صرف اسی سند سے مروی ہے جس میں عیسیٰ بن ابراہیم، بحوالہ سعید بن عبد اللہ، نوح سے وہ اُن سے روایت کرنے میں متفرد ہے اور عبد الغنی بن سعید نے \"مؤتلف\" میں لکھا ہے کہ اسے ایوب بن ذکوان نے ہشام سے روایت کیا۔\n\nمیں کہتا ہوں: ایوب اور نوح دونوں ضعیف ہیں یہ بھی احتمال ہے کہ کسی راوی نے نوح کو ایوب بنا دیا ہو۔ شعب میں بیہقی نے اسے متنبہ کیا ہے کہ کسی نے اسے روایت کیا ہے تو فرمایا: جبیر بن حارث رائے ہے۔ فرماتے ہیں: یہ وہم ہے ابن شاہین نے اسے غلط لکھ دیا ہے اور خاء میں ان کا نام درج کیا ہے۔ ابو موسیٰ نے ان کا تعاقب کیا ہے۔ نیز حبیب کا تذکرہ ابو الغادیہ کے سوانح میں آئے گا۔","",{"fn":"(1) اسد الغابۃ (۶۹۱) الاستيعاب (۳۶۴)\n(2) سنن دارقطنی (۱۰۲/۳) السنن الکبریٰ (۲۷۱/۸) مجمع الزوائد (۲۰/۱۰) تفسیر ابن کثیر (۱۰۳/۳)"}],[1086,"§۱۰۸۶ ۔ جبیر بن ایاس(1)\nبن خلدہ بن مخلد بن عامر بن زریق انصاری خزرجی ابو الاسود نے بحوالہ عروہ اور موسیٰ بن عقبہ نے بحوالہ ابن شہاب۔ ابن اسحاق(2) اور ابو معشر وغیرہ نے شرکاء بدر میں ان کا ذکر کیا ہے۔ ابن مندہ فرماتے ہیں: ان کی کوئی روایت معروف نہیں۔ اور ابن قداح نے لکھا ہے: جبیر میں جیم پر زبر اور باء ساکن ہے۔","",{"fn":"(1) اسد الغابۃ (۶۹۲) الاستيعاب (۳۱۶)\n(2) السیرۃ النبویہ (۲۵۹/۲)"}],[1087,"§۱۰۸۷ ۔ جبیر بن بُحینہ(1)\nعبد اللہ کے بھائی۔ ابن مالک بن القشب ازدی بنی المطلب کے حلیف ابو الاسود نے بحوالہ عروہ یمامہ میں شہید ہونے والے صحابہ میں ان کا ذکر کیا ہے۔ طبرانی نے ان کا تذکرہ لکھتے ہوئے ان کے سوانح کے آغاز میں لکھا ہے: بجبیر بن مالک نوفلی، نوفلی میں انہیں وہم ہو گیا جبکہ وہ ازدی ہیں یا مطلبی۔","",{"fn":"(1) اسد الغابۃ (۶۹۳) الاستيعاب (۳۱۷)"}],[1088,"§۱۰۸۸ ۔ جبیر بن الحباب(1)\nبن المنذر انصاری۔ ابن حبان(2) فرماتے ہیں: کچھ لوگوں کا کہنا ہے کہ وہ صحابی ہیں، جس کی سند میں تامل ہے۔ البتہ مطین نے انہیں صحابہ میں ذکر کیا ہے۔ اور فرمایا کہ عبید اللہ بن ابی رافع کی سیر میں، سیدنا علی رضی اللہ عنہ کے ساتھ جنگ صفین میں شریک صحابہ میں ان کا نام لیا ہے۔ باوردی اور طبرانی(3) نے مطین ہی کے حوالہ سے اور ابن مندہ باوردی اور ابو نعیم نے طبرانی کے حوالہ سے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۹۴)\n(2) الثقات (۵۱/۳)\n(3) المعجم الکبیر (۱۶۱۲)"}],[1089,"§۱۰۸۹ ۔ جبیر بن حویرث(1)\nبن نقید بن بجیر بن عبد بن قصی بن کلاب قرشی۔ زبیر لکھتے ہیں: ان کے والد فتح مکہ میں قتل ہو گئے۔ بقول ابن سعد: نبی صلی اللہ علیہ وسلم کا دور پایا ہے اور آپ کی زیارت بھی کی ہے، لیکن ان سے کوئی روایت نہیں ملتی۔ البتہ ابو بکر صدیق اور دیگر صحابہ رضی اللہ عنہم سے روایت کی ہے۔ واقدی نے ابن المسیب سے بحوالہ جبیر بن حویرث روایت کی ہے، فرمایا: معرکہ یرموک میں میں شریک تھا، مجھے سوائے لوہے کی ٹن ٹن کے آدمیوں کی ایک بات بھی سنائی نہیں دے رہی تھی۔\n\nمیں کہتا ہوں: جو شخص یرموک میں جوان مرد ہو یقیناً فتح مکہ کے روز ممتاز و مشہور ہوگا۔ لہذا انہیں صحابہ میں شمار کرنے سے کوئی مانع نہیں۔ اگرچہ انہوں نے روایت نہیں کی۔ ابو عمر فرماتے ہیں: ان کے صحابی ہونے میں تامل ہے۔ جبکہ ابن حبان نے انہیں تابعین میں شمار کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۶۹۵) الاستيعاب (۳۱۹)"}],[1090,"§۱۰۹۰ ۔ جبیر بن حیہ(1)\nابن مسعود ثقفی، مغیرہ بن شعبہ رضی اللہ عنہ اور عروہ بن مسعود رضی اللہ عنہ کے بھتیجے۔\n\nمیں کہتا ہوں: صحیح بخاری میں ثابت ہے کہ وہ سیدنا عمر رضی اللہ عنہ کے دور میں فتوحات میں شریک رہے۔ اور امام بخاری رحمہ اللہ نے اس کے متعلق حدیث بھی روایت کی ہے جو زائدہ بن زیاد بن جبیر سے ان کے حوالہ سے ہے۔ میں نے کسی کو نہیں دیکھا کہ اس نے جبیر کو صحابہ میں ذکر کیا ہو۔ حالانکہ وہ ان کی شرط پر پورا اترتے ہیں۔ اس واسطے کہ نبی صلی اللہ علیہ وسلم کے عہد مبارک میں ثقیف کا جو شخص بھی باقی بچا وہ مسلمان ہو کر حجۃ الوداع میں شریک ہوا ہے۔ ابو موسیٰ نے انہیں صحابہ میں ذکر کیا اور ان کی ایک حدیث نقل کی جس کے متعلق مرسل ہونے کا گمان کیا ہے اور اس بات کو صحیح قرار دیا کہ وہ تابعی ہیں۔ لیکن میرے نزدیک ان کا صحابی ہونا اس لحاظ سے ثابت ہے کہ جو شخص عہد فاروقی کی فتوحات میں جوان سال ہو اور جس قصہ میں انہوں نے اپنی شرکت کا بتایا وہ نبی صلی اللہ علیہ وسلم کی وفات کے بعد دس سال سے کم کے عرصہ میں پیش آیا ہے تو کم از کم ان کے لئے دیدار نبوی تو ثابت ہوتا ہے۔ یہ مذکورہ شخص طائف میں رہتے تھے اور کاتبوں کے معلم تھے عراق آئے تو شاہی دیوان کے کاتب مقرر ہو گئے۔ بعد میں زیاد نے انہیں اصبہان کا والی بنا دیا۔ یوں عبد الملک کی حکومت میں ان کی عظمت بڑھ گئی۔","",{"fn":"(1) اسد الغابۃ (۶۹۶)"}],[1091,"§۱۰۹۱ ۔ جبیر بن مالک نوفلی\nابن بحینہ ہیں جن کا ذکر پہلے ہو چکا ہے۔"],[1092,"§۱۰۹۲ ۔ جُبَیر بن مُطعم(1)\nبن عدی بن نوفل بن عبد مناف قرشی نوفلی، ان کی والدہ ام حبیبہ بنت سعید اور بقول بعض ام جمیل بنت سعید بن عبد اللہ بن ابی قیس از بنی عامر بن لوی ہیں۔ وہ قریش کے اکابر اور علماء انساب میں سے تھے۔ بدر کے قیدیوں کا وفد نبی صلی اللہ علیہ وسلم کے پاس آیا تو یہ بھی اس میں شامل تھے۔ نبی صلی اللہ علیہ وسلم سے سورہ طور کی تلاوت سنی، فرماتے ہیں: یہ پہلا موقع تھا کہ ایمان نے میرے دل میں گھر کر لیا۔ یہ بات امام بخاری(2) نے صحیح میں روایت کی ہے اور نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: \"آج اگر تمہارے والد زندہ ہوتے اور مجھ سے ان قیدیوں کی رہائی کی بات کرتے تو میں یہ ان کے حوالہ کر دیتا\"۔ سیدنا جبیر حدیبیہ اور فتح مکہ کے درمیانی عرصہ میں اسلام لائے۔ بقول بعض فتح مکہ میں مسلمان ہوئے اور امیر معاویہ رضی اللہ عنہ کی خلافت میں فوت ہوئے۔ ابن اسحاق کے سامنے جب نعمان کا نسب لایا گیا تو آپ نے جبیر بن مطعم کو بلایا۔ جبکہ وہ قریش میں سے قریش اور سارے عرب کے سب سے زیادہ انساب کے عالم تھے، فرماتے ہیں: میں نے علم انساب ابو بکر الصدیق رضی اللہ عنہ سے حاصل کیا اور ابو بکر رضی اللہ عنہ سارے عرب کے انساب کے بڑے عالم تھے۔ صحابہ میں سے ان سے روایت کرنے والے سلیمان بن صرد اور عبد الرحمن بن ازہر ہیں۔ ابن المسیب ان سے روایت کرتے ہیں کہ وہ اور سیدنا عثمان رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے پاس آکر عرض کرنے لگے کہ جیسی تقسیم آپ نے بنی ہاشم و مطلب کے لیے کی ہے میرے لیے بھی کریں۔ اور ساتھ یہ بھی کہا: ہماری رشتہ داری صحیح ہے، یعنی ہاشم، مطلب اور نوفل جو جبیر کے دادا اور عبد شمس جو سیدنا عثمان رضی اللہ عنہ کے دادا تھے، آپس میں بھائی ہیں۔ آپ صلی اللہ علیہ وسلم نے انکار کر دیا اور فرمایا: \"بنی ہاشم اور بنی مطلب تو شیر و شکر ہیں\"۔(3) ان کی وفات ستاون، اٹھاون یا انسٹھ (۵۷/۵۸/۵۹) ھ میں ہوئی۔","",{"fn":"(1) اسد الغابۃ (۶۹۸) الاستيعاب (۳۱۵)\n(2) بخاری کتاب المغازی باب ۱۲ حدیث (۴۰۴۲)\n(3) بخاری کتاب المناقب باب مناقب قریش (۳۵۰۲) ابو داؤد کتاب الخراج باب فی بیان مواضع قسم الخمس وسہم ذی القربیٰ (۲۹۷۸) نسائی فی کتاب قسم الفی باب ۱ حدیث (۴۱۴۷، ۴۱۴۸) ابن ماجہ فی باب الجہاد باب قسمۃ الخمس (۲۸۸۱) السنن الکبریٰ (۳۴۰/۶) (۳۱/۷) تفسیر طبری (۱۰/۵) حلیۃ الاولیاء (۶۶/۹)"}],[1093,"§۱۰۹۳ ۔ جبیر بن نفیر کندی\nعسکری نے ان میں اور جبیر بن نفیر حضرمی میں فرق کیا ہے۔ تھوڑا قریب ہی جبر کندی میں تذکرہ گزر چکا ہے۔"],[1094,"§۱۰۹۴ ۔ جبیر بن نوفل(1)\nابن حبان فرماتے ہیں، بعض لوگ کہتے ہیں: یہ صحابی ہیں۔ اس کی سند میں لیث بن ابی سلیم ہے۔ اور مطین، باوردی اور ابن مندہ نے انہیں صحابہ میں ذکر کیا ہے۔ سب نے ابو بکر بن عیاش کی سند سے بحوالہ لیث بن ابی سلیم، زید بن ارطاۃ سے انہوں نے جبیر بن نوفل سے نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کوئی بندہ اس سے بڑھ کر اللہ تعالیٰ کا قرب کسی چیز سے حاصل نہ کر سکا بجز اس کے جو اس سے نکلی ہے یعنی قرآن مجید۔(2) ابن مندہ فرماتے ہیں: اسے بکر بن خنیس نے لیث سے بحوالہ زید انہوں نے ابو امامہ سے نقل کیا ہے۔ اور علاء بن حارث نے بحوالہ لیث زید سے انہوں نے جبیر بن نفیر سے مرسل روایت کیا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۷۰۱)\n(2) ترمذی کتاب فضائل القرآن باب ۱۷ حدیث (۲۹۱۱) مسند احمد (۲۶۸/۵) المعجم الکبیر (۱۶۱۴) مجمع الزوائد (۲۵۰/۲) کنز العمال (۲۳۶۶)"}],[1095,"§۱۰۹۵ ۔ جبیر مولیٰ کثیرہ بنت سفیان\nان کا تذکرہ سعید مولیٰ کثیرہ کے سوانح میں آئے گا۔"],[1096,"§۱۰۹۶ ۔ (ز) جبیر\nنبی کریم صلی اللہ علیہ وسلم نے اس نام سے جابر بن عبد اللہ رضی اللہ عنہ کو اس حدیث میں مخاطب فرمایا ہے جسے ابو عبد اللہ صدقہ والے ابو زبیر سے بحوالہ جابر رضی اللہ عنہ روایت کرتے ہیں۔ ابن ابی خیثمہ وغیرہ نے اسے نقل کیا ہے۔"],[1097,"§۱۰۹۷ ۔ جبیلہ بن عامر\nبن انیف بن ثعلبہ بن قنفذ بن حلاوہ بن سمیع بن بکر بن المجمع بلوی، انصار کے حلیف۔ ابن الامین نے استیعاب پر اپنے استدراک میں ان کا تذکرہ کیا ہے اور نسب بیان نہیں کیا۔ جبکہ انساب میں رشاطی نے نقل کیا ہے اور ابن کلبی سے نقل کیا کہ وہ نبی صلی اللہ علیہ وسلم کے معاہدوں والے اور غزوہ احزاب میں آپ کے جاسوس تھے۔ فرماتے ہیں: ابن عبد البر اور نہ ابن فتحون نے ان کا ذکر کیا ہے۔"],[1098,"§۱۰۹۸ ۔ جثامہ (شروع کے زبر اور ثا مشدد سے) ابن قیس(1)\nابن مندہ نے ان کا تذکرہ کیا ہے اور حبیب بن عبید الرحبی کی سند سے بحوالہ ابو بشر جثامہ بن قیس (جو صحابی رسول صلی اللہ علیہ وسلم ہیں) سے مرفوعاً نقل کیا ہے، فرمایا: \"جس نے اللہ تعالیٰ کی راہ میں ایک دن کا روزہ رکھا اللہ تعالیٰ اسے سو سال کی مسافت جہنم سے دور کر دے گا\"۔(2) اس کی سند میں غیر معروف راوی ہیں۔ صعب بن جثامہ بن قیس بن عبد اللہ بن لیثی اور ان کے والد کے سوانح میں اس کے علاوہ روایت آ رہی ہے۔","",{"fn":"(1) اسد الغابۃ (۷۰۲)\n(2) بخاری کتاب الجہاد باب فضل الصوم فی سبیل اللہ (۲۸۴۰) مسلم کتاب الصوم باب فضل الصیام فی سبیل اللہ (۲۷۰۴) ترمذی کتاب فضائل الجہاد باب ما جاء فی فضل الصوم (۱۶۲۳) نسائی کتاب الصیام باب ذکر الاختلاف علی سفیان فیہ (۲۲۵۳) السنن الکبریٰ (۲۹۱/۴) مجمع الزوائد (۱۶۰/۳) المعجم الکبیر الصغیر (۱۶۱/۱) التاریخ الکبیر (۲۳۴/۲) کنز العمال (۱۰۸۰۰) (۲۳۵۹۶)"}],[1099,"§۱۰۹۹ ۔ جثامہ بن مساحق(1)\nبن ریح بن قیس الکنانی، انہیں شرف صحابیت حاصل ہے۔ سیدنا عمر رضی اللہ عنہ نے انہیں \"ہرقل\" کی طرف بھیجا تھا۔ ابن مندہ نے عبد الخالق حمصی کی سند سے بحوالہ یحییٰ بن ایوب، کنانی سے جو ہرقل کی جانب سیدنا عمر رضی اللہ عنہ کے قاصد تھے۔ جنہیں جثامہ بن مساحق کہا جاتا تھا، فرمایا: ہرقل کی مجلس میں جب میں کرسی پر بیٹھا تو مجھے معلوم نہ تھا کہ اس چادر کے نیچے کیا ہے۔ بعد میں مجھے پتہ چلا کہ یہ سونے کی کرسی ہے۔ جو نہی میں نے اسے دیکھا میں اس سے اتر پڑا، جس پر \"ہرقل\" ہنسنے لگا۔ مجھ سے بولا: کیا اتر پڑے؟ میں نے کہا: \"رسول اللہ صلی اللہ علیہ وسلم (سونے کی) ایسی چیزوں سے منع فرماتے تھے\"۔","",{"fn":"(1) اسد الغابۃ (۷۰۳)"}],[1100,"§۱۱۰۰ ۔ (ز) جثجاث\nبقول بعض یہ ابو عقیل صاع والے (جنہوں نے رات بھر محنت سے دو صاع کمائے ایک صاع گھر والوں کے لیے اور ایک صاع اللہ کی راہ میں صدقہ کر دیا جس پر منافقوں نے طعنہ زنی کی اس وقت سے ان کا نام صاحب الصاع پڑ گیا) کا نام ہے۔ سہیلی نے یہ نام ابن عبد البر کی اقتداء میں حاء بے نقطی سے قلمبند کیا ہے۔ اور کچھ لوگوں کا کہنا ہے کہ ان کا نام کچھ اور ہے ان کے حالات کنیتوں میں آئیں گے۔"],[1101,"§۱۱۰۱ ۔ (ز) جثیلہ (جیم اور ثاء سے تصغیر) ابن عامر\nحاء بے نقطی میں آئے گا۔"],[1102,"§۱۱۰۲ ۔ جحدم بن فضالہ الجہنی(1)\nابن مندہ نے محمد بن عمرو بن عبد اللہ بن جحدم کی سند سے بحوالہ ان کے والد وہ اپنے والد وہ اپنے دادا جحدم سے روایت کرتے ہیں، وہ نبی صلی اللہ علیہ وسلم کے پاس آئے تھے آپ صلی اللہ علیہ وسلم نے ان کے سر پر ہاتھ پھیرا تھا، اور فرمایا تھا: \"اللہ تعالیٰ جحدم کو برکت دے\" اور ان کے لیے ایک تحریر بھی بنوائی۔(2) پھر لمبی حدیث ذکر کی۔ ابن مندہ فرماتے ہیں: اجنبی روایت ہے۔\n\nمیں کہتا ہوں: اس کی سند میں غیر معروف راوی ہیں۔ پھر وہ مروی بھی نضر بن مسلمہ بن شاذان سے ہے جو متروک راوی ہے۔","",{"fn":"(1) اسد الغابۃ (۷۰۶)\n(2) کنز العمال (۳۶۸۸۳) جامع المسانید (۶۴۹/۲)"}],[1103,"§۱۱۰۳ ۔ جحدم الخُمس (حاء بے نقطی کے پیش، میم کے سکون سے پھر سین ہے)\nمیں نے خطیب کے قلم سے مؤتلف میں ایسا ہی لکھا ہوا پڑھا ہے، اور انہوں نے محمد بن المسیب ارغیانی کی سند سے بحوالہ موسیٰ بن سہل رملی، محمد بن عمرو بن عبد اللہ بن فضالہ فرمایا: میں نے اپنے والد کو اپنے والد عبد اللہ سے وہ اپنے والد فضالہ سے وہ جحدم سے روایت کرتے سنا وہ نبی صلی اللہ علیہ وسلم کے پاس آئے، آپ صلی اللہ علیہ وسلم نے ان کے سر پر ہاتھ پھیر کر فرمایا: \"اللہ تعالیٰ جحدم کو برکت دے\"۔ اس میں یہ احتمال بھی ہے کہ وہ پہلے والے ہوں، اور پہلی شخصیت کے بارے میں جہنی کہنا غلطی سے لکھا گیا ہو اور قصہ کی دو سندیں ہوں۔"],[1104,"§۱۱۰۴ ۔ (ز) جعدم (بے نسبت)(1)\nعیسیٰ عنجار نے مغیرہ بصری سے بحوالہ ہیشم بن میمون، حکیم بن جحدم سے میرے خیال میں وہ اپنے والد سے جنہیں شرف صحابیت حاصل ہے۔ فرمایا: رسول اللہ صلی اللہ علیہ وسلم کا ارشاد ہے: \"جو اپنی بکری دوہ لے، اپنی قمیص پر پیوند لگا لے، اپنا جوتا گانٹھ لے، اپنے خادم کے ساتھ بیٹھ کر کھانا کھا لے، اور بازار اپنا سودا سلف لے آیا کرے تو ایسا شخص تکبر سے بری ہے\"۔(2) اس کی سند ضعیف ہے، ابن مندہ نے اسی سند سے نقل کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۰۵)\n(2) اتحاف السادۃ المتقین (۴۰۷/۸) جامع المسانید (۶۴۹/۲)"}],[1105,"§۱۱۰۵ ۔ (ز) جحدم الجذیمی\nاز بنی جذیمہ، جیم کے زیر ذال نقطے والی کا زیر، اموی نے بحوالہ ابن اسحاق ان کا مغازی میں ذکر کیا ہے کہ بنی جذیمہ کے جو لوگ اسلام لائے ان میں سے ہیں۔ اور واقدی نے ان لوگوں میں ذکر کیا ہے۔ بنی جذیمہ کے جن لوگوں کو خالد بن ولید رضی اللہ عنہ نے اس وجہ سے قتل کیا تھا کہ انہوں نے مسلمان ہوئے کہنے کی بجائے \"ہم بے دین ہوئے\" کہا تھا۔ قصہ مشہور ہے البتہ ان میں سے ان کا جحدم نام لینے میں متفرد ہے۔ ابن فتحون نے اپنے ذیل میں اس کا ذکر کیا ہے۔"],[1106,"§۱۱۰۶ ۔ جحدمہ (بے نسبت، نسب کا ذکر نہیں)\nانہیں صحابی ہونے اور روایت کرنے کا شرف حاصل ہے۔ یہ ابو حجاب کا ایاد سے بحوالہ ان کے قول ہے، ایسا ہی ذہبی(1) کی تجرید میں لکھا ہے۔ آخری قسم میں جحدمہ آئے گا جہاں اس قول کی وضاحت کی جائے گی۔ ان شاء اللہ تعالیٰ","",{"fn":"(1) التجرید (۲۷/۱)"}],[1107,"§۱۱۰۷ ۔ جحش الجہنی(1)\nاپنے ذیل میں ابن فتحون نے لکھا ہے: طبری نے ان کا صحابہ میں ذکر کیا ہے۔\n\nمیں کہتا ہوں: آخری قسم میں جحش الجہنی کا تذکرہ آئے گا کہ بعض راویوں نے ان کا نام غلط لکھ دیا۔ مجھے معلوم نہیں آیا وہ یہی ہیں یا کوئی اور؟","",{"fn":"(1) اسد الغابۃ (۷۰۷)"}],[1108,"§۱۱۰۸ ۔ (ز) جحش بن رئاب الاسدی\nابو احمد کے والد، انہی کے سوانح میں ان کا نسب آئے گا۔ بقول ابن حبان(1) انہیں شرف صحابیت حاصل ہے۔ بجابی نے ان لوگوں میں ان کا ذکر کیا ہے جو خود اور ان کے بیٹے نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں۔ دار قطنی نے ایک کمزور سند سے نقل کیا ہے کہ نبی صلی اللہ علیہ وسلم نے ان جحش کا نام تبدیل کیا تھا۔ پہلے ان کا نام برہ تھا آپ صلی اللہ علیہ وسلم نے جحش رکھا۔ (لیکن) مشہور یہ ہے کہ ان کی بیٹی کا نام برہ تھا آپ نے اس کا نام تبدیل کیا تھا۔","",{"fn":"(1) الثقات (۶۵/۳)"}],[1109,"§۱۱۰۹ ۔ جذار(1)\n(شروع کے حرف کے زیر اور دال کی تخفیف سے)\n\nبغوی اور ابن ابی عاصم وغیرہ نے عباس بن فضل بن عمرو انصاری کی سند سے بحوالہ قاسم بن عبد الرحمن انصاری، وہ زہری وہ یزید بن شجرہ وہ جذار سے روایت کرتے ہیں، فرمایا: ہم نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں جہاد کیا، جب ہمارا دشمن سے سامنا ہوا آپ نے کھڑے ہو کر حمد و ثنا بیان کی اس کے بعد ارشاد فرمایا: \"لوگو! صبح ہوتے ہی تم پر اللہ تعالیٰ کی نعمتیں کوئی سبز کوئی زرد اور کوئی سرخ ہونا شروع ہو گئیں اور گھروں میں جو ہیں وہ اس کے علاوہ ہیں\"۔(2) پھر لمبا خطبہ ذکر کیا۔\n\nابن مندہ لکھتے ہیں: اجنبی روایت ہے اسے یزید بن ابی زیاد نے مجاہد سے بحوالہ یزید بن شجرہ طویل ذکر کیا ہے لیکن \"جذار\" کا تذکرہ نہیں کیا۔ ایسا ہی یزید سے منصور نے روایت کیا لیکن موقوف۔\n\nمیں کہتا ہوں: مجاہد سے موقوف نقل کرنے میں اعمش نے ان کی متابعت کی ہے۔ عباس بے حد ضعیف راوی ہے۔ عباس دوری نے ابن معین سے بحوالہ یزید بن شجرہ کہا ہے کہ یہ صحابی ہیں۔ رہی جذار کی حدیث تو وہ صحیح نہیں، ہمیں معلوم نہیں کہ زہری نے یزید بن شجرہ سے کچھ روایت کیا ہو۔ حدیث منصور سے مروی ہے اور بغوی نے اسی مفہوم کی روایت کی ہے۔ البتہ اس میں اضافہ کیا ہے کہ زہری نے یزید سے نہیں سنا: ابن الجوزی بحوالہ نسائی فرماتے ہیں: یہ حدیث باطل ہے اور دار قطنی کا ارشاد ہے یہ روایت محفوظ نہیں۔ درست منصور اور اعمش کا قول ہے یہ بات انہوں نے \"علل\" میں لکھی ہے۔","",{"fn":"(1) اسد الغابۃ (۷۰۸)\n(2) المعجم الکبیر (۲۸۹/۲) مسند البزار (۱۷۱۴) مجمع الزوائد (۲۷۵/۵) الاحاد والمثانی (۱۱۴/۵)"}],[1110,"§۱۱۱۰ ۔ (ز) جُد جُد (دو پیش والی جیموں اور درمیان میں دال ساکن) الجندعی\nبیہقی نے دلائل میں عبد الرزاق کی روایت سے بحوالہ ایک شخص، سعید بن جبیر سے نقل کیا ہے کہ ایک شخص انصار سے آ کر کہنے لگا: مجھے رسول اللہ صلی اللہ علیہ وسلم نے بھیجا ہے اور فلاں عورت سے میرا نکاح کیا ہے۔ آپ کو اطلاع ملی تو آپ نے سیدنا علی اور مقداد رضی اللہ عنہما کو بھیجا: \"وہ تمہیں ملے تو اسے قتل کر دینا لیکن وہ تمہیں نہیں ملے گا\"۔ تو انہوں نے اسے دیکھا کہ کسی سانپ نے اسے ڈس لیا تھا۔(1) بیہقی فرماتے ہیں: اس شخص کا نام لیا گیا ہے جو عطاء بن سائب کی بحوالہ عبد اللہ بن حارث کی روایت میں جد جد ہے۔\n\nمیں کہتا ہوں: مندہ کے ہاں یحییٰ بن بسطام کی سند سے بحوالہ عمرو بن فرقد، عطاء بن سائب سے عبد اللہ بن حارث سے منقول ہے کہ جریج جندعی پھر وہ قصہ ذکر کیا۔ جسے جندع انصاری کے سوانح میں درج کیا ہے جو درست نہیں، اس بنا پر عطاء بن سائب سے آگے اس شخص کے نام میں اختلاف ہے۔","",{"fn":"(1) دلائل النبوۃ للبیہقی (۲۸۵/۶)"}],[1111,"§۱۱۱۱ ۔ جد بن قیس(1)\nبن قیس بن صحر بن خنساء ابن سنان بن عبید بن غنم بن کعب بن سلمہ انصاری ابو عبد اللہ۔ طبرانی(2) اور ابن مندہ نے معاویہ بن عمار دنی کی سند سے بحوالہ ان کے والد وہ ابو زبیر سے وہ جابر سے روایت کرتے ہیں، فرمایا: مجھے میرے ماموں جد بن قیس سوار کر کے لے گئے اور میں انصار کے ستر گھڑ سواروں میں پتھر بھی نہ پھینک سکتا تھا جو رسول اللہ صلی اللہ علیہ وسلم کے پاس وفد بنا کر گئے یعنی کم سن تھا۔ پھر بیعت عقبہ کی حدیث ذکر کی۔ اس کی سند قوی ہے۔ ابن مندہ فرماتے ہیں: اجنبی روایت ہے جو معاویہ بن عمار کی حدیث سے مروی ہے جسے محمد بن عمران بن ابی لیلیٰ نقل کرنے میں متفرد ہے۔ جد بن قیس بنی سلمہ کے سردار تھے جیسا کہ عمرو بن الجموح کے حالات میں آئے گا۔ یہ بھی کہا جاتا ہے کہ جد بن قیس منافق شخص تھا۔ ابو نعیم اور ابن مردویہ ضحاک کی سند سے بحوالہ ابن عباس رضی اللہ عنہما روایت کرتے ہیں کہ اس کے متعلق یہ ارشاد باری تعالیٰ نازل ہوا:\n\n\"ان میں سے بعض کہتے ہیں: مجھے اجازت دیجئے اور فتنہ میں نہ ڈالیے\"۔ (سورۃ التوبہ: ۴۹)\n\nاسے ابن مردویہ نے حدیث عائشہ رضی اللہ عنہا سے ضعیف سند سے بھی ذکر کیا ہے اور حدیث جابر سے ایسی سند سے روایت کیا ہے جس میں مبہم شخص ہے۔ سیدنا جابر رضی اللہ عنہ سے مروی ہے کہ جد حدیبیہ اور بیعت سے پیچھے رہ گیا تھا۔ اسے ابن عساکر نے اعمش کی سند سے بحوالہ ابو سفیان، ان سے روایت کیا ہے۔\n\nعبد الرزاق، معمر سے بحوالہ قتادہ اللہ تعالیٰ کے اس ارشاد:\n\n\"ان کا عمل رلا ملا ہے کچھ نیک اور کچھ بد بعید نہیں کہ اللہ تعالیٰ ان پر مہربانی فرمائے\"۔ (سورۃ التوبہ: ۱۰۲)\n\nکے متعلق فرماتے ہیں: ان لوگوں کے بارے میں نازل ہوا جو غزوہ تبوک سے رہ گئے تھے۔ ان میں ابو لبابہ اور جد بن قیس ہیں ان کی توبہ قبول نہیں ہوئی۔ ابو عمر ان کے سوانح کے آخر میں لکھتے ہیں: کچھ لوگوں کا کہنا ہے انہوں نے توبہ کی اور اچھے انداز سے تائب ہوئے۔ سیدنا عثمان رضی اللہ عنہ(3) کی خلافت میں فوت ہوئے۔","",{"fn":"(1) اسد الغابۃ (۷۰۹) الاستيعاب (۳۵۵)\n(2) المعجم الکبیر (۲۷۵/۲)\n(3) اسد الغابۃ (۳۱۴/۱) الاستيعاب (۳۳۱)"}],[1112,"§۱۱۱۲ ۔ جُدرہ (سین اور سکون سے)\nابن شبرہ العقبی۔(1) بقول ابن یونس: صحابی ہیں فتح مصر میں شریک ہوئے ایسا ہی عبد الغنی بن سعید نے ذکر کیا۔","",{"fn":"(1) اسد الغابۃ (۷۱۱)"}],[1113,"§۱۱۱۳ ۔ جُدیع بن نُذیر(1)\n(دونوں نام تصغیر سے ہیں)\n\nالمرادی ثم الکعبی از بنی کعب بن عوف جو مراد کا بطن ہے۔ نبی صلی اللہ علیہ وسلم کے خادم۔ ابن یونس نے تاریخ مصر میں ان کا تذکرہ کیا ہے کہ صحابی ہیں، نبی صلی اللہ علیہ وسلم کی خدمت کی لیکن مجھے ان کی روایت کا علم نہیں۔ ابو ظبیان عبد الرحمن بن مالک کے دادا ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۰)"}],[1114,"§۱۱۱۴ ۔ جُدّی (تصغیر ہے)\nابن مرہ بن سراقہ البلوی، بنی عمرو بن عوف جو انصار کی ایک شاخ ہے اس کے حلیف۔ ابن سعد(1) نے ان کا ذکر کیا کہ وہ اور ان کے والد خیبر میں شہید ہوئے۔","",{"fn":"(1) الطبقات الکبریٰ (۸۹/۴)"}],[1115,"§۱۱۱۵ ۔ جدیمہ بن عمرو العصری\nاز وفد عبد القیس، رشاطی نے انساب میں ان کا ذکر کیا ہے۔ فرمایا: جو لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس وفد کی صورت میں آئے ان میں جدیمہ بن عمرو، عمرو بن مرحوم اور ہمام بن ربیعہ شامل ہیں۔ ان چار حضرات کا تذکرہ ابو عبید نے بھی کیا ہے، جبکہ ابو عمر اور ابن فتحون نے ان کا ذکر نہیں کیا۔"],[1116,"§۱۱۱۶ ۔ الجذع الانصاری ثعلبہ بن زید"],[1117,"§۱۱۱۷ ۔ الجذع الانصاری(1)\nابن شاہین نے ان کا تذکرہ پہلے شخص سے جدا کیا ہے۔ شریک بن ابی نمر کی سند سے بحوالہ انصار کے ایک شخص جن کا نام ابن الجذع ہے اپنے والد سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میری امت کے اکثر لوگوں کو اس لیے مال نہیں دیا گیا کہ وہ حق کے منکر ہو جائیں اور ان سے بالکل مال چھینا نہیں گیا کہ وہ سوال کرنے لگ جائیں\"۔ ابو موسیٰ(2) لکھتے ہیں: میں نہیں جانتا یہ ثعلبہ بن زید ہیں یا کوئی اور؟\n\nمیں کہتا ہوں: ہاں! یہ دوسری شخصیت ہے۔ اس واسطے کہ ان کا بیٹا ثابت بن ثعلبہ طائف میں شہید ہوا، جن کا زمانہ شریک ابن ابی نمر نے نہیں پایا جس کی وضاحت ان سے مروی حدیث سے ہو گئی لہذا دونوں میں فرق ہو گیا۔","",{"fn":"(1) اسد الغابۃ (۷۱۲)\n(2) جامع المسانید (۶۵۳/۲)"}],[1118,"§۱۱۱۸ ۔ الجراح الاشجعی(1)\nطبرانی نے ان کے حالات تو لکھے ہیں لیکن ان کا نسب بیان نہیں کیا۔ انہیں ابو الجراح بھی کہا جاتا ہے۔ ان کی حدیث امام احمد اور ابو داؤد(2) نے عبد اللہ بن عقبہ بن مسعود کی سند سے روایت کی ہے، فرماتے ہیں: مجھے عبد اللہ بن مسعود نے ایک شخص کے بارے میں بتایا جس نے ایک عورت سے شادی کی پھر اس سے ہمبستر ہوا اور کچھ مقرر کیے بغیر ہی فوت ہو گیا۔ (حدیث) فرماتے ہیں: تو اشجع کا ایک شخص کھڑا ہو کر کہنے لگا اس کا فیصلہ ہمارے لیے نبی صلی اللہ علیہ وسلم نے بروع بنت واشق کے بارے میں کر دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس پر اپنے دو گواہ لاؤ\"۔ فرماتے ہیں: تو ابو سنان اور جراح جو اشجع کے دو آدمی تھے انہوں نے گواہی دی (اور آپ صلی اللہ علیہ وسلم نے اس کے لئے مہر مثل مقرر فرمایا)۔","",{"fn":"(1) اسد الغابۃ (۷۱۴) الاستيعاب (۳۵۷)\n(2) مسند احمد (۴۳۰/۱)"}],[1119,"§۱۱۱۹ ۔ جراد بن عبس(1)\nان کا شمار بصرہ کے دیہاتیوں میں ہوتا ہے۔ ابن مندہ نے عبد الرحمن بن عمرو بن جبلہ (جو متروک راوی ہے) کی سند سے بحوالہ قرہ بنت مزاحم روایت کی ہے۔ انہوں نے ام عیسیٰ بنت جراد سے سنا وہ اپنے والد جراد بن عبس یا ابن عیسیٰ کے حوالہ سے نقل کرتی ہیں۔ فرمایا: ہم نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! ہمارے کنویں ہیں وہ کیسے میٹھے ہوں گے؟ (حدیث)","",{"fn":"(1) اسد الغابۃ (۷۱۶)"}],[1120,"§۱۱۲۰ ۔ جراد العقیلی\nعبد اللہ کے پدر بزرگوار، ابن مندہ نے یعلیٰ بن اشدق سے (جو متروک راوی ہے) بحوالہ عبد اللہ بن جراد العقیلی وہ اپنے والد سے روایت کرتے ہیں، فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ایک سریہ روانہ فرمایا جس میں قبیلہ ازد اور اشعری لوگ تھے۔ وہ غنیمت لے کر صحیح سالم واپس آ گئے۔ (حدیث) ابو نعیم فرماتے ہیں: یہ روایت خود عبد اللہ بن جراد سے مشہور ہے۔\n\nمیں کہتا ہوں: ابن کلبی نے انساب میں جراد بن امتفق بن عامر بن عقیل کا ذکر کر کے فرمایا: نبی صلی اللہ علیہ وسلم کے پاس آئے بظاہر وہ یہی ہیں ابن الامین نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[1121,"§۱۱۲۱ ۔ (ز) جرثوم ابو ثعلبہ الخشنی\nان کا اس کے علاوہ کچھ اور بھی ذکر کیا گیا ہے جو کنیتوں میں آئے گا۔"],[1122,"§۱۱۲۲ ۔ (ز) جَرْجَرَہ الاسرائیلی\nحاء بے نقطی میں تذکرہ آئے گا۔"],[1123,"§۱۱۲۳ ۔ جرج\nابو نعیم نے اس میں جو ابن بشکوال اور ابو اسحاق بن الامین نے واقعہ بیان کیا ان کا ذکر کیا ہے اور ان کے حوالہ سے اسد بن وداعہ کی حدیث بیان کی کہ ایک جرج نامی شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر کہنے لگے: یا رسول اللہ! میری اہلیہ میری بات نہیں مانتی۔ (حدیث) لفظ جزء جیم کے زبر، زا کے سکون، آخر میں ہمزہ میں درست نام آئے گا۔"],[1124,"§۱۱۲۴ ۔ جرموز الہُجیمی(1)\nابو حاتم(2) فرماتے ہیں: جرموز قریعی بصری، صحابی ہیں۔ ابن قانع نے ان کا نسب یوں بیان کیا ہے: جرموز بن اوس بن عبد اللہ بن جریر بن عمرو بن انمار بن نجیم بن عمرو بن تمیم۔ بقول ابن السکن صحابی ہیں۔ بصریین میں ان کی حدیث ملتی ہے۔ امام بخاری نے اپنی تاریخ میں ابو عامر العقدی کی سند سے بحوالہ عبید اللہ بن ھوذہ قریعی، بنی نجیم کے ایک شخص سے وہ جرموز سے روایت کرتے ہیں۔ جبکہ امام احمد وغیرہ نے عبد الصمد بن عبد الوارث کی سند سے بحوالہ عبد اللہ بن ھوذہ، ایک شخص سے جس نے جرموز ہجیمی سے سنا فرماتے ہیں۔ میں نے عرض کیا: یا رسول اللہ! مجھے کوئی وصیت فرمائیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: میں تمہیں وصیت کرتا ہوں زیادہ لعن طعن نہ کرنا۔ اسے ابن السکن(3) نے مسلم بن قتیبہ کی سند سے بحوالہ عبید اللہ بن ھوذہ، میں نے انہیں بڑھاپے کی وجہ سے ان کی چارپائی پر انہیں دیکھا فرماتے ہیں: مجھ سے جرموز نے بیان کیا پھر وہ روایت ذکر کی۔ اس بنا پر ہو سکتا ہے کہ عبید اللہ نے ان سے یہ روایت کسی واسطے سے سنی ہو پھر براہ راست ان سے سنی ہو۔ پہلی روایت میں مبہم شخص جس کے متعلق بغوی اور ابن السکن نے یقین کیا ہے کہ وہ ابو تمیمہ ہجیمی ہے۔ ابن مندہ کہتے ہیں: اسی طرح ان سے ان کے بیٹے حارث بن جرموز بھی روایت کرتے ہیں، یہی قول ابن ابی حاتم(4) کا بحوالہ ان کے والد ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۸) الاستيعاب (۳۷۰)\n(2) الجرح والتعدیل (۶۲/۲)\n(3) مسند احمد (۷۰/۵) مجمع الزوائد (۷۱/۸) المعجم الکبیر (۲۸۳/۲، ۲۸۴) المستدرک (۴۹۸/۴) التاریخ الکبیر (۲۴۸/۲) الترغیب والترہیب (۴۷۰/۳)\n(4) الجرح والتعدیل (۶۲/۳)"}],[1125,"§۱۱۲۵ ۔ (ز) جُرہُم\nبقول بعض یہ ابو ثعلبہ کا نام ہے۔ یہ قول بغوی نے امام احمد کے حوالہ سے نقل کیا ہے۔ ایسے ہی رشاطی اور ابو عمر نے بھی ذکر کیا۔"],[1126,"§۱۱۲۶ ۔ جرو السدوسی(1)\n(راء ساکن پھر دال، بقول بعض ز پھر ہمزہ سے)\n\nابن مندہ نے محمد بن جابر کی سند سے بحوالہ حفص بن المبارک بنی سدوس کے جرو نامی شخص سے فرمایا: ہم لوگ نبی صلی اللہ علیہ وسلم کے پاس یمامہ کی کھجوریں لائے، آپ نے فرمایا: یہ کونسی قسم کی کھجوریں ہیں؟ (حدیث)(2) فرماتے ہیں: یہ اجنبی روایت ہے (لیکن) اس کا مخرج اچھا ہے۔\n\nمیں کہتا ہوں: محمد بن جابر یمامی ضعیف راوی ہے اسی حدیث کو ابو نعیم نے ابن مندہ کی سند سے نقل کیا ہے شاید انہیں اس کے علاوہ کوئی طریق نہیں ملا۔","",{"fn":"(1) اسد الغابۃ (۷۱۹)\n(2) مجمع الزوائد (۴۱/۵) کنز العمال (۳۸۳۲۶)"}],[1127,"§۱۱۲۷ ۔ جرو بن عمرو العذری(1)\nبقول بعض تصغیر سے اور بعض نے جزو، زاء اور ہمزہ سے اور بعض نے جزی، زاء کے زیر اور اس کے بعد یاء سے کہا ہے۔ میں نے استیعاب کے صحیح نسخہ میں جزاء بروزن خفاء لکھا دیکھا ہے۔ ابن مندہ نے ابو ثمامہ بن الضرین بن ربعی کی سند سے بحوالہ ان کے والد ربعی وہ اپنے والد قیصر سے روایت کرتے ہیں کہ جرو بن عمرو نے ان سے بیان کیا: وہ نبی صلی اللہ علیہ وسلم کے پاس آئے آپ صلی اللہ علیہ وسلم نے ان کے لیے ایک تحریر بنوائی کہ \"تم پر جمع ہونا اور عشر دینا واجب نہیں\"۔(2) یہ سند مجہول ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۰)\n(2) کنز العمال (۳۰۳۱۲)"}],[1128,"§۱۱۲۸ ۔ جزول بن مالک(1)\nبن مالک بن عمرو از بنی نجی بن عوف بن کلفہ بن عوف بن عمرو بن عوف اوسی انصاری، بقول بعض زاء اور ہمزہ سے۔ بعض نے کچھ اور کہا ہے۔ موسیٰ بن عقبہ نے بحوالہ ابن شہاب اور ابو الاسود نے بحوالہ عروہ شہدائے یمامہ میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۴)"}],[1129,"§۱۱۲۹ ۔ جرول بن الاحنف(1)\nبن سمح بن امری القیس بن عمرو بن معاویہ بن حارث الاکبر الکندی۔ بقول بعض یہ رجاء بن حیوہ کا نام ہے۔ جو احمد بن محمد بن الحجاج بن رشدین کا قول ہے۔ طبرانی(2) نے جاریہ بن مصعب کی سند سے بحوالہ رجاء بن حیوہ، بحوالہ اپنے والد، اپنے دادا جو صحابی رسول صلی اللہ علیہ وسلم تھے میں فرماتے ہیں: جنین کے قیدیوں میں سے ایک لڑکی آپ صلی اللہ علیہ وسلم کے پاس سے گزری، آپ صلی اللہ علیہ وسلم نے فرمایا: یہ کس کی ہے؟ (حدیث) ان کے دادا کا نام راوی نے نہیں لیا۔ اس بارے میں حافظ ابن عساکر نے دو اور قول نقل کیے ہیں، ایک جندل نون سے دوسرا دال کے بدلے زا سے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲)\n(2) المعجم الکبیر (۷۶۶/۲۲)"}],[1130,"§۱۱۳۰ ۔ جرول بن عباس(1)(2)\nبن عامر انصاری۔ ابو عمر فرماتے ہیں: ابن اسحاق اور خلیفہ نے شہدائے یمامہ میں ان کا تذکرہ کیا ہے۔\n\nمیں کہتا ہوں: ابن ماکولہ کی کتاب میں ہے: جرو (جیم کے پیش اس کے بعد را سے ہے) ابن عیاش (یا اور شین سے) از بنی مالک بن اوس یہ عطاردی کی، یونس بن بکیر سے بحوالہ ابن اسحاق روایت ہے اور ابراہیم بن سعد کی ان سے روایت میں جرو بن عباس ہے شروع کے زیر یا اور سین سے۔ موسیٰ بن عقبہ بن عقبہ کے ہاں جیم کے زیر، زا کے سکون اور اس کے بعد ہمزہ سے ہے۔ با اور سین پر اتفاق کیا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۷۲۳) الاستيعاب (۳۵۲)\n(2) الاکمال (۱۳۴/۱)"}],[1131,"§۱۱۳۱ ۔ جَزول(1)\nانہیں جرو بن مالک بن عمرو بن عوف بن مالک بن عوف بن عمرو بن عوف بن مالک بن اوس انصاری بھی کہا جاتا ہے۔ ابن کلبی نے ان کا ذکر کیا کہ بسر بن ابی ارطاۃ نے جب مدینہ پر سیدنا امیر معاویہ کی جانب سے چڑھائی کی خلافت کا آخری دور تھا تو مدینہ میں ان کا مکان گرا دیا۔(2) اس لیے کہ یہ ان لوگوں میں شامل تھے جنہوں نے سیدنا عثمان رضی اللہ عنہ کے خلاف باغیوں کو مدد دی تھی۔","",{"fn":"(1) اسد الغابۃ (۷۲۴)\n(2) اسد الغابۃ (۷۲۵) الاستيعاب (۳۶۳)"}],[1132,"§۱۱۳۲ ۔ جَرْھَد بن خویلد(1)\nبن حجرہ بن عبدیالیل بن زرعہ بن رزاح بن عدی بن سہم بن تمیم بن مازن بن حارث بن سلامان بن اسلم بن افعی اسلمی۔ اہل صفہ میں شامل تھے کنیت ابو عبد الرحمن تھی، لوگ کہتے ہیں: شریف انسان تھے، ان سے کئی احادیث مروی ہیں۔ ان کی مشہور حدیث ران (پردہ) ستر ہے۔ محدثین کا اس کی سند میں بہت زیادہ اختلاف ہے۔ ابن حبان نے اسے صحیح کہا ہے، فرماتے ہیں: ان کا شمار اہل بصرہ میں ہوتا ہے ان کے علاوہ دیگر علماء کا کہنا ہے: \"اہل مدینہ میں یہی صحیح ہے۔\n\nابن السکن نے ایاس بن سلمہ بن اکوع کی سند سے بحوالہ مسلم بن جرھد، چچا زاد سے وہ اپنے والد سے (جو حدیبیہ میں شریک تھے) روایت کرتے ہیں، پھر وہ حدیث ذکر کی۔ طبرانی(2) نے زرعہ بن عبد الرحمن بن جوہر کی سند سے بحوالہ ان کے والد ان کے دادا روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم ان کے پاس تشریف فرما ہوئے۔ وہ اصحاب صفہ سے تعلق رکھتے تھے۔ اور سفیان بن فروہ کی سند سے بحوالہ بنی جرہد کے کسی شخص سے وہ جرہد سے کہ انہوں نے بائیں ہاتھ سے کھایا تو نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: \"دائیں ہاتھ سے کھاؤ\"۔ انہوں نے عرض کیا: اس میں تکلیف ہے۔ چنانچہ آپ صلی اللہ علیہ وسلم نے اس پر پھونک ماری۔ پھر مرتے دم تک انہیں تکلیف نہیں ہوئی۔ واقدی فرماتے ہیں: مدینہ میں ان کا گھر تھا، اس میں یزید کی حکومت کے آخری ایام میں فوت ہوئے۔","",{"fn":"(1) المعجم الکبیر (۲۷۳/۲)\n(2) اسد الغابۃ (۷۲۷)"}],[1133,"§۱۱۳۳ ۔ جریج الاسرائیلی\nپہلے یہودی تھے پھر مسلمان ہوئے۔ ابو علی بن اشعث (جو ایک متروک و متہم بالکذب راوی ہے) کی کتاب السنن میں ان کا ذکر آتا ہے۔ چنانچہ وہ اپنی سند سے بحوالہ اہل بیت سیدنا علی رضی اللہ عنہ تک کی روایت کرتے ہیں کہ ایک جریج نامی یہودی تھا۔ پھر ان کے اسلام لانے کی حدیث ذکر کی۔ میں نے اس لفظ کو دوسری جگہ جریجرہ لکھا پایا ہے۔"],[1134,"§۱۱۳۴ ۔ جریج الجندعی\nجد جد میں تذکرہ ہو گیا ہے۔"],[1135,"§۱۱۳۵ ۔ جریر بن الارقط(1)\nفرماتے ہیں: میں نے حجتہ الوداع کے موقع پر نبی صلی اللہ علیہ وسلم کو دیکھا آپ سے سنا آپ فرما رہے تھے: ((اعطيت الشفاعة)) \"مجھے (قیامت کے روز خصوصی) شفاعت عطا کی گئی۔\" اسے ابن مندہ(2) نے یعلیٰ بن اشرق (جو متروک راوی ہے) کی سند سے روایت کیا ہے۔","",{"fn":"(1) بخاری کتاب التیمم باب حدیث (۳۳۵) مسلم کتاب المساجد باب المساجد ومواضع الصلاۃ (۱۱۶۳) نسائی کتاب الغسل باب التیمم بالصعید (۴۳۰) السنن الکبریٰ (۴۳۳/۲) مسند احمد (۳۰۱/۱) المعجم الکبیر (۱۱۰۴۷/۱۱) (۱۳۵۲۲/۱۲)\n(2) السنة لابن ابی عاصم (۳۷۳/۲)"}],[1136,"§۱۱۳۶ ۔ جریر بن اوس(1)\nبن حارثہ طائی۔ خریم کے بھائی۔ ابو عمر فرماتے ہیں: دونوں بھائی ایک ساتھ نبی صلی اللہ علیہ وسلم کے پاس آئے۔ یہ وہی جریر ہیں جن سے امیر معاویہ بن ابی سفیان نے کہا تھا: تمہارا سردار کون ہے؟ انہوں نے کہا: جو ہمارے سائل کو عطا کرے اور جاہل کو معاف کر دے۔ تو سیدنا معاویہ نے فرمایا: \"جزیر! تم نے بہت بہتر کہا\"۔(2)","",{"fn":"(1) اسد الغابۃ (۷۲۸) الاستيعاب (۳۲۷)\n(2) اسد الغابۃ (۳۱۹/۱) الاستيعاب (۳۱۱/۱)"}],[1137,"§۱۱۳۷ ۔ جریر بن عبد اللہ(1)\nبن جابر بن مالک بن نضر بن ثعلبہ بن جشم بن عوف بن خزیمہ بن حرب بن علی البجلی مشہور صحابی ہیں۔ کنیت ابو عمرو اور بقول بعض ابو عبد اللہ تھی۔ وہ کس وقت مسلمان ہوئے اس میں اختلاف ہے۔ چنانچہ طبرانی(2) کی الاوسط میں حصین بن عمر الا مسی کی سند سے بحوالہ اسمعیل بن ابی خالد، قیس بن ابی حازم، جریر رضی اللہ عنہ سے روایت ہے، فرمایا: جب نبی صلی اللہ علیہ وسلم مبعوث ہوئے میں آپ کے پاس آیا، آپ نے فرمایا: \"تم کس وجہ سے آئے؟\" میں نے عرض کیا: مسلمان ہونے، آپ نے اپنی چادر میری طرف پھیلا کر فرمایا: \"جب تمہارے پاس کسی قوم کا معزز شخص آئے تو اس کی عزت کرو\"۔ اس سند میں حصین ضعیف راوی ہے۔ اگر صحیح ثابت ہو جائے تو اسے مجاز پر محمول کیا جائے گا۔ یعنی جب ہمیں نبی صلی اللہ علیہ وسلم کی بعثت کی خبر ملی، یا محذوف (کچھ عبارت پوشیدہ) پر محمول کیا جائے گا۔ یعنی جب آپ صلی اللہ علیہ وسلم مبعوث ہوئے اور آپ نے اللہ تعالیٰ کی طرف بلایا اور آپ مدینہ تشریف لا چکے اس کے بعد قریش وغیرہ سے جنگ کی، فتح مکہ ہوئی اور آپ کے پاس کئی وفود آئے۔ ابن حزم نے ان کی اس روایت پر بھروسا کیا کہ وہ نبی صلی اللہ علیہ وسلم کی وفات سے چالیس روز قبل مسلمان ہوئے، جو غلط ہے۔ صحیحین میں ان سے بحوالہ نبی صلی اللہ علیہ وسلم مروی ہے، آپ نے ان سے فرمایا: \"حجۃ الوداع میں لوگوں کو خاموش رہنے کا کہو\"۔ اور واقدی نے اس پر بھروسا کیا ہے کہ وہ دس ھ کے رمضان میں نبی صلی اللہ علیہ وسلم کے پاس آئے۔(3) اور ذی الخلصہ کی طرف ان کی روانگی اس کے بعد ہوئی۔ اور انہوں نے نبی صلی اللہ علیہ وسلم کے ساتھ پورا حجتہ الوداع اسی سال گزارا۔ لیکن میرے نزدیک اس میں تامل ہے اس واسطے کہ شریک نے شیبانی سے انہوں نے شعبی سے بحوالہ جریر رضی اللہ عنہ نقل کرتے ہیں کہ سیدنا جریر نے فرمایا، ہمیں رسول اللہ صلی اللہ علیہ وسلم نے بتایا: \"تمہارا نجاشی بھائی فوت ہو گیا۔\" (حدیث) اسے طبرانی(4) نے نقل کیا۔ جس سے معلوم ہوتا ہے کہ جریر رضی اللہ عنہ کے اسلام لانے کا زمانہ دس ھ سے پہلے کا ہے۔ اس واسطے کہ نجاشی کی وفات اس سے پہلے ہوئی ہے۔ سیدنا جریر خوبصورت ورع شخص تھے۔ سیدنا عمر رضی اللہ عنہ فرماتے: یہ اس امت کا یوسف ہے۔ عراقی جنگوں میں سیدنا عمر رضی اللہ عنہ نے تمام بجیلہ لوگوں سے انہیں پیش پیش رکھا۔ ان لوگوں کا فتح قادسیہ میں نمایاں اثر ہے۔ اس کے بعد سیدنا جریر کوفہ رہنے لگے۔ سیدنا علی رضی اللہ عنہ نے انہیں قاصد بنا کر امیر معاویہ رضی اللہ عنہ کے پاس بھیجا۔ اس کے بعد یہ دونوں فریق سے جدا ہو کر قرقیسا میں ہی سکون پذیر رہے یہاں تک کہ ۵۱ ھ اور بقول بعض ۵۴ ھ میں فوت ہو گئے۔ صحیح روایت میں ہے کہ آپ(5) صلی اللہ علیہ وسلم نے انہیں ذی الخلصہ بھیجا جسے یہ منہدم کر آئے۔ اسی روایت میں ان سے مروی ہے، فرمایا: جب سے میں مسلمان ہوا آپ صلی اللہ علیہ وسلم نے کبھی مجھے اپنے پاس آنے سے نہیں روکا۔ اور جب مجھے دیکھتے تبسم ومسکان فرماتے۔ بغوی نے قیس کے طریق سے بحوالہ جریر رضی اللہ عنہ نقل کیا، فرمایا: سیدنا عمر رضی اللہ عنہ نے مجھے (لنگوٹ میں) کپڑوں کے بغیر دیکھ کر فرمایا: میرے خیال میں حضرت یوسف علیہ السلام کے متعلق جو کچھ ذکر کیا جاتا ہے اس طرح کی صورت صرف اس نوجوان کو ملی ہے۔ ابراہیم بن اسمعیل کھیلی کی سند سے مروی ہے کہ سیدنا جریر کا قد چھ ہاتھ لمبا تھا۔ اور طبرانی(6) نے سیدنا علی رضی اللہ عنہ کی موضوع حدیث نقل کی ہے: \"جریر ہم اہل بیت سے ہے۔\" صحابہ نبی صلی اللہ علیہ وسلم میں سے ان سے سیدنا انس بن مالک رضی اللہ عنہ روایت کرتے ہیں۔ فرماتے ہیں: جریر میری خدمت کرتے حالانکہ وہ عمر میں مجھ سے بڑے تھے (محض اس وجہ سے کہ سیدنا انس رسول اللہ صلی اللہ علیہ وسلم کے خادم تھے)۔ اسے بیہقی نے نقل کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۳۰) الاستيعاب (۳۲۶)\n(2) المعجم الکبیر (۲۲۶۶)\n(3) بخاری کتاب العلم باب الانصات للعلماء (۱۲۱) مسلم کتاب الایمان باب بیان معنی قول النبی صلی اللہ علیہ وسلم لا ترجعوا... (۲۲۰)\n(4) المعجم الاوسط (۵۹۸۳، ۸۵۲۵)\n(5) بخاری کتاب الجہاد والسیر باب من لا یثبت علی الخیل (۳۰۳۵)\n(6) مسلم کتاب فضائل الصحابۃ باب من فضائل جریر ابن عبد اللہ رضی اللہ عنہ (۶۳۱۴)"}],[1138,"§۱۱۳۸ ۔ جریر بن عبد اللہ الحمیری(1)\nابن عساکر فرماتے ہیں: صحابی ہیں۔ پھر سیف بن عمر سے فتوح میں بحوالہ محمد، ابو عثمان سے روایت کرتے ہیں کہ سیدنا خالد بن ولید رضی اللہ عنہ نے جب یمامہ سے عراق جانے کا عزم کیا تو لشکر کو نئے سرے سے ترتیب دی، پہلے صحابہ کو طلب کیا پھر ان میں سے زرہ پوشوں کو تلاش کیا اور فرمایا: \"قضاعہ قبیلہ پر یمن کی طرف جریر بن عبد اللہ حمیری، اقرع بن عبد اللہ کے بھائی قاصد رسول اللہ صلی اللہ علیہ وسلم ہو گئے۔ اور وہ قصہ ذکر کیا۔ اسی طرح سیف(2) ذکر کرتے ہیں کہ یہی جریر بن عبد اللہ جنگ یرموک میں مدینہ جانے کے قاصد تھے۔ سیف نے مختلف مقامات پر ان کا ذکر کیا ہے۔ ابن فتحون نے اپنے استدراک اور ابن الاثیر نے تجرید میں ان کا ذکر کیا ہے۔ بقول بعض: جریر بن عبد الحمید سے۔\n\nمیں کہتا ہوں: میرے خیال میں یہ لفظی غلطی ہے۔","",{"fn":"(1) المعجم الکبیر (۲۹۱/۲، ۲۹۲)\n(2) اسد الغابۃ (۷۲۹)"}],[1139,"§۱۱۳۹ ۔ جریر بن معدان الکندی(1)\nفشیش میں تذکرہ آئے گا۔","",{"fn":"(1) اسد الغابۃ (۷۳۲)"}],[1140,"§۱۱۴۰ ۔ جری الحنفی(1)\n(جیم کے بعد را تصغیر ہے)\n\nابن مندہ سلام طویل کی سند سے بحوالہ اسمعیل بن رافع، حکیم بن سلمہ وہ بنی حنیفہ کے جری نامی شخص سے روایت کرتے ہیں کہ ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آکر کہنے لگا، یا رسول اللہ! اکثر اوقات جب میں نماز میں ہوتا ہوں تو میرا ہاتھ میری شرمگاہ پر جا لگتا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنی نماز جاری رکھا کرو\"۔(2) فرماتے ہیں: اجنبی روایت ہے۔ میں کہتا ہوں: سلام اور اسی طرح اسمعیل دونوں ضعیف ہیں۔","",{"fn":"(1) اسد الغابۃ (۳۱۹/۱)\n(2) کنز العمال (۲۷۱۷۹) جامع المسانید والسنن (۷۷/۳)"}],[1141,"§۱۱۴۱ ۔ (ز) جری بن عمرو العُذری\nجرو میں تذکرہ ہو چکا ہے۔"],[1142,"§۱۱۴۲ ۔ (ز) جرتی (بے نسبت)\nبعد والے میں ذکر آئے گا۔"],[1143,"§۱۱۴۳ ۔ جزء بن انس السلمی(1)\nابن ابی عاصم نے ان کا ذکر کیا تھا اور نائل بن مطرف بن عبد الرحمن بن زین بن انس کی سند سے نقل کیا ہے، فرماتے ہیں:(2) میں نے اپنے والد اور دادا کے پاس نبی صلی اللہ علیہ وسلم کا تحریر کروایا ہوا ایک نوشتہ دیکھا جو آپ نے رزین بن انس کے لیے لکھوایا، وہ ان کے دادا کے چا ہیں۔ ابو موسیٰ کہتے ہیں: رزین کے لیے جو تحریر تھی اس میں جزء کا ذکر نہیں۔\n\nمیں کہتا ہوں: ابو محمد بن حزم نے عبد الکریم بن امیہ کے طریق سے نقل کیا ہے کہ جزء بن انس نے رسول اللہ صلی اللہ علیہ وسلم سے خرگوش کے بارے میں پوچھا، آپ نے فرمایا: تم اسے نہیں کھاتے۔ (حدیث) ابو عمر کہتے ہیں: جری (جیم اور را سے) بے نسبت ہیں۔ انہوں نے نبی صلی اللہ علیہ وسلم سے گوہ، لومڑی اور حشرات الارض کے بارے میں پوچھا، اس کی سند قوی نہیں سارا دار و مدار عبد الکریم بن امیہ پر ہے۔ اسی طرح انہوں نے جوی (جیم کے زبر، زا کے زیر اور اس کے بعد یاء) میں اس کا ذکر کیا ہے۔ میرے خیال میں یہ وہی ہیں جن کا ابن حزم نے ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۳۵)\n(2) الاحاد والمثانی (۱۰۷/۳)"}],[1144,"§۱۱۴۴ ۔ جزء بن الحَدْرَجان(1)\nبن مالک الیمانی۔ ابن مندہ نے ہاشم بن محمد بن ہاشم بن جزء بن عبد الرحمن بن جزء بن الحدرجان بن مالک کی سند سے بحوالہ ان کے والد ان کے دادا وہ اپنے والد عبد الرحمن سے روایت کرتے ہیں، فرمایا: مجھ سے میرے والد جزء بن الحدرجان نے (جو صحابی رسول صلی اللہ علیہ وسلم ہیں) بیان کیا کہ میرے بھائی قداد بن الحدرجان نبی صلی اللہ علیہ وسلم کے پاس اپنے ایمان اور اپنے گھرانے کے لوگوں کے ایمان کی یمن سے اطلاع دینے گئے یہ چھ سو گھر تھے جنہوں نے صدر جان کی بات مانی اور حضور محمد صلی اللہ علیہ وسلم پر ایمان لائے۔ راستے میں انہیں نبی صلی اللہ علیہ وسلم کا لشکر ملا، قداد نے ان سے کہا: میں مومن ہوں۔ انہوں نے اس کی بات نہ مانی اور اسے قتل کر دیا، مجھے اطلاع ملی تو میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں چل نکلا جس پر یہ آیت:\n\n\"اے ایمان والو! جب اللہ تعالیٰ کی راہ میں سفر کرو تو اچھی طرح چھان بین کر لیا کرو\"۔ (سورۃ النساء: ۹۴) تو نبی صلی اللہ علیہ وسلم نے مجھے میرے بھائی کی دیت سو سرخ اونٹنیاں دیں۔ اسی دوران میں بنی طے سے جنگ کی جہاں سے مجھے بہت سی غنیمتیں اور چالیس قیدی عورتیں ہاتھ لگیں اور انہیں مدینہ لے آیا، جن سے نبی صلی اللہ علیہ وسلم نے اپنے صحابہ کی شادیاں کرا دیں۔(2) یہ سند مجہول ہے ابن ماکولا کے ہاں لکھا ہے: جزء بن الحدرجان صحابی ہیں ایسا ہی ابن الامین نے اپنے استدراک میں ان کا تذکرہ کیا ہے، شاید وہ یہی ہوں جن کے والد کے نام میں اختلاف ہو گیا ہو۔ جمہرہ ابن کلبی میں ازد کے نسب میں لکھا ہے: عبد الملک بن جزء بن الحدرجان شام میں شریف النسب تھے، حجاج کے زمانہ میں والی بنے۔","",{"fn":"(1) اسد الغابۃ (۷۳۶)\n(2) جامع المسانید والسنن (۷۹/۳، ۸۰)"}],[1145,"§۱۱۴۵ ۔ (ز) جزء بن سہیل السلمی\nان کا ذکر اس حدیث میں آتا ہے جسے حافظ ابن عساکر نے اپنی تاریخ میں روایت کیا ہے اور ثابت بن قاسم نے \"دلائل\" میں نضر بن علقمہ کی سند سے بحوالہ جبیر بن نفیر، عبد اللہ بن حوالہ سے روایت کی ہے، فرمایا: ہم لوگ نبی صلی اللہ علیہ وسلم کے پاس تھے آپ نے فرمایا: \"خوشخبری پاؤ\"۔ پھر ایک قصہ ذکر کیا، اس میں ہے میں نے عرض کیا: شام کون جا سکتا ہے؟ وہاں تو بالوں والے رومی ہیں؟ آپ نے فرمایا: اللہ کی قسم! اللہ تعالیٰ ضرور تمہیں اس میں خلافت عطا فرمائے گا یہاں تک کہ ان میں کی سفید چہروں والی جماعت تم میں سے کالے شخص کی حکم بجا آوری کے لیے کھڑی ہو گی وہ انہیں جو حکم دے گا وہ کر گزریں گے\"۔(1) فرماتے ہیں: میں نے عبد الرحمن بن جبیر بن نفیر کو فرماتے سنا: تو اصحاب رسول اللہ صلی اللہ علیہ وسلم نے مذکورہ علامت جزء بن سہیل سلمی میں پہچان لی وہ عجمیوں کے والی بنے، جبکہ وہ رنگ کے سیاہ اور چھوٹے قد کے تھے۔ یہ لوگ ان عجمیوں کو ان کے ارد گرد کھڑے دیکھتے، جس کام کا انہیں حکم دیتے وہ کرنے لگ جاتے تو اس حدیث کی وجہ سے انہیں تعجب ہوا۔","",{"fn":"(1) اسد الغابۃ (۷۴۳) الاستيعاب (۳۶۹)"}],[1146,"§۱۱۴۶ ۔ جزء السدوسی\nسب کا ذکر جرو اور جرول میں گزر چکا ہے۔"],[1147,"§۱۱۴۷ ۔ جزء العذری\nسب کا ذکر جرو اور جرول میں گزر چکا ہے۔"],[1148,"§۱۱۴۸ ۔ جزء بن عباس\nسب کا ذکر جرو اور جرول میں گزر چکا ہے۔"],[1149,"§۱۱۴۹ ۔ جزء بن مالک از بنی جرجبی\nسب کا ذکر جرو اور جرول میں گزر چکا ہے۔"],[1150,"§۱۱۵۰ ۔ جزء بن مُعاویہ(1)\nبن حصین ابن عبادہ بن النزال بن مرہ بن عبید بن مقاعس بن عمرو بن کعب بن سعد بن زید مناۃ بن تمیم تمیمی سعدی، احنف بن قیس کے چا۔ ابو عمر فرماتے ہیں وہ اہواز پر سیدنا عمر رضی اللہ عنہ کی طرف سے گورنر تھے۔ بقول بعض: صحابی ہیں۔(2) لیکن یہ قول صحیح نہیں۔ یہ بات کئی بار گزر چکی ہے کہ اُس دور میں صرف صحابہ ہی امیر بنائے جاتے تھے۔ جزء اتنا عرصہ زندہ رہے کہ زیاد کے کسی عہدے پر فائز ہوئے۔ یہ بات بلاذری نے انساب الاشراف میں ذکر کی ہے۔","",{"fn":"(1) اسد الغابۃ (۳۲۳/۱) الاستيعاب (۳۳۸/۱)\n(2) مشکل الآثار (۳۶/۲)"}],[1151,"§۱۱۵۱ ۔ (ز) جزء(1)\n(بے نسبت)\n\nبقول ابن مندہ: اہل شام میں شمار ہوتے ہیں۔ طبرانی(2) نے معاویہ بن صالح کی سند سے بحوالہ اسد بن وداعہ روایت کیا ہے کہ ان سے جزء نامی شخص نے بیان کیا کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آئے، عرض کیا: یا رسول اللہ! میری اہلیہ میری نافرمانی کرتی ہے، میں اسے کیسے سرزنش کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تین بار عفو و معافی سے کام لو اس کے بعد اگر سزا دینا بھی چاہو تو بقدر گناہ دو، دیکھنا چہرے پر مارنے سے بچنا\"۔ ابو مسعود رازی نے اسی سند سے روایت کیا ہے۔ فرمایا: اسد بن وداعہ سے بحوالہ جزء نامی شخص جو نبی صلی اللہ علیہ وسلم کے پاس آئے۔ پھر وہ روایت ذکر کی۔ جبکہ ابن بشکوال اور ابن الامین نے ابو نعیم کی طرف یہ قول منسوب کر کے بحوالہ طبرانی مذکورہ سند سے ان کا ذکر بجرج (جیم کے پیش را کے سکون اور اس کے بعد جیم سے) نامی لوگوں میں کیا ہے۔ راجح وہی ہے جو پہلے گزر چکا ہے۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۷۴۰)\n(2) المعجم الکبیر (۲۱۳۰/۲)"}],[1152,"§۱۱۵۲ ۔ جزی(1)\nابو خنزیر سلمی، اسلمی بھی کہا جاتا ہے۔ ابن السکن نے بیچی بن محمد الجاری کی سند سے بحوالہ حصین بن عبد الرحمن (جن کا تعلق اہل دفینہ سے ہے) حبان بن جزی وہ اپنے والد سے روایت کرتے ہیں کہ وہ نبی صلی اللہ علیہ وسلم کے پاس قاصد بن کر آئے آپ نے انہیں پہنے کو دو کپڑے دیئے۔ اور طبرانی(2) نے اسی سند سے ان الفاظ میں یہ روایت کی ہے کہ نبی صلی اللہ علیہ وسلم کے پاس ایک قیدی لایا گیا نبی صلی اللہ علیہ وسلم کے پاس آپ کے صحابہ تھے۔ جنہوں نے اسے حالت شرک میں گرفتار کیا تھا۔ پھر مسلمان ہوئے تو جزء بھی اسلام لے آیا۔ آپ نے فرمایا: \"عائشہ کے پاس جاؤ وہ تمہیں دو چادریں دے گی۔\" ابن مندہ نے اسے حدیث جزء سے یوں ذکر کیا ہے کہ جزء کو دو چادریں پہنے کو دیں اور وہ اسلام لا چکے تھے۔","",{"fn":"(1) اسد الغابۃ (۷۴۲) الاستيعاب (۳۶۸)\n(2) المعجم الکبیر (۲۶۸/۲)"}],[1153,"§۱۱۵۳ ۔ جسر بن وہب(1)(4)\nبن سلمہ ازدی: دارقطنی نے موتلف میں ان کا ذکر کیا اور وجیہ بن عمارہ کی سند سے بحوالہ ابو عمارہ بن دجی بن جسر، انہوں نے جسر بن زہران وہ اپنے دادا جسر بن وہب سے روایت کرتے ہیں، فرمایا: میں نے نبی صلی اللہ علیہ وسلم کو ارشاد فرماتے سنا: \"(اللہ کی راہ میں جنگی) گھوڑوں کی پیشانیوں میں قیامت تک خیر و برکت رکھ دی گئی ہے۔\"(2) یہ مجہول سند ہے بقول ابن ماکولا(3) یہ نام جیم کے زیر سے ہے۔","",{"fn":"(1) اسد الغابۃ (۷۴۴)\n(2) مسلم کتاب الزکاۃ باب اثم مانع الزکاۃ (۲۶) ترمذی کتاب فضائل الجہاد باب فضل من ارتبط فرسا فی سبیل اللہ (۱۶۳۶)\n(3) الاکمال (۱۰۰/۲)\n(4) المستدرک (۹۱/۵) المعجم الکبیر (۳۸۵/۲) کنز العمال (۳۵۲۴۴) حلیۃ الاولیاء (۴۳/۳)"}],[1154,"§۱۱۵۴ ۔ جشیب(1)\n(جیم کے زبر، شین نقطوں والا، پھر یا ہے، آخر میں با ہے)\n\nابن ابی عاصم(2) ابن ابی فدیک کے طریق سے بحوالہ جہم بن عثمان، ابن بشیب سے وہ اپنے والد سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: جس نے برکت کی امید سے میرا نام رکھا تو برکت اس کی طرف آ جائے گی اور قیامت تک رہے گی۔ ابن مندہ فرماتے ہیں: اگر یہ جشیب وہی بشیب ہیں جن سے سعید بن سوید نقل کرتے ہیں تو وہ پرانے تابعی ہیں جو سیدنا ابو درداء رضی اللہ عنہ کے اصحاب میں شامل ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۴۵)\n(2) الاحاد والمثانی (۲۷۵/۵)"}],[1155,"§۱۱۵۵ ۔ جُعال بن زیاد\nجحیل میں تذکرہ آئے گا۔"],[1156,"§۱۱۵۶ ۔ جُعال بن سراقہ ضمری غفاری/ثعلبی(1)\nابو موسیٰ نے ان کا ذکر کیا اور اسامہ بن زید بن اسلم کے طریق سے بحوالہ ان کے والد وہ عوف بن سراقہ سے وہ اپنے بھائی سے روایت کرتے ہیں، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا، اس وقت آپ اُحد کی جانب متوجہ تھے: \"مجھے کسی نے کہہ دیا کہ تم کل قتل کر دیئے جاؤ گے\"۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا سارا زمانہ کل آئندہ نہیں؟\"۔ ابو موسیٰ(2) فرماتے ہیں: علماء نے جعال بن سراقہ کا بھی ذکر کیا ہے (لیکن) مجھے معلوم نہیں آیا وہ ای (نام) کی تصغیر ہے یا کوئی اور شخصیت ہے؟\n\nمیں کہتا ہوں: احتمال ہے کہ ان کے بھائی ہوں۔ واقدی مغازی میں عرباض بن ساریہ کی سند سے روایت کرتے ہیں، فرمایا: ہم لوگ غزوہ تبوک میں نبی صلی اللہ علیہ وسلم کے ساتھ تھے تو جعال بن سراقہ اور عبد اللہ بن مغفل نمودار ہوئے۔ پھر ہم تینوں نے آپ کا ساتھ نہیں چھوڑا اس کے بعد وہ قصہ ذکر کیا۔ موسیٰ بن عقبہ غزوہ بنی مصطلق کے واقعہ میں ذکر کر چکے ہیں: اصحاب رسول صلی اللہ علیہ وسلم میں ایک جعال نامی شخص تھے جن کے متعلق گمان ہے کہ وہ بنی ثعلبہ سے تعلق رکھتے تھے اور دوسرے صاحب بنی غفار سے تھے، جن کا نام جحجاہ تھا۔ دونوں کی آوازیں بلند ہوئیں، پھر ایک قصہ ذکر کیا جس میں طوالت ہے۔ مغازی میں ابن اسحاق کا قول ہے: جب شعبان میں نبی صلی اللہ علیہ وسلم نے غزوہ بنی مصطلق کیا جو ۶ ھ کا واقعہ ہے تو مدینہ میں جعال ضمری کو مقرر فرمایا۔ یہ موسیٰ بن عقبہ کے قول کے مخالف ہے کہ وہ غزوہ بنی مصطلق میں ان کے ساتھ تھے۔ دونوں میں جمع کی یہ صورت بنتی ہے کہ انہیں دو شخصیتیں تسلیم کیا جائے۔","",{"fn":"(1) اسد الغابۃ (۷۴۸) الاستيعاب (۳۷۱)\n(2) اسد الغابۃ (۳۲۵/۱) الاستيعاب (۳۳۸/۱)"}],[1157,"§۱۱۵۷ ۔ (ز) جعال الحبشی(1)\nابن شاہین نے اعمش کے طریق سے ایک ضعیف سند سے بحوالہ مجاہد، ابن عمر رضی اللہ عنہما سے روایت کی ہے کہ ایک شخص نبی صلی اللہ علیہ وسلم سے آ کر کہنے لگا: یا رسول اللہ صلی اللہ علیہ وسلم! اس کے متعلق آپ کیا فرماتے ہیں کہ اگر میں آپ کے سامنے قتال کرتے کرتے شہید ہو جاؤں تو میرا رب مجھے جنت میں داخل فرمائے گا اور میری حقارت نہیں کرے گا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں۔ وہ کہنے لگا: میرا پسینہ بدبودار اور میرا رنگ سیاہ ہے، پھر بھی؟ اسی میں ہے(2) کہ وہ شہید ہو گئے۔ ابو موسیٰ انہیں بے نسبت ذکر کرنے کے بعد کہتے ہیں: ہمیں نہیں جانتا آیا یہ وہی یعنی ابن سراقہ ہیں یا کوئی اور؟ ابن الاثیر فرماتے ہیں: بلکہ یہ دوسری شخصیت ہے۔ میں کہتا ہوں: کتاب الانساب میں صفار نے ان کا یوں ذکر کیا ہے، الحبشی جس سے ظاہر ہوتا ہے کہ یہ اور ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۷۴۹)\n(2) اسد الغابۃ (۳۲۵/۱)"}],[1158,"§۱۱۵۸ ۔ (ز) الجعد بن قیس المرادی\nشاعر اور بنی خطیف کے فرد ہیں۔ ابو سعد نیشا پوری نے \"شرف المصطفیٰ\" نامی کتاب میں ان کی حدیث روایت کی ہے، فرماتے ہیں: جعد بن قیس نے فرمایا: اس وقت وہ سو سال کے ہو چکے تھے۔ ہم چار شخص زمانہ جاہلیت میں حج کے ارادے سے نکلے، میمن کی کسی وادی سے ہمارا گزر ہوا، رات ہوئی تو ہم نے وادی کے (جن) سردار کی پناہ طلب کی اور اپنی سواریاں باندھ دیں۔ جب رات تھی اور میرے ساتھی سو گئے تو مجھے وادی کے کونے سے کسی کہنے والے کی آواز آئی: \"اے پڑاؤ کرنے والے سوارو! جب تم مقام حطیم اور زمزم پر کھڑے ہونا تو محمد (صلی اللہ علیہ وسلم) کو جو مبعوث ہوئے ہیں ہماری طرف سے سلام کہہ دینا جو ان کے ساتھ رہے جب بھی وہ چلیں یا (چلنے کا) قصد کریں اور ان سے کہہ دینا ہم آپ کے دین کے مددگار ہیں، اس کی ہمیں مسیح ابن مریم علیہ السلام نے وصیت کی ہے۔\" پھر لمبی حدیث ذکر کی جس میں ان کے اسلام لانے کا قصہ ہے۔"],[1159,"§۱۱۵۹ ۔ جعدہ بن خالد(1)\nبن الصمہ الجشمی۔ امام احمد اور نسائی نے ان کی دو حدیثیں روایت کی ہیں۔ ان میں سے ایک کی سند صحیح ہے ان کی حدیث بصریین میں سے ملتی ہے۔ ابن السکن(2) فرماتے ہیں: بعض لوگوں کا کہنا ہے کہ وہ کوفہ میں فروکش ہوئے۔ ابن قانع نے ان کا نام ابو معاویہ بتایا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۵۰) الاستيعاب (۳۲۰)\n(2) مسند احمد (۴۷۱/۳) عمل الیوم واللیلۃ (۱۰۶۴)"}],[1160,"§۱۱۶۰ ۔ جعدہ بن ہانئ الحضرمی(1)\nابن مندہ محفوظ بن علقمہ کے طریق سے بحوالہ ابن العائذ روایت کرتے ہیں، فرمایا: مجھے مقدام کندی، جعدہ بن ہانی اور ابو عتبہ نے بتایا کہ نبی صلی اللہ علیہ وسلم نے انہیں مدینہ میں ایک نصرانی شخص کو اسلام کی دعوت دینے کے لیے بھیجا، اگر وہ انکار کر دے تو اس کا مال نصفا نصف تقسیم کر دے۔(2)","",{"fn":"(1) اسد الغابۃ (۷۵۱)\n(2) جامع المسانید (۸۶/۳)"}],[1161,"§۱۱۶۱ ۔ جعدہ بن ہبیرہ الاشجعی(1)\nکوفی ہیں۔ یزید ازدی ان سے بحوالہ نبی صلی اللہ علیہ وسلم روایت کرتے ہیں کہ آپ نے فرمایا: \"بہترین لوگ میرے زمانے کے لوگ ہیں\"۔(2) ان کی حدیث ادریس اور داؤد(3) (جو دونوں یزید اوری کے بیٹے ہیں) کے ہاں بحوالہ ان کے والد، ان سے مروی ہے ایسا ہی ابن عبد البر نے جعدہ بن ہبیرہ مخزومی سے علیحدہ ان کا تذکرہ کیا ہے۔ ابن الاثیر فرماتے ہیں: غالب گمان یہی ہے کہ وہ یہی ہیں۔ کیونکہ حدیث کو عبد اللہ بن اوریس نے اپنے والد، اپنے دادا سے بحوالہ جعدہ بن ہبیرہ مخزومی روایت کیا ہے۔\n\nمیں کہتا ہوں: لیکن میں نے نہیں دیکھا جس نے ان کا تذکرہ کیا ہو اس نے انہیں اشجعی کہا ہو۔ ہاں! ابن ابی شیبہ، احمد بن منیع، ابن ابی عاصم بغوی، باوردی، ابن قانع، طبرانی(4) اور حاکم نے جعدہ بن ہبیرہ مخزومی کے سوانح میں نقل کی ہے۔ مصنف ابن ابی شیبہ میں جعدہ بن ہبیرہ بن ابی وہب لکھا ہے وہ یہی مخزومی ہیں، لگتا ہے ابن عبد البر کو انہیں دوسری شخصیت بنانے میں وہم ہوا ہے۔ ابن ابی حاتم(5) نے ذکر کیا کہ ان کے والد نے ان لوگوں سے یہ حدیث وحدان بن جعدہ مخزومی کے سوانح میں بیان کی ہے اور یہ بھی کہا کہ جعدہ تابعی ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۵۲) الاستيعاب (۳۲۹)\n(2) بخاری کتاب الجہاد باب لا یشہد علی شہادۃ جور... (۲۶۵۲) مسلم کتاب فضائل الصحابۃ باب فضل الصحابۃ ثم الذین یلونہم... (۶۴۱۹) ترمذی کتاب المناقب باب ما جاء فی فضل من رأی النبی صلی اللہ علیہ وسلم و صحبہ (۳۸۵۹) ابن ماجہ کتاب الاحکام کراہیۃ الشہادۃ لمن لم یتشہد (۲۳۶۲) مسند احمد (۲۷۷/۴)\n(3) المستدرک (۱۹۱/۳) التاریخ الکبیر (۴۷۱/۲) (۱۰۱/۱) (۱۸۸/۱)\n(4) المعجم الکبیر (۲۸۵/۲)\n(5) الجرح والتعدیل (۵۲۶/۲)"}],[1162,"§۱۱۶۲ ۔ جعدہ بن ہبیرہ(1)\nابن ابی وہب بن عائذ بن عمران بن مخزوم قریشی مخزومی، ان کی والدہ ام ہانی بنت ابی طالب ہیں۔ بلا اختلاف انہیں دیدار نبوی حاصل ہے۔ اس واسطے کہ ان کے والد فتح مکہ کے بعد کافر قتل ہوئے۔ ان کے صحابی اور ان کے سماع کے صحیح ہونے میں اختلاف ہے جسے میں ان شاء اللہ قسم ثانی میں تفصیل سے بیان کروں گا۔","",{"fn":"(1) اسد الغابۃ (۶۵۳) الاستيعاب (۳۲۸)"}],[1163,"§۱۱۶۳ ۔ جعدہ (بے نسبت)\nان کے گھنگھریالے بال تھے اس وجہ سے نبی صلی اللہ علیہ وسلم نے ان کا نام \"جعدہ\" رکھ دیا۔ اسے ابو داؤد طیالسی نے محمد بن عبد اللہ بن حسین بن جعدہ سے بحوالہ ان کے گھر کے کسی فرد سے وہ اپنے دادا جعدہ سے روایت کرتے ہیں۔ ابن ابی حاتم(1) نے اپنے والد کے حوالہ سے ان کا ذکر کیا ہے۔","",{"fn":"(1) الجرح والتعدیل (۵۲۶/۲)"}],[1164,"§۱۱۶۴ ۔ جعشم الخیر بن خلیبہ(1)\nبن شاہی بن موہب الصدفی۔ درخت تلے بیعت کی نعمت ملی ہی ہم نے انہیں اپنی قمیض اور اپنے نعلین پہنے کو دیئے اور اپنے بال بھی عطا کیے۔ انہوں نے آمنہ بنت طلیق بن سفیان بن امیہ سے شادی کی تھی۔ شرید بن مالک نے عکاشہ بن محصن کو شہید کرنے کے بعد انہیں شہید کر دیا۔ یہ فتنہ ارتداد کا دور تھا۔ ایسا ہی ابو عمر نے ذکر کیا ہے۔(2) جہاں تک ابن یونس کا تعلق ہے تو وہ تاریخ مصر میں لکھتے ہیں: وہ فتح مصر میں شریک تھے، اس بنا پر وہ فتنہ ارتداد میں شہید نہیں ہوئے، اس واسطے کہ وہ فتح مصر سے پہلے ہے۔ ابن ماکولہ(3) فرماتے ہیں: شرید بن مالک سے پہلے آمنہ بنت طلیق سے شادی کی۔ یہ صحیح بات کے زیادہ قریب ہے۔ شاید قبلہ تا سے (بجائے قبلہ) لفظی غلطی ہو اور ارتداد میں ضمیر وہم ہو یعنی لفظ قبل قتل بنا کر اس کے ساتھ ضمیر لگا دی گئی۔ [عامر تقی ندوی]","",{"fn":"(1) اسد الغابۃ (۷۵۴) الاستيعاب (۳۸۲)\n(2) اسد الغابۃ (۳۲۶/۱) الاستيعاب (۳۴۲/۱)\n(3) الاکمال (۲۴۷/۱)"}],[1165,"§۱۱۶۵ ۔ جعفر بن ابی الحکم(1)\nبقول بعض جعفر بن عبد اللہ بن ابی الحکم۔ یہ بھی کسی نے کہا ہے کہ وہ صحابی ہیں۔ محمد بن عثمان بن ابی شیبہ \"وحدان میں ان کی ایک روایت بیچی بن جمانی سے بحوالہ عبد اللہ بن جعفر وہ عبد الحکم بن صہیب سے روایت کرتے ہیں، فرمایا: مجھے جعفر بن ابی الحکم نے دیکھا، میں برتن میں سے ادھر اُدھر سے کھا رہا ہوں۔ فرمایا: \"بھتیجے! انہ! ایسے شیطان کھاتا ہے۔ آپ صلی اللہ علیہ وسلم جب کھانا تناول فرماتے تو اپنے سامنے سے اپنا ہاتھ نہ بڑھاتے۔ یہی روایت بخاری(2) نے اپنی تاریخ میں دوسری سند سے عبد اللہ بن جعفر سے بحوالہ عبد الحکم نقل کی کہ انہوں نے جعفر بن عبد اللہ بن ابی الحکم سے یہ روایت سنی ہے، فرماتے ہیں: یہ مرسل روایت ہے۔ جبکہ ابراہیم نے ایک سند سے عبد اللہ بن جعفر سے بحوالہ عبد الحکم انہوں نے جعفر بن ابی الحکم سے نقل کی ہے۔ فرمایا: مجھے حکم بن رافع بن سنان نے دیکھا۔ اگر یہ روایت صحیح ثابت ہو جائے تو جعفر کی صحابیت منفی ثابت ہو گی۔ لیکن چونکہ اس کا راوی نعمان بن شبل ضعیف ہے اس بہر کیف احتمال پھر بھی ہے۔","",{"fn":"(1) اسد الغابۃ (۷۵۵)\n(2) کنز العمال (۱۸۱۷۵) اتحاف السادۃ المتقین (۱۱۷/۷) جامع المسانید (۸۹/۳)"}],[1166,"§۱۱۶۶ ۔ جعفر بن ابی سفیان(1)\nبن حارث بن عبد المطلب بن ہاشم۔ ابن سعد(2) فرماتے ہیں: ان کے گھرانے کے لوگوں کا کہنا ہے کہ وہ حنین میں شریک تھے۔ اور امیر معاویہ رضی اللہ عنہ کا دور پایا ہے اس کے درمیانی عرصہ میں فوت ہوئے۔ ایسا ہی ابن شاہین نے محمد بن یزید سے بحوالہ ان کے رجال سے ذکر کیا اس میں اتنا اضافہ کیا ہے کہ وہ اپنے والد کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کی وفات تک جڑے رہے۔ جبکہ ابو نعیم کا گمان ہے کہ ابن مندہ اس میں منفرد ہیں۔ لیکن ان کا تعاقب ہوا کہ یہ وہم ہے۔ حنین میں ان کے والد ابو سفیان شریک تھے۔ اس بارے میں ابو نعیم کے پاس کوئی دلیل نہیں۔ ابن حبان نے اس پر بھروسا کیا ہے کہ وہ اپنے والد کے ساتھ اسلام لائے، اور حنین میں شریک ہوئے۔ ان کی والدہ حمامہ بنت ابی طالب ہیں اور دمشق میں ۵۰ ھ میں فوت ہوئے۔ جعالنی نے \"جس نے اور اس کے والد نے نبی صلی اللہ علیہ وسلم سے روایت کی\" نامی کتاب میں لکھا ہے: مقام ابواء میں جعفر بن ابی سفیان اور ان کے والد نبی صلی اللہ علیہ وسلم سے ملے اور اسلام لے آئے۔ ان کے والد ابو سفیان کے سوانح میں آئے گا کہ انہوں نے نبی صلی اللہ علیہ وسلم سے ملنے کی اجازت چاہی۔ آپ صلی اللہ علیہ وسلم نے اجازت مرحمت نہ فرمائی، جس پر وہ کہنے لگے: اگر مجھے اجازت نہیں تو میں اپنے بیٹے کو لے کر دور نکل جاؤں گا۔ ابو الیقظان فرماتے ہیں: جعفر کا کوئی بیٹا نہ تھا۔","",{"fn":"(1) اسد الغابۃ (۷۵۸) الاستيعاب (۳۳۲)\n(2) الطبقات الکبریٰ (۳۸/۴)"}],[1167,"§۱۱۶۷ ۔ جعفر بن ابی طالب(1)\nبن عبد المطلب بن ہاشم بن عبد مناف بن قصی، ابو عبد اللہ نبی صلی اللہ علیہ وسلم کے چچا زاد بھائی اور اسلام کی طرف سبقت کرنے والوں میں سے ایک ہیں۔ سیدنا علی رضی اللہ عنہ کے سگے بھائی ہیں۔ ابن اسحاق فرماتے ہیں: پچیس(۲۵) آدمیوں کے بعد اسلام لائے۔ بقول بعض: اکتیس(۳۱) آدمیوں کے بعد۔ نبی صلی اللہ علیہ وسلم نے ان میں اور معاذ بن جبل رضی اللہ عنہ میں رفیق اخوت قائم فرمایا۔ سیدنا ابو ہریرہ رضی اللہ عنہ فرمایا کرتے تھے: نبی صلی اللہ علیہ وسلم کے بعد تمام لوگوں سے افضل جعفر تھے۔ بخاری(2) میں انہی سے مروی ہے، فرمایا: جعفر مساکین کے لیے بہترین انسان تھے۔ خالد اخذ، ابو جعفر روایت کرتے ہیں۔ فرمایا: میں نے سیدنا ابو ہریرہ رضی اللہ عنہ کو فرماتے سنا: میں نے نبی صلی اللہ علیہ وسلم کے بعد جوتے پہنے، سوار ہونے اور پیدل چلنے والوں میں جعفر بن ابی طالب سے بڑھ کر افضل شخص نہیں دیکھا۔ اسے ترمذی(3) اور نسائی نے روایت کیا ہے۔ سند صحیح ہے۔ اور ابن عدی مقبری کی سند سے بحوالہ ابو ہریرہ رضی اللہ عنہ روایت کرتے ہیں، جعفر مساکین سے محبت کرتے ان کے پاس بیٹھتے ان کی خدمت کرتے وہ بھی ان کا کوئی کام کر دیتے یا اسی بنا پر نبی صلی اللہ علیہ وسلم نے انہیں ابو المساکین کی کنیت دی۔ آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"تم شکل و شباہت اور اخلاق میں مجھ جیسے ہو\"۔ اسے امام بخاری اور مسلم(4) نے براء کی حدیث سے روایت کیا اور مسند میں سیدنا علی رضی اللہ عنہ کی مرفوع حدیث ہے: \"مجھے ایسے رفقا دیئے گئے جو شریف ہیں\"۔ ان میں ان کا بھی ذکر کیا۔ انہوں نے حبشہ ہجرت کی تو نجاشی اور ان کے پیروکار ان کے ہاتھ پر شرف با اسلام ہوئے۔ جعفر نے وہیں قیام کیا اس کے بعد مدینہ کی جانب ہجرت کی، آئے تو نبی صلی اللہ علیہ وسلم خیبر میں تھے۔ یہ سب کچھ مغازی میں متعدد صحیح روایات سے ثابت ہے۔ بغوی اور ابن اسکن محمد بن عبد اللہ بن سعید بن عمر کے طریق سے بحوالہ یحییٰ بن سعید، قاسم، وہ سیدہ عائشہ رضی اللہ عنہا سے روایت کرتے ہیں: جب جعفر اور ان کے ساتھی آئے، نبی صلی اللہ علیہ وسلم نے ان کا استقبال کیا اور ان کی پیشانی پر بوسہ دیا۔ ابن اسکن مجاہد کے طریق سے بحوالہ شعیب، عبد اللہ بن جعفر سے روایت کرتے ہیں، میں نے اپنے چچا سیدنا علی رضی اللہ عنہ سے جب کوئی ایسی چیز مانگی جو وہ دے دینا چاہتے تو میں جعفر کا واسطہ دیتا تو وہ مجھے دے دیتے۔ شام کی سرزمین میں بمقام موتہ میں بجاے پیچھے ہٹنے کے آگے بڑھتے ہوئے شہید ہوئے۔ نبی صلی اللہ علیہ وسلم کی حیات میں رومیوں سے جہاد کیا جو جمادی الاولیٰ ۸ ھ کا واقعہ ہے۔ سیدنا علی رضی اللہ عنہ سے دس سال بڑے تھے۔ پورے چالیس پائے صحیح روایت کے مطابق زیادہ عمر پائی۔ ابن اسحاق فرماتے ہیں: مجھے یحییٰ بن عباد بن عبد اللہ بن زبیر نے بحوالہ اپنے والد بتایا، فرمایا: مجھے میرے رضاعی والد نے بتایا: ان کا تعلق بنی مرہ بن عوف سے تھا، اللہ کی قسم! میں گویا اب بھی جعفر بن ابی طالب کو اپنے سرخ زرد رنگ کے گھوڑے پر دیکھ رہا ہوں، وہ جنگ میں گھس پڑے اس کی ٹانگیں کاٹ دیں اس کے بعد آگے بڑھے اور لڑتے لڑتے شہید ہو گئے۔ ابو داؤد(5) نے اسی سند سے نقل کیا ہے۔ ابن اسحاق کہتے ہیں: اسلام میں یہ پہلے شخص ہیں جنہوں نے (جنگ میں) گھوڑے کی ٹانگیں کاٹیں۔ طبرانی(6) نے بحوالہ ابن عمر، نافع کی حدیث روایت کی ہے، فرمایا: میں اس غزوے میں ان کے ساتھ تھا۔ ہم نے جعفر کو بھیڑ میں سے تلاش کیا۔ ہم نے دیکھا کہ ان کے جسم پر سامنے سے نوے سے زائد نیزے اور تیر کے زخم لگے ہوئے ہیں۔ نبی صلی اللہ علیہ وسلم نے فرمایا: \"میں نے جعفر کو ملائکہ کے ساتھ جنت میں پرواز کرتے دیکھا\"۔ اسے طبرانی نے ابن عباس رضی اللہ عنہما کی حدیث سے نقل کیا ہے، نیز طبرانی(7) نے سالم بن ابی الجعد کے طریق سے مروی ہے، نبی صلی اللہ علیہ وسلم کو جعفر دو پروں والے خون آلود فرشتہ کی صورت میں دکھائے گئے، جس کی وجہ یہ ہے کہ جہاد کرتے ہوئے ان کے دونوں بازو کٹ گئے۔ صحیحین میں ابن عمر سے مروی ہے، آپ علیہ السلام جب بھی عبد اللہ بن جعفر کو سلام کرتے تو فرماتے: \"اے ذوالجناحین کے بیٹے! السلام علیک\"۔ دار قطنی نے غرائب میں ضعیف سند سے مالک، نافع بحوالہ ابن عمر رضی اللہ عنہما روایت کی ہے، فرمایا: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے آپ نے آسمان کی طرف اپنا سر اٹھایا اور فرمایا: \"وعلیکم السلام و رحمۃ اللہ و برکاتہ\"۔ لوگوں نے عرض کیا یا رسول اللہ صلی اللہ علیہ وسلم! آپ نے ایسا کیا کیا؟ فرمایا: جعفر ابن ابی طالب فرشتوں کے ہمراہ گزرتے ہوئے مجھے سلام کر رہے تھے\"۔\n\nابو سہل بن زیاد القطان کے فوائد کے جزء رابع میں سعدان بن ولید کے طریق سے بحوالہ عطاء، ابن عباس رضی اللہ عنہما مروی ہے، فرمایا: ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم تشریف فرما تھے اور اسماء بنت عمیس آپ کے پاس ہی تھیں، اچانک آپ نے فرمایا: اے اسماء! ابھی جعفر بن ابی طالب، جبرائیل اور میکائیل کے ساتھ گزرے اور میرے سلام کا جواب دیا۔ (حدیث) اسی میں میں ہے: \"اللہ تعالیٰ نے انہیں دونوں ہاتھوں کے بدلے دو پر عطا کیے ہیں جن سے وہ جہاں چاہتے ہیں پرواز کرتے ہیں\"۔ مغازی میں ابن اسحاق(8) فرماتے ہیں، مجھ سے عبد الرحمن بن قاسم نے بحوالہ اپنے والد، سیدہ عائشہ رضی اللہ عنہا سے روایت کرتے ہیں، فرماتی ہیں: جب جعفر کی وفات کی خبر آئی تو ہم لوگوں نے نبی صلی اللہ علیہ وسلم کے چہرے پر غم کے نمایاں آثار دیکھے۔ سیدنا حسان رضی اللہ عنہ کو جب عبد اللہ بن رواحہ کی شہادت کی اطلاع ملی تو اہل موتہ کا مرثیہ کہتے ہوئے انہوں نے فرمایا:\n\n\"میں نے دیکھا کہ بہترین اہل ایمان گھاٹیوں میں اتر گئے اور میں پیچھے رہ جانے والوں میں چھوڑ دیا گیا۔ اللہ تعالیٰ موتہ میں پے در پے شہید ہونے والوں کو ہرگز (اپنی رحمت سے) دور نہیں کرے گا جن میں ذوالجناحین جعفر، زید اور عبد اللہ تھے جو یکے بعد دیگرے سب شہید ہوئے جبکہ موت کے اسباب پیش آ رہے تھے۔\" نیز اسی قصیدے میں فرماتے ہیں:\n\n\"وہمیں جعفر میں محمد (صلی اللہ علیہ وسلم) سے وفاء اور کام کی مضبوطی نظر آتی جب انہیں کسی کام کا حکم دیا جاتا۔ اسلام میں آل ہاشم کے ہمیشہ سے عزت کے ستون قائم رہیں گے جن پر فخر کیا جائے گا۔","",{"fn":"(1) اسد الغابۃ (۷۵۹) الاستيعاب (۳۳۱)\n(2) بخاری کتاب فضائل الصحابۃ مناقب جعفر بن ابی طالب (۳۷۰۸)\n(3) ترمذی کتاب، باب العنوان و احد (۳۷۶۴)\n(4) بخاری کتاب المغازی باب عمرۃ القضاء (۴۲۵۱)\n(5) ابو داؤد کتاب الجہاد باب الدابۃ تعرقب فی الحرب (۲۵۷۳)\n(6) المعجم الکبیر (۱۰۷/۲)\n(7) المعجم الکبیر (۱۰۹، ۱۰۸/۲)\n(8) بخاری کتاب المغازی باب غزوہ موتۃ من ارض الشام (۴۲۶۴)"}],[1168,"§۱۱۶۸ ۔ (ز) جعفر بن عبد یزید\nبن ہاشم بن عبد المطلب بن عبد مناف قرشی مطلبی۔ رکازہ کے بھائی، سائب بن یزید بن عبد یزید جو امام شافعی رحمہ اللہ کے دادا ہیں ان کے چچا۔ یکی بن سعید اسوی نے مغازی میں ابن اسحاق کے حوالہ سے ذکر کیا ہے کہ نبی صلی اللہ علیہ وسلم نے انہیں خیبر کی کھجوروں میں تیس(۳۰) وسق اور ان کے بھائی رکازہ کو پچاس(۵۰) وسق کھجوریں کھانے کے لیے دیں۔ ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔"],[1169,"§۱۱۶۹ ۔ جعفر بن محمد(1)\nبن مسلمہ انصاری۔ ابن شاہین نے عبد اللہ بن سلیمان بن اشعث کے حوالہ سے ان کا ذکر کیا کہ نبی صلی اللہ علیہ وسلم کے ساتھ رہے اور فتح مکہ اور بعد کے غزوات میں شریک رہے۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۶۱)"}],[1170,"§۱۱۷۰ ۔ (ز) جعونہ بن زیاد الشنی(1)\nابن مندہ نے ان کا ذکر کیا کہ عبد الرحمن بن عمرو بن جبلہ (جو ایک ضعیف راوی ہے) نے بحوالہ عبد اللہ بن زیاد شنی، جبلاس بن زیاد شنی، وہ جعونہ بن زیاد شنی سے، وہ نبی صلی اللہ علیہ وسلم سے کر روایت کرتے ہیں۔ آپ نے فرمایا: \"نام کے بغیر چارہ نہیں (لیکن بے انصاف) نام ظلم جہنم میں ہے\"۔ اس باقی کے رجال مجہول ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۶۳)"}],[1171,"§۱۱۷۱ ۔ (ز) جعونہ بن نضلہ انصاری(2)\nفتوح میں ان کا ذکر آتا ہے ابن جریر نے تاریخ میں اور باوردی نے \"اصحابہ\" میں ابو معروف بن عبد اللہ بن معروف کے طریق سے بحوالہ ابو العوام بن حوشب، محمد بن حسن بن علی بن ابی طالب سے روایت کرتے ہیں کہ سعد بن ابی وقاص نے جب طوائف عراق فتح کیا۔ مسلمان کفار کے ایک نضلہ بن انصار ایک جعونہ بن نضلہ نامی شخص تھے۔ ایک گھاٹی سے گزرے تو نماز کا وقت ہو چکا تھا پھر زریب بن شرقی، عیسیٰ بن مریم علیہ السلام کے وہی کے قصہ کی لمبی حدیث ذکر کی۔ یہ اسناد ضعیف ہے۔ ان شاء اللہ تعالیٰ ہم زریب کے سوانح میں باوردی کے طریق سے قصہ کا بیان ذکر کریں گے۔\n\nابن ابی حاتم(1) کی \"الجرح والتعدیل\" میں لکھا ہے: جعونہ بن نضلہ سعید بن ابی وقاص سے اور ان سے قادہ روایت کرتے ہیں۔ فرمایا: میں نے اپنے والد سے سنا ہے۔ اس قصہ کا ایک طریق متصل بھی ہے لیکن وہ بھی ضعیف ہے، جونا نغ کے طریق سے بحوالہ ابن عمر مروی ہے۔ بحوالہ ابن عمر مروی ہے۔ منصور بن دیبار بحوالہ عبد اللہ بن ابی ذئب سے مروی ہے کہ سعد بن ابی وقاص نے نضلہ بن عمرو انصاری کو روانہ کیا جیسا کہ آ رہا ہے۔","",{"fn":"(1) الجرح والتعدیل (۵۴۰/۲)\n(2) کنز العمال (۴۶۹۷۵) جامع المسانید (۱۰۲/۲)"}],[1172,"§۱۱۷۲ ۔ جُعَیل بن زیاد اشجعی(1)\nبقول بعض ابن ضمر۔ وہ ان کی حدیث نسائی نے صحیح سند سے عبد اللہ بن ابی الجعد کی روایت سے نقل کی ہے، اس میں انہوں نے رسول اللہ صلی اللہ علیہ وسلم کی معیت(2) میں غزوہ میں شرکت کی۔ انہیں جہال بھی کہا گیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۶۴) الاستيعاب (۳۳۴)\n(2) المعجم الکبیر (۲۸۰/۲) دلائل النبوۃ (۱۵۲/۶) کنز العمال (۲۵۳۸۴) جامع المسانید (۱۰۴/۳)"}],[1173,"§۱۱۷۳ ۔ جُعَیل بن سُراقہ ضمری\nجہال بن سراقہ کے سوانح میں ان کے متعلق کچھ گزر چکا ہے۔ ابن اسحاق نے مغازی میں محمد بن ابراہیم تمیمی سے نقل کیا کہ کسی نے عرض کیا یا رسول اللہ صلی اللہ علیہ وسلم! آپ نے عیینہ بن حصن اور اقرع بن حابس کو سو سو (دینار وغیرہ) عطا کیے ہیں اور جعیل کو محروم چھوڑ دیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس ذات کی قسم جس کے قبضہ قدرت میں میری جان ہے! جعیل بن سراقہ پر نظر آنے والے عیینہ اور اقرع جیسوں سے بہتر ہے۔ انہیں ان کا دل بہلا نے کو دیا ہوں اور جعیل کو اس کے ایمان پر چھوڑ دیتا ہوں (ورنہ اس سے بھی ویسا ہی معاملہ کرتا)\"۔ یہ مرسل روایت ہے لیکن اس کا شاہد مرسول روایت ہے۔ روایاتی نے اپنی سند میں اور ابن عبد الحکم نے فتوح مصر میں کبر بن سوادہ کے طریق سے بحوالہ ابو سالم جیشانی، سیدنا ابو ذر الغفاری(1) سے روایت کیا ہے کہ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: جعیل جہنم (مال کے لحاظ سے) کیسا لگتا ہے؟ میں نے عرض کیا: اپنے بیٹے کو لوں کی طرح مسکین ہے، پھر فرمایا: فلاں کے متعلق کیا رائے ہے؟ میں نے عرض کیا: سرداروں میں سے سردار ہے۔ آپ نے فرمایا: \"ان جیسے لوگوں سے زمین بھر جائے پھر بھی جعیل ان سے بہتر ہے\"۔ فرماتے ہیں: میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! فلاں تو ایسا ہی ہے پھر بھی آپ صلی اللہ علیہ وسلم اس سے ایسا سلوک کرتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ اپنی قوم کا سردار ہے، میں اس کی دلجوئی کے لیے ایسا کرتا ہوں\"۔(2)\n\nاس کی سند صحیح ہے جسے ابن حبان نے دوسری سند سے بحوالہ ابو ذر سے نقل کیا ہے لیکن جعیل کا نام نہیں لیا۔ اور بخاری نے سہل بن سعد کی حدیث سے نقل کیا ہے جس میں جعیل اور ابو ذر کو ہم رکھا ہے۔ ابن مندہ یعقوب بن عتبہ بحوالہ عبد الواحد بن عوف، سراقہ سے وہ اپنے والد سے روایت کرتے ہیں، فرمایا: میرے بھائی جعیل کی آنکھ بھی قریظہ کے غزوے میں ضائع ہو گئی۔","",{"fn":"(1) دلائل النبوۃ (۱۸۳/۵) الطبقات الکبریٰ (۱۸۱/۴) کنز العمال (الحدیث: ۳۳۲۳۹)\n(2) دلائل النبوۃ (۱۸۳/۵) حلیۃ الاولیاء (۳۵۲/۱) الطبقات الکبریٰ (۱۸۱/۴) فتح الباری (۸۰/۱) و (۷۲۷/۱۱)"}],[1174,"§۱۱۷۴ ۔ (ز) جُعَیل (بے نسبت)(1)\nابو موسیٰ نے ان میں اور پہلے شخص میں فرق کیا ہے۔ اور مغازی میں ابن اسحاق نے یزید بن رومان سے بحوالہ عمروہ، عبد اللہ بن کعب بن مالک سے نقل کیا ہے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے خندق کی کھدائی کو لوگوں پر تقسیم کر دیا، آپ خود بھی ان کے ساتھ کھدائی میں مشغول تھے۔ ان میں جعیل نامی ایک شخص تھے، آپ صلی اللہ علیہ وسلم نے ان کا نام عمرو رکھا۔ جس پر بعض فی البدیہ بول اٹھے۔ آپ نے ان کا نام جعیل سے عمرو کھدیا اور رنگ دست کے لئے مدد کاون تھا، لوگ جب عمرو کہتے آپ بھی عمرو کہتے اور جب ظہر کہتے آپ بھی ظہر کہتے۔(2)","",{"fn":"(1) اسد الغابۃ (۷۶۱)\n(2) اسد الغابۃ (۳۳۱/۱)"}],[1175,"§۱۱۷۵ ۔ جحشیش بن النعمان الکندی(1)\nابن مندہ نے ان کے والد کا یہی نام لیا ہے۔ فرماتے ہیں: انہیں معدان بھی کہا جاتا ہے۔ کنیت ابو الیقظی تھی۔ جریر بن معدان، بعض نے کہا ہے۔ اور بعض روایات میں جحشیش خا نقطے والی سے لکھا ہے۔ اور یہ اضافہ کیا ہے ہے نقطی حا سے پڑھا جاتا ہے جس کے شروع میں زیر اور پیش کا ذکر کیا ہے یعنی جحشیش۔\n\nابن کلبی و ابن سعد لکھتے ہیں: ان کا نام معدان بن اسود بن معدوی کرب بن شامہ بن اسود ہے۔ ابو عمر بن عبد البر(2) نے لکھا ہے: جعالہ کے طریق سے بحوالہ شعبی مروی ہے کہ اشعث بن قیس نے کہا: ہمارے اور حضری شخص کے درمیان جس کا نام جحشیش تھا زمین کا تنازعہ تھا۔ (حدیث) خبر کی اصل سنن ابو داؤد میں مسلم بن ہیثم کی روایت سے بحوالہ اشعث موجود ہے لیکن جحشیش کا نام نہیں لیا گیا۔\n\nابو عمر نے ابن عون کے طریق سے بحوالہ شعبی، جریر بن معدان سے (جن کا لقب جحشیش تھا) روایت کی کہ انہوں نے ایک شخص سے اپنے تنازع کا فیصلہ رسول اللہ صلی اللہ علیہ وسلم سے کرایا۔ پھر وہ حدیث ذکر کی۔\n\nمیں کہتا ہوں: اس سے ظاہر ہوتا ہے ان کا نام جریر تھا، اور وہ صحابی تھے۔ جبکہ یہ روایت اتنی ہے۔ یہ بھی ممکن ہے: \"ان کا لقب\" جریر کے والد کی طرف ضمیر راجع ہو اور حدیث جریر کی روایت سے بحوالہ ان کے والد مروی ہو۔ جریر نے اس میں ارسال سے کام لیا ہو، میرے نزدیک یہی زیادہ صحیح ہے۔ ابو سعد نیشا پوری نے مسلم بن محارب کے طریق سے بحوالہ سعدی، ابو مالک، ابن عباس رضی اللہ عنہما سے نقل کیا ہے: حضرت موت کے بادشاہ آئے۔ کندہ کا وفد آیا اس میں اشعث بن قیس تھے پھر وہ قصہ ذکر کیا۔ فرماتے ہیں: اسی کے متعلق جحشیش کہتے ہیں: ان کا نام معدان بن اسود کندی تھا۔ پھر رنگ کے اونٹ ہمیں یمن والے دینا تیوں سے تیز لے گئے وہ ہمیں لے کر بلندی کے بعد پستی میں لے اترتے۔ بالآخر ایک جمع کے پاس ہم نے وہ اونٹ جا بٹھائے جن میں صادق امین رہنما رسول تھے۔ طبرانی(3) نے صالح بن یحییٰ کے طریق سے بحوالہ جحشیش کندی روایت کیا ہے، فرمایا: کندہ کی ایک جماعت رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی، کہنے لگی: آپ ہمارے خاندان سے ہیں اور اس کا دعویٰ کرنے لگے۔ آپ نے فرمایا: \"تم لوگ ہم (عربوں) سے اپنی نفی نہ کرو اور ہم اپنے باپ دادا سے اپنی نفی نہیں کرتے\"۔\n\nان کی ایک اور طریق سے بحوالہ صالح روایت ہے: ہم سے جحشیش نے بیان کیا \"جو غلط ہے اس واسطے کہ انہوں نے ان کا دور نہیں پایا۔ حدیث کی اصل مسند احمد(4) میں مسلم بن ہیثم کی روایت سے بحوالہ اشعث موجود ہے۔ فرمایا: میں کندہ کی ایک جماعت کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا۔ اس میں جحشیش کا ذکر نہیں۔ ابو عمر نے عمران بن موسیٰ بن طلحہ سے بحوالہ جحشیش اسی روایت کو نقل کیا ہے، وہ مرسل ہے۔ ابن کلبی نے اسے بغیر سند روایت کر کے کہا: انہوں نے یہ بات تین بار کہی، تیسری بار میں آپ نے جواب دیا۔ اس پر اشعث نے اس سے کہا: اللہ تمہارے دانت گرا دے تم پر تم کیوں خاموش نہ ہوئے۔ فرمایا: جحشیش ہی فتنہ ارداد کے زمانہ میں کہتے ہیں: \"ہم رسول اللہ صلی اللہ علیہ وسلم کے فرمانبردار ہیں جب وہ صادق موجود تھے۔ تعجب ہے ابو بکر کو بادشاہی مل گئی\"۔\n\nمیں کہتا ہوں: کامل میں ہمزہ نے یہ بیت طیبہ کے حوالہ سے پڑھی ہے اس میں صادق کی جگہ حاضر ہے۔ اور عجباً کی جگہ لھفاً ہے۔ عمر بن شبہ نے ذکر کیا کہ جحشیش کندہ ان لوگوں میں سے تھے جو مرتد ہو گئے گرفتاری کے بعد قید کر کے انہیں باندھ کر قتل کر دیا گیا۔ اگر یہ روایت صحیح ہے تو پھر وہ صحابی نہیں۔ جتنے بھی لوگوں نے ان سے روایت کی وہ مرسل ہی ہے۔ اس واسطے کہ انہوں نے یزید مانیں پایا۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۷۶۷) الاستيعاب (۲۸۰)\n(2) الاستيعاب (۳۴۱/۱)\n(3) المعجم الکبیر (۲۸۵/۲، ۲۸۶) المعجم الصغیر (۸۰/۱)\n(4) مسند احمد (۲۱۱/۵)"}],[1176,"§۱۱۷۶ ۔ جفینہ الجہنی(1)\nبقول بعض نہدی اور شمالی، ابن ابی حاتم(2) بحوالہ اپنے والد، بغوی طبرانی(3) ابو بکر زاہری کے طریق سے بحوالہ عثمان، ابو اسحاق سے وہ غریرہ سے وہ ضمیرہ سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے ان کی طرف ایک خط بھیجا، جس سے انہوں نے اپنا ڈول مرمت کر لیا۔ اس پر ان کی بیٹی کہنے لگی: آپ نے عرب کے سردار کے خط سے (جو چہرے پر لکھا تھا) اپنا ڈول مرمت کر لیا ہے؟ تو مارے خوف کے وہ بھاگ نکلے، اپنا تصور ابہت مال سمیت لے یا بعد میں مسلمان ہو کر آگئے۔ نبی صلی اللہ علیہ وسلم نے ان سے فرمایا: \"دیکھو! صحوب کی تقسیم سے پہلے تمہیں جو اپنا سامان نظر آئے وہ لے لو\"۔ بغوی فرماتے ہیں ڈوری کی حدیث میں مکرر روایت ہے۔ اور ابو بکر زاہری ضعیف الحدیث شخص ہے۔\n\nمیں کہتا ہوں: یہ حدیث ہمیں فوائد یہودی کے جزء ثانی میں عالی سند سے ملی ہے اور اسے اسرائیل نے روایت کیا ہے جو ابو اسحاق کے متعلق ابو اسحاق سے روایت کرنے میں سب سے مستند ہیں وہ بحوالہ شعبی روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے رعیہ یعنی کو خط لکھا۔۔۔۔ پھر طوالت سے اس کا ذکر کیا جس کا شاہد حامد بن سلمیٰ بحوالہ حجاج بن ارطاۃ، ابو اسحاق سے مروی روایت ہے۔ البتہ انہوں نے بحوالہ رعینہ کہی کہا: رعینہ کا ذکر نہیں کیا۔ ان شاء اللہ تعالیٰ حرف راء میں درست نام آئے گا۔","",{"fn":"(1) اسد الغابۃ (۷۶۸) الاستيعاب (۲۷۳)\n(2) الجرح والتعدیل (۵۵/۲)\n(3) المعجم الکبیر (۲۸۹/۲)"}],[1177,"§۱۱۷۷ ۔ جلاس بن سوید(1)\nبن حاصمت انصاری۔ پہلے منافقوں سے میل جول تھا پھر توبہ کر لی اور اچھے طریقے سے توبہ کی۔ یکی بن سعید اموی اپنے مغازی میں لکھتے ہیں: ہمیں محمد بن اسحاق نے بحوالہ زہری، عبد الرحمن بن عبد اللہ بن کعب بن مالک سے وہ اپنے والد وہ اپنے دادا سے روایت کرتے ہیں، فرمایا: جب رسول اللہ صلی اللہ علیہ وسلم آئے تو میرے پاس میری قوم آ کر کہنے لگی: تم ایک شاعر آدمی ہو اگر رسول اللہ صلی اللہ علیہ وسلم سے کچھ حضرت کرنا چاہو تو کر لو۔ پھر کعب بن مالک کی توبہ والی لمبی حدیث ذکر کی۔ جس میں کہا کہ منافقوں میں پیچھے رہ جانے والوں میں جلاس بن سوید بن صامت بھی تھے، جن کے متعلق قرآن نازل ہوا۔ امام عمیر بن سعد ان کی زوجیت میں تھی۔ اور عمیر ان کی پرورش میں تھے۔ ایک دن انہوں نے سن لیا کہ یہ کہہ رہے تھے کہ اگر محمد صلی اللہ علیہ وسلم سچے ہیں تو ہم لوگ گدھوں سے بدتر ہیں۔ پھر وہ قصہ ذکر کیا جو ان دونوں کے درمیان پیش آیا۔ اور اس آیت کا نازل ہونا: \"وہ اللہ کی قسمیں کھاتے ہیں کہ ہم نے یہ بات کی۔۔۔۔ پس اگر وہ توبہ کر لیں یہ ان کے لیے بہتر رہے گا\" (سورۃ التوبہ: ۷۴) تک۔ تو لوگوں نے سمجھا کہ جلاس نے توبہ کر لی اور ان کی توبہ اچھی رہی۔\n\nمیں کہتا ہوں: جلاس کی توبہ کے قصہ کو امام موسیٰ کعب کی توبہ کے قصہ میں شامل کر دیا ہے جبکہ کعب کی حدیث اس سے پہلے ختم ہو چکی ہے۔ ابن ہشام نے صرف کعب کے قصہ پر اکتفا کیا ہے جلاس کا قصہ ذکر نہیں کیا۔ اوحد واقدی نے یہ قصہ عبد الحمید بن جعفر سے بحوالہ ان کے والد و طویل ذکر کیا ہے جس کے آخر میں ہے: جلاس نے توبہ کر لی اور ان کی توبہ اچھا رنگ لائی۔ اور جو جلاس کی وہ تحریر کرتے تھے اس سے ہاتھ نہیں کھینچا۔ جس سے ان کی توبہ کی پہچان ہوئی۔ عذری نے نقل کیا ہے کہ جلاس کی وہی ہیں جنہوں نے اپنے والد سوید بن صامت کے بدلے میں جبز بن زید کو قتل کر دیا تھا۔ لیکن صحیح یہ ہے کہ جبز کا قاتل حارث بن سوید تھا (جو مرتد ہو گیا تھا پھر فتح مکہ کے موقع پر اسلام لائے آپ نے انہیں جبز کے قصاص میں قتل کرا دیا تھا) جیسا کہ آ رہا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۶۹) الاستيعاب (۲۵۴)"}],[1178,"§۱۱۷۸ ۔ (ز) جلاس بن صلیت الیربوعی(1)\nابن اسکن اور ابن شاہین نے عبد الرحمن بن عمرو بن جبلہ کے طریق سے بحوالہ مرام بنت مقفع صلیحہ روایت کیا ہے کہ امام مقنع بنت جلاس بن صلیت یہ جو یہ اپنے والد سے روایت کرتی ہیں، انہوں نے فرمایا میں نے عرض کیا یا رسول اللہ صلی اللہ علیہ وسلم میں مالدار خطرات اور رشتہ داروں والا شخص ہوں، میرے آباء اجداد اس مقام تک پہنچے کہ انہوں نے آگ جلائی دختر خوان بچھائے یہ کیا اور وہ کیا، کیا انہیں یہ سب کام فائدہ دیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں۔ انہوں نے کہا: پھر آپ نے ہمارے سوالی میں سے ایک نوجوان کو ہمارا امیر مقرر کیا جو اللہ کی کتاب زیادہ پڑھتا تھا۔ فرماتے ہیں: جلاس کی اولاد نے اسلام میں عظیم کارنامہ سر انجام دیا ابن مندہ نے اسی سند سے بحوالہ جلاس تعلیقاً نقل کیا ہے کہ وہ نبی صلی اللہ علیہ وسلم کے پاس آئے اور آپ سے وضو کے متعلق پوچھا، آپ نے فرمایا: ایک مرتبہ اور دو مرتبہ وضو کر لینا کافی ہے۔ فرماتے ہیں: میں نے آپ کو ایک عضو تین بار دھوتے دیکھا۔(2) ابن مندہ کہتے ہیں: اجنبی روایت ہے کہ جو اسی سند سے مشہور ہے۔ عبد الرحمن حدیث میں قائل ترک شخصیت ہے۔\n\nمیں کہتا ہوں: لفظ مرار کو میں نے ابن شاہین اور ابن اسکن کی کتاب کے متند نسخہ میں پیش تخفیف اور آخر میں دال سے لکھا ہوا اور ان کے علاوہ کتابوں میں را سے لکھا دیکھا۔ واللہ اعلم","",{"fn":"(1) اسد الغابۃ (۷۷۰)\n(2) کنز العمال (۲۶۸۹۸)"}],[1179,"§۱۱۷۹ ۔ جُلاس بن عمرو الکندی(1)(2)\nبغوی نے علی بن ترین کے طریق سے بحوالہ یزید بن ہلال، اپنے والد ہلال بن قطبہ سے روایت کیا ہے، فرمایا: میں نے جلاس بن عمرو سے سنا کہ میں اپنی قوم کی جماعت میں کندہ سے رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا۔ جب ہم واپس آنے لگے، ہم نے عرض کیا اللہ کے رسول! ہمیں کوئی وصیت فرمائیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہر کوشش کرنے والے کی ایک انتہا ہوتی ہے اور انسان کی آخری حد موت ہے\"۔ (حدیث) علی بن قرین تو بہت ضعیف راوی ہے جبکہ اس سے اوپر کے راوی غیر معروف ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۷۱)\n(2) کنز العمال (۴۲۱۳۱) مسند ابن شہاب (۱۰۲۵)"}],[1180,"§۱۱۸۰ ۔ جُلَیبیب (بے نسبت جلباب کی تصغیر)(1)\nامام مسلم(2) نے حمادی حدیث سے، بحوالہ ثابت، کتانہ بن نعیم، ابو برزہ اسلمی سے نقل کیا کہ نبی صلی اللہ علیہ وسلم کسی غزوے میں تھے جس میں اللہ تعالیٰ نے آپ کو بغیر جنگ سامان دیا۔ اس موقع پر آپ نے فرمایا: تم کسی کو گم پاتے ہو؟ لوگوں نے عرض کیا: فلاں فلاں شخص نہیں ہیں۔ آپ نے فرمایا: \"لیکن مجھے جلیبیب نظر نہیں آ رہا\"۔ پھر وہ حدیث ذکر کی۔(3) نسائی نے اسے نقل کیا ہے۔ سیدنا انس رضی اللہ عنہ کی حدیث میں بھی ان کا ذکر ہے جس میں ایک انصاری عورت سے ان کی شادی کرانے کا ذکر ہے، جس میں آپ صلی اللہ علیہ وسلم کا ارشاد ہے: \"لیکن تم اللہ تعالیٰ کے ہاں کچھ لے تو نہیں\"۔ جو برقانی کے ہاں ابو برزہ کی حدیث میں ان کے اخراج میں ہے۔ امام احمد نے اسے طویل ذکر کیا ہے۔ حدیث انس بہادر نے عبد الرزاق کے طریق سے بحوالہ معمر، ثابت نے ان سے طویل ذکر کی ہے۔ اور امام احمد اور محمد نے عبد الرزاق سے اور ابن عبد البر نے ان کے سوانح میں نقل کیا ہے کہ ان کے متعلق یہ آیت نازل ہوئی:\n\n\"کسی مسلمان مرد اور عورت کے لئے اس کی گنجائش نہیں کہ جب اللہ تعالیٰ اور اس کا رسول کسی کام کا فیصلہ کر دیں تو پھر انہیں کسی قسم کا اختیار باقی ہو\"۔ (سورۃ الاحزاب: ۳۶)\n\nبعض یہ بات حدیث انس کے کسی موصول طریق میں نہیں ملی اور نہ حدیث ابی برزہ میں اس کا ذکر ہے۔","",{"fn":"(1) اسد الغابۃ (۷۷۲) الاستيعاب (۳۶۶/۱)\n(2) مسلم کتاب فضائل الصحابۃ باب من فضائل جلیبیب (۳۸۰۸)\n(3) مسند احمد (۱۶۱/۳)"}],[1181,"§۱۱۸۱ ۔ جُلَیحہ بن عبد اللہ(1)\nبن محارب، ابن ناشب بن ثعیرہ بن سعد بن لیث، بن بکر بن عبد مناة لیشی۔ ابن اسحاق اور واقدی نے شہداء طائف(2) میں ان کا ذکر کیا ہے۔ ان کے دادا کا نام بعض نے محارب کی بجائے حارث ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۷۳) الاستيعاب (۳۸۱)\n(2) المعجم الکبیر (۲۷۵/۲)"}],[1182,"§۱۱۸۲ ۔ جلیحہ بن شجار العافقی"],[1183,"§۱۱۸۳ ۔ جمانہ الباہلی(1)\nابو الحج ازدی نے صحابہ میں ان کا ذکر کیا ہے اور بکر بن خمیس کے طریق سے بحوالہ عاصم بن حمانہ باہلی نقل کیا، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے جب موسیٰ علیہ السلام کو فرعون کے لیے بددعا کی اجازت دے دی تو فرشتے آمین کہتے تھے۔ (حدیث)(2) اسی میں مجاہدین کی فضیلت کا ذکر ہے۔ ابو موسیٰ نے اپنے استدراک میں ان کا تذکرہ کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۷۴)\n(2) کنز العمال (۱۰۶۶۵) الاتحافات السنیۃ (۲۵۲) جامع المسانید (۱۰۹/۲)"}]])